CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_bar_usable_v2(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE k text; o numeric; h numeric; l numeric; c numeric;
BEGIN
 FOREACH k IN ARRAY ARRAY['o','h','l','c','v'] LOOP
  IF jsonb_typeof(v->k) IS DISTINCT FROM 'number' THEN RETURN false; END IF;
 END LOOP;
 o:=(v->>'o')::numeric;h:=(v->>'h')::numeric;l:=(v->>'l')::numeric;c:=(v->>'c')::numeric;
 RETURN o>0 AND h>0 AND l>0 AND c>0 AND (v->>'v')::numeric>=0 AND h>=GREATEST(o,c,l) AND l<=LEAST(o,c,h);
EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_breadth_project_page_v2(p_task_id text, p_page_no integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; p astra_ingestion_v1.backfill_pages_v2;
 v_row jsonb; v_day date; v_month date; v_member text; v_symbol text; v_ordinal integer:=0; v_raw numeric; v_adjusted numeric;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF t.family<>'D03' OR lower(t.provider)<>'derived' THEN RETURN 0; END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_breadth_projected_pages_v2 WHERE task_id=t.id AND page_no=p_page_no) THEN RETURN 0; END IF;
 SELECT * INTO STRICT p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=t.id AND page_no=p_page_no;
 IF jsonb_array_length(t.scope->'member_ids')<>1 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Daily return projection requires one frozen company'; END IF;
 v_member:=t.scope#>>'{member_ids,0}';v_month:=astra_ingestion_v1.backfill_date_v2(t.scope->>'source_month');
 FOR v_row IN SELECT value FROM jsonb_array_elements(COALESCE(p.raw_body::jsonb->'rows','[]')) LOOP
  v_ordinal:=v_ordinal+1;v_day:=astra_ingestion_v1.backfill_date_v2(v_row->>'market_date');v_symbol:=v_row->>'symbol';
  IF v_row->>'member_id' IS DISTINCT FROM v_member OR v_day IS NULL OR length(COALESCE(v_symbol,''))=0
   OR v_day<'2025-09-01'::date OR v_day>'2026-07-31'::date
   OR (v_month IS NOT NULL AND date_trunc('month',v_day)::date<>v_month) THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='D03 projection member/date differs from its immutable workflow scope'; END IF;
  v_raw:=CASE WHEN jsonb_typeof(v_row#>'{values,raw_ret_1d}')='number' THEN (v_row#>>'{values,raw_ret_1d}')::numeric END;
  v_adjusted:=CASE WHEN jsonb_typeof(v_row#>'{values,adjusted_ret_1d}')='number' THEN (v_row#>>'{values,adjusted_ret_1d}')::numeric END;
  INSERT INTO astra_ingestion_v1.backfill_breadth_inputs_v2(run_id,member_id,market_date,source_month,symbol,task_id,page_no,record_ordinal,
   raw_ret_1d,adjusted_ret_1d,raw_null_reason,adjusted_null_reason,formula_version,body_sha256,source_committed_at,identity_input_attribution)
  VALUES(t.run_id,v_member,v_day,date_trunc('month',v_day)::date,v_symbol,t.id,p.page_no,v_ordinal,v_raw,v_adjusted,
   CASE WHEN v_raw IS NULL THEN COALESCE(v_row#>>'{null_reasons,raw_ret_1d}','MISSING_OR_NON_NUMERIC_D03_INPUT') END,
   CASE WHEN v_adjusted IS NULL THEN COALESCE(v_row#>>'{null_reasons,adjusted_ret_1d}','MISSING_OR_NON_NUMERIC_D03_INPUT') END,
   COALESCE(v_row->>'formula_version',p.adapter_version),p.body_sha256,p.committed_at,v_row->'identity_input_attribution');
 END LOOP;
 IF v_ordinal<>p.record_count THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='D03 compact projection count differs from retained receipt'; END IF;
 INSERT INTO astra_ingestion_v1.backfill_breadth_projected_pages_v2(task_id,page_no,run_id,source_month,body_sha256,projected_records)
 VALUES(t.id,p.page_no,t.run_id,v_month,p.body_sha256,v_ordinal);
 RETURN v_ordinal;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_breadth_ready_v2(p_task_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; v_month text; v_count integer;
BEGIN
 SELECT * INTO t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF NOT FOUND OR t.kind<>'derive_breadth' OR t.family<>'CTX06' THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_plan_manifests_v2 WHERE run_id=t.run_id)
  OR NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=t.run_id AND metadata->'planning_complete'='true'::jsonb) THEN RETURN false; END IF;
 v_month:=t.scope->>'source_month';
 IF v_month IS NULL OR v_month !~ '^\d{4}-\d{2}-01$' OR t.scope->>'target_start' IS DISTINCT FROM t.scope->>'target_end' THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 d WHERE d.run_id=t.run_id AND d.family='D03' AND d.scope->>'source_month'=v_month
  AND d.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED')) THEN RETURN false; END IF;
 SELECT count(DISTINCT d.scope#>>'{member_ids,0}') INTO v_count FROM astra_ingestion_v1.backfill_tasks_v2 d
  WHERE d.run_id=t.run_id AND d.family='D03' AND d.scope->>'source_month'=v_month AND jsonb_array_length(d.scope->'member_ids')=1;
 IF v_count<>3000 THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 d JOIN astra_ingestion_v1.backfill_pages_v2 p ON p.task_id=d.id
  WHERE d.run_id=t.run_id AND d.family='D03' AND d.scope->>'source_month'=v_month
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_breadth_projected_pages_v2 b WHERE b.task_id=p.task_id AND b.page_no=p.page_no AND b.body_sha256=p.body_sha256)) THEN RETURN false; END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_admit_page_v2(p_task text, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '12s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;r astra_ingestion_v1.backfill_runs_v2;e astra_ingestion_v1.backfill_contract_enumeration_v2;
 rows jsonb;syms jsonb;scope jsonb;child_id text;grp integer;children integer:=0;linked integer;unlinked integer;
 a timestamptz:='2025-09-01T00:00:00-04:00';b timestamptz:='2026-07-31T23:59:59-04:00';
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t.run_id,706314020261099));
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=t.run_id;
 IF r.status<>'ACTIVE' OR r.fence<>t.run_fence THEN RETURN jsonb_build_object('state','RUN_FENCE_NOT_ACTIVE');END IF;
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_state_v2 WHERE run_id=t.run_id AND seed_complete) THEN RETURN jsonb_build_object('state','RETAINED_CHILD_RECONCILIATION_PENDING');END IF;
 SELECT * INTO STRICT e FROM astra_ingestion_v1.backfill_contract_enumeration_v2 WHERE task_id=p_task AND page_no=p_page FOR UPDATE;
 IF e.processed_at IS NOT NULL THEN RETURN jsonb_build_object('state','ALREADY_LINKED');END IF;
 IF t.kind<>'alpaca_option_contracts' OR NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=p_task AND page_no=p_page) THEN RETURN jsonb_build_object('state','INDEPENDENT_READBACK_PENDING');END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('ordinal',x.record_ordinal,'symbol',x.source_row->>'symbol','underlying',x.source_row->>'underlying_symbol',
  'eligible',COALESCE(x.source_row->>'symbol' ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' AND (t.scope->'symbols') ? (x.source_row->>'underlying_symbol'),false))),'[]') INTO rows
 FROM astra_ingestion_v1.backfill_page_rows_v2(t.id,p_page) x;
 FOR syms,grp IN
  SELECT jsonb_agg(symbol ORDER BY symbol),g FROM(SELECT symbol,((row_number() OVER(ORDER BY symbol)-1)/100)::int g FROM(
   SELECT DISTINCT x->>'symbol' symbol FROM jsonb_array_elements(rows) x WHERE x->'eligible'='true'::jsonb
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_work_v2 w WHERE w.run_id=t.run_id AND w.work_key=astra_ingestion_v1.backfill_contract_key_v2(x->>'symbol',a,b,'opra','1Day'))
  ) unique_symbols) numbered GROUP BY g
 LOOP
  scope:=jsonb_build_object('symbols',syms,'member_ids',t.scope->'member_ids','start','2025-09-01T00:00:00-04:00','end','2026-07-31T23:59:59-04:00',
   'identity_status','PROVIDER_CONTRACT_UNDERLYING_LINK','enumeration_parent',t.id,'contract_registry_version','fixed3000-contract-work-v2');
  child_id:='backfill-contract-'||encode(sha256(convert_to(jsonb_build_array(t.run_id,syms,extract(epoch FROM a),extract(epoch FROM b),'opra','1Day')::text,'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
  VALUES(child_id,t.run_id,'CTX02','Alpaca','alpaca_option_bars',scope,t.priority+1,t.run_fence);
  children:=children+1;
 END LOOP;
 INSERT INTO astra_ingestion_v1.backfill_contract_parent_links_v2(run_id,parent_task_id,page_no,record_ordinal,contract_symbol,underlying_symbol,work_key,task_at_admission)
 SELECT t.run_id,t.id,p_page,(x->>'ordinal')::bigint,x->>'symbol',x->>'underlying',w.work_key,w.canonical_task_id
 FROM jsonb_array_elements(rows) x JOIN astra_ingestion_v1.backfill_contract_work_v2 w
  ON w.run_id=t.run_id AND w.work_key=astra_ingestion_v1.backfill_contract_key_v2(x->>'symbol',a,b,'opra','1Day') WHERE x->'eligible'='true'::jsonb ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS linked=ROW_COUNT;
 SELECT count(*) INTO unlinked FROM jsonb_array_elements(rows) x WHERE x->'eligible'<>'true'::jsonb;
 UPDATE astra_ingestion_v1.backfill_contract_enumeration_v2 SET processed_at=clock_timestamp(),linked_contracts=linked,unlinked_source_contracts=unlinked WHERE task_id=t.id AND page_no=p_page;
 UPDATE astra_ingestion_v1.backfill_contract_state_v2 SET parent_contract_links=parent_contract_links+linked,new_children_created=new_children_created+children,
  enumeration_pages_processed=enumeration_pages_processed+1,unlinked_source_contracts=unlinked_source_contracts+unlinked WHERE run_id=t.run_id;
 RETURN jsonb_build_object('state','CONTRACT_WORK_LINKED','new_children',children,'linked_source_contracts',linked,'unlinked_source_contracts',unlinked,
  'preexisting_children_preserved',true,'historical_enumeration_completeness_certified',false);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_prove_child_v2(p_task text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;v record;passed boolean;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 IF t.kind<>'alpaca_option_bars' THEN RETURN false;END IF;
 SELECT count(*) n,COALESCE(sum(actual_records),0) records,min(page_no) first_page,max(page_no) last_page INTO v
  FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=t.id;
 passed:=t.status IN('INGESTED','NO_DATA_RETURNED','IDENTITY_OR_QUALITY_UNRESOLVED') AND t.cursor IS NULL
  AND t.page_no>0 AND v.n=t.page_no AND v.first_page=0 AND v.last_page=t.page_no-1;
 INSERT INTO astra_ingestion_v1.backfill_contract_child_proofs_v2(task_id,run_id,task_pages,verified_pages,verified_records,query_complete)
 VALUES(t.id,t.run_id,t.page_no,v.n,v.records,COALESCE(passed,false)) ON CONFLICT(task_id) DO UPDATE SET task_pages=EXCLUDED.task_pages,
  verified_pages=EXCLUDED.verified_pages,verified_records=EXCLUDED.verified_records,query_complete=EXCLUDED.query_complete,checked_at=clock_timestamp();
 RETURN COALESCE(passed,false);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_readback_v2(p_task text, p_page integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 IF t.kind NOT IN('alpaca_option_bars','alpaca_option_contracts') THEN RETURN;END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t.run_id,706314020261099));
 IF t.kind='alpaca_option_bars' THEN PERFORM astra_ingestion_v1.backfill_contract_register_child_v2(t.id);
 ELSE PERFORM astra_ingestion_v1.backfill_contract_enqueue_v2(t.id,p_page);
  PERFORM astra_ingestion_v1.backfill_contract_admit_page_v2(t.id,p_page);END IF;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_register_child_v2(p_task text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;s text;k text;a timestamptz;b timestamptz;feed text;frame text;
 n integer:=0;v_added integer;v_windows integer:=0;candidate_complete boolean;prior record;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 IF t.kind<>'alpaca_option_bars' OR t.provider<>'Alpaca' THEN RETURN 0;END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t.run_id,706314020261099));
 INSERT INTO astra_ingestion_v1.backfill_contract_state_v2(run_id) VALUES(t.run_id) ON CONFLICT DO NOTHING;
 candidate_complete:=astra_ingestion_v1.backfill_contract_prove_child_v2(t.id);
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_registered_children_v2 WHERE task_id=t.id) THEN
  IF candidate_complete THEN
   UPDATE astra_ingestion_v1.backfill_contract_work_v2 w SET canonical_task_id=t.id
    FROM astra_ingestion_v1.backfill_contract_child_links_v2 l
    WHERE l.task_id=t.id AND w.run_id=l.run_id AND w.work_key=l.work_key AND w.canonical_task_id<>t.id
     AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_child_proofs_v2 p WHERE p.task_id=w.canonical_task_id AND p.query_complete);
  END IF;
  RETURN 0;
 END IF;
 a:=astra_ingestion_v1.backfill_stamp_v2(t.scope->>'start');b:=astra_ingestion_v1.backfill_stamp_v2(t.scope->>'end');
 feed:=COALESCE(t.scope->>'feed','opra');frame:=COALESCE(t.scope->>'timeframe','1Day');
 IF a IS NULL OR b IS NULL OR a>=b OR feed<>'opra' OR frame<>'1Day' OR jsonb_typeof(t.scope->'symbols')<>'array' THEN
  RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Existing option child scope cannot be safely registered';END IF;
 FOR s IN SELECT DISTINCT value FROM jsonb_array_elements_text(t.scope->'symbols') WHERE value ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' LOOP
  k:=astra_ingestion_v1.backfill_contract_key_v2(s,a,b,feed,frame);
  INSERT INTO astra_ingestion_v1.backfill_contract_work_v2 VALUES(t.run_id,k,'Alpaca',s,a,b,feed,frame,t.id) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_added=ROW_COUNT;v_windows:=v_windows+v_added;
  IF v_added=0 AND candidate_complete THEN
   SELECT w.canonical_task_id,COALESCE(p.query_complete,false) complete INTO prior FROM astra_ingestion_v1.backfill_contract_work_v2 w
    LEFT JOIN astra_ingestion_v1.backfill_contract_child_proofs_v2 p ON p.task_id=w.canonical_task_id WHERE w.run_id=t.run_id AND w.work_key=k;
   -- A better retained receipt can be referenced without cancelling or changing
   -- the previous child, including any running lease or incomplete cursor.
   IF NOT prior.complete THEN UPDATE astra_ingestion_v1.backfill_contract_work_v2 SET canonical_task_id=t.id WHERE run_id=t.run_id AND work_key=k;END IF;
  END IF;
  INSERT INTO astra_ingestion_v1.backfill_contract_child_links_v2(run_id,work_key,task_id) VALUES(t.run_id,k,t.id) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_added=ROW_COUNT;n:=n+v_added;
 END LOOP;
 INSERT INTO astra_ingestion_v1.backfill_contract_registered_children_v2(task_id,run_id,scope_sha256)
  VALUES(t.id,t.run_id,encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(t.scope),'UTF8')),'hex'));
 UPDATE astra_ingestion_v1.backfill_contract_state_v2 SET registered_windows=registered_windows+v_windows,registered_child_links=registered_child_links+n WHERE run_id=t.run_id;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_delivery_dispatch_v2(p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_result jsonb; v_verified jsonb; v_finalize jsonb;
BEGIN
 IF p_operation='backfill_delivery_status' THEN RETURN astra_ingestion_v1.backfill_delivery_status_v2(p_payload->>'run_id');
 ELSIF p_operation='backfill_status' THEN
  RETURN astra_ingestion_v1.backfill_dispatch_v2(p_operation,p_payload)||jsonb_build_object('delivery',astra_ingestion_v1.backfill_delivery_status_v2(p_payload->>'run_id'));
 ELSIF p_operation='backfill_finalize' THEN RETURN astra_ingestion_v1.backfill_try_finalize_v2(p_payload->>'run_id');
 ELSIF p_operation='backfill_recover' THEN RETURN astra_ingestion_v1.backfill_recover_v2(p_payload);
 ELSIF p_operation='backfill_maintain' THEN RETURN astra_ingestion_v1.backfill_maintain_v2(COALESCE((p_payload->>'limit')::integer,2));
 ELSIF p_operation='backfill_plan_snapshot' THEN RETURN astra_ingestion_v1.backfill_plan_snapshot_v2(p_payload->>'run_id',COALESCE((p_payload->>'limit')::integer,500));
 ELSIF p_operation='backfill_seal_plan' THEN RETURN astra_ingestion_v1.backfill_seal_plan_v2(p_payload->>'run_id',(p_payload->>'expected_task_count')::bigint,p_payload->>'expected_plan_sha256',p_payload->'workflow_plan');
 ELSIF p_operation='backfill_verify' THEN
  v_result:=astra_ingestion_v1.backfill_dispatch_v2(p_operation,p_payload);
  IF v_result->>'state'='committed' THEN
   v_verified:=astra_ingestion_v1.backfill_recheck_page_v2(v_result->>'task_id',(v_result->>'page_no')::integer);
   v_finalize:=astra_ingestion_v1.backfill_try_finalize_v2(p_payload#>>'{claim,run_id}');
   IF p_payload->'include_raw'='false'::jsonb THEN v_result:=v_result-'raw_body'; END IF;
   RETURN v_result||jsonb_build_object('verification',v_verified,'run_disposition',v_finalize);
  END IF;
  RETURN v_result;
 END IF;
 RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unsupported delivery operation';
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_dispatch_v2(p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; p astra_ingestion_v1.backfill_pages_v2;
 v_now timestamptz:=clock_timestamp(); v_claim jsonb; v_owner text; v_lease int; v_supported jsonb; v_result jsonb;
 v_count int; v_hash text; v_raw text; v_cursor jsonb; v_state text; v_delay double precision; v_retry boolean; v_page int;
 v_parsed jsonb; v_source_rows jsonb; v_submitted_rows jsonb; v_source_cursor text; v_source_url text;
 v_members jsonb; v_contracts jsonb; v_symbols jsonb; v_child_scope jsonb; v_child_id text; v_record jsonb; v_group int; v_kind text;
 v_after_task text; v_after_page int; v_limit int; v_pages jsonb; v_last jsonb; v_more boolean;
 v_dependency record; v_capability_revision text; v_dependency_code text;
 v_not_before double precision; v_epoch double precision;
 v_fair_run text; v_fair_start integer; v_fair_pick record; v_fair_selected boolean;
BEGIN
 -- backfill_retained_reader_v2: invoked only after existing worker authentication.
 IF p_operation='backfill_reuse_commit' THEN RETURN astra_ingestion_v1.backfill_reuse_commit_v2(p_payload); END IF;
 -- backfill_retained_verify_v2: committed pointer, no fabricated live lease.
 IF p_operation='backfill_reuse_verify' THEN RETURN astra_ingestion_v1.backfill_reuse_verify_v2(p_payload->>'task_id',(p_payload->>'page_no')::integer); END IF;
 IF p_operation='backfill_feature_reuse_commit' THEN RETURN astra_ingestion_v1.backfill_feature_reuse_commit_v2(p_payload); END IF;
 IF p_operation='backfill_feature_reuse_verify' THEN RETURN astra_ingestion_v1.backfill_feature_reuse_verify_v2(p_payload->>'task_id',(p_payload->>'page_no')::int); END IF;
 IF p_operation='backfill_reuse_read' THEN RETURN astra_ingestion_v1.backfill_reuse_read_v2(p_payload); END IF;
 IF p_operation='backfill_breadth_material' THEN RETURN astra_ingestion_v1.backfill_breadth_material_v2(p_payload); END IF;
 IF p_operation='backfill_breadth_project' THEN RETURN astra_ingestion_v1.backfill_breadth_project_pending_v2(COALESCE((p_payload->>'limit')::integer,2)); END IF;
 IF p_operation='backfill_identity_material' THEN RETURN astra_ingestion_v1.backfill_identity_material_v2(p_payload); END IF;
 IF p_operation='backfill_identity_source_read' THEN RETURN astra_ingestion_v1.backfill_identity_source_read_v2(p_payload); END IF;
 IF p_operation='backfill_identity_source_commit' THEN RETURN astra_ingestion_v1.backfill_identity_source_commit_v2(p_payload); END IF;
 IF p_operation='backfill_identity_refresh' THEN RETURN jsonb_build_object('queued',astra_ingestion_v1.backfill_identity_refresh_pending_v2(COALESCE((p_payload->>'limit')::int,2))); END IF;
 IF p_operation='backfill_massive_archive_read' THEN RETURN astra_ingestion_v1.backfill_massive_archive_read_v2(p_payload);END IF;
 IF p_operation='backfill_massive_archive_commit' THEN RETURN astra_ingestion_v1.backfill_massive_archive_commit_v2(p_payload);END IF;
 IF p_operation='backfill_massive_archive_verify' THEN RETURN astra_ingestion_v1.backfill_massive_archive_verify_v2(p_payload->>'task_id',(p_payload->>'page_no')::int);END IF;
 IF p_operation='backfill_status' THEN
  -- backfill_runtime_status_asof_v2: report freshness uses its advertised v_now.
  -- Claim admission retains its existing live-clock checks unchanged.
  WITH fresh_workers AS MATERIALIZED (
   SELECT supported_kinds FROM astra_ingestion_v1.backfill_workers_v2
   WHERE observed_at>v_now-interval '10 minutes'
  )
  SELECT COALESCE(jsonb_agg(x),'[]') INTO v_result FROM (
   SELECT to_jsonb(r) || astra_ingestion_v1.backfill_identity_progress_v2(r.id) || jsonb_build_object(
    'members',(SELECT count(*) FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=r.id),
    'tasks',summary.tasks,
    'unsupported_pending_kinds',summary.unsupported_pending_kinds,
    'provider_dependencies',(SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]') FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=r.id),
    'next_retry_at',(SELECT min(next_retry_at) FROM astra_ingestion_v1.backfill_tasks_v2 st WHERE st.run_id=r.id AND status='RETRY_WAIT')) AS x
   FROM (SELECT * FROM astra_ingestion_v1.backfill_runs_v2
    WHERE p_payload->>'run_id' IS NULL OR id=p_payload->>'run_id' ORDER BY created_at DESC LIMIT 20) r
   CROSS JOIN LATERAL (
    WITH task_groups AS MATERIALIZED (
     SELECT family,kind,provider,status,count(*) tasks,sum(records_committed) records,max(last_progress_at) last_progress_at
     FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=r.id GROUP BY family,kind,provider,status
    ), pending_kinds AS MATERIALIZED (
     SELECT DISTINCT kind FROM task_groups WHERE status IN ('PENDING','RETRY_WAIT')
    )
    SELECT (SELECT COALESCE(jsonb_agg(z),'[]') FROM task_groups z) tasks,
     (SELECT COALESCE(jsonb_agg(DISTINCT k.kind),'[]') FROM pending_kinds k
      WHERE NOT EXISTS(SELECT 1 FROM fresh_workers w WHERE w.supported_kinds ? k.kind)) unsupported_pending_kinds
   ) summary
   ORDER BY r.created_at DESC
  ) q;
  RETURN jsonb_build_object('runs',v_result,'observed_at',v_now);
 ELSIF p_operation='backfill_claim' THEN
  PERFORM astra_ingestion_v1.backfill_identity_discover_pending_v2();
  PERFORM astra_ingestion_v1.backfill_identity_refresh_pending_v2(2);
  v_now:=clock_timestamp();
  v_owner:=p_payload->>'worker_id'; v_supported:=p_payload->'supported_kinds';
  IF v_owner IS NULL OR v_owner !~ '^[A-Za-z0-9_.:-]{1,160}$' OR jsonb_typeof(v_supported) IS DISTINCT FROM 'array' OR jsonb_array_length(v_supported)>32
   OR COALESCE(length(p_payload->>'source_revision'),0) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid bounded worker capabilities'; END IF;
  v_lease:=GREATEST(30,LEAST(COALESCE((p_payload->>'lease_seconds')::int,120),300));
  v_capability_revision:=COALESCE(p_payload->>'capability_revision',encode(sha256(convert_to(p_payload->>'source_revision'||':'||astra_ingestion_v1.rpc_canonical(v_supported),'UTF8')),'hex'));
  IF length(v_capability_revision) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid capability revision'; END IF;
  INSERT INTO astra_ingestion_v1.backfill_workers_v2(worker_id,source_revision,supported_kinds,capability_revision,observed_at)
   VALUES(v_owner,p_payload->>'source_revision',v_supported,v_capability_revision,v_now) ON CONFLICT(worker_id) DO UPDATE SET source_revision=EXCLUDED.source_revision,supported_kinds=EXCLUDED.supported_kinds,capability_revision=EXCLUDED.capability_revision,observed_at=v_now;
  -- Missing runtime configuration is one durable provider dependency; it does
  -- not consume attempts or request reservations for every waiting task.
  FOR v_dependency IN
   SELECT rr.id run_id,pp.provider FROM astra_ingestion_v1.backfill_runs_v2 rr CROSS JOIN (VALUES('Alpaca'),('Massive')) pp(provider)
   WHERE rr.status='ACTIVE' AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 st WHERE st.run_id=rr.id AND st.provider=pp.provider AND st.status IN ('PENDING','RETRY_WAIT','BLOCKED_EXTERNAL'))
  LOOP
   IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_workers_v2 w WHERE w.observed_at>v_now-interval '10 minutes'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(w.supported_kinds) k WHERE k LIKE lower(v_dependency.provider)||'_%')) THEN
    INSERT INTO astra_ingestion_v1.backfill_provider_dependencies_v2(run_id,provider,dependency,state,code,evidence)
     VALUES(v_dependency.run_id,v_dependency.provider,upper(v_dependency.provider)||'_WORKER_CREDENTIAL','BLOCKED_EXTERNAL','RUNTIME_CAPABILITY_UNAVAILABLE',jsonb_build_object('observed_at',v_now,'reason','No recently registered worker advertises this provider capability'))
     ON CONFLICT(run_id,provider) DO UPDATE SET state='BLOCKED_EXTERNAL',code=EXCLUDED.code,evidence=EXCLUDED.evidence,observed_at=v_now,resolved_at=NULL
      WHERE astra_ingestion_v1.backfill_provider_dependencies_v2.state='AVAILABLE';
   ELSE
    UPDATE astra_ingestion_v1.backfill_provider_dependencies_v2 d SET state='AVAILABLE',resolved_at=v_now,observed_at=v_now,
      evidence=d.evidence||jsonb_build_object('resolution','Changed configured worker capability observed','resolved_at',v_now)
     WHERE d.run_id=v_dependency.run_id AND d.provider=v_dependency.provider AND d.state='BLOCKED_EXTERNAL'
      AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_workers_v2 w WHERE w.observed_at>v_now-interval '10 minutes'
       AND (d.code='RUNTIME_CAPABILITY_UNAVAILABLE' OR w.worker_id IS DISTINCT FROM d.blocked_worker OR w.capability_revision IS DISTINCT FROM d.blocked_revision)
       AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(w.supported_kinds) k WHERE k LIKE lower(d.provider)||'_%'));
    UPDATE astra_ingestion_v1.backfill_tasks_v2 st SET status='PENDING',next_retry_at=v_now,error_code=NULL,error_message=NULL
     WHERE st.run_id=v_dependency.run_id AND st.provider=v_dependency.provider AND st.status='BLOCKED_EXTERNAL' AND st.error_code='MISSING_PROVIDER_CREDENTIAL'
      AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=st.run_id AND d.provider=st.provider AND d.state='AVAILABLE');
   END IF;
  END LOOP;
  -- Exhaustion stays an operational failure, never a provider-gap terminal result.
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status='OPERATIONAL_ERROR',owner=NULL,lease_until=NULL,error_code='ATTEMPT_BUDGET_EXHAUSTED',error_message='Eight bounded attempts exhausted; implementation recovery must diagnose before requeue'
   WHERE status='RUNNING' AND lease_until<=v_now AND page_attempts>=8;

  -- backfill_family_fairness_hook_v2: one coherent queue, at most16 families and32 indexed candidate probes.
  SELECT id INTO v_fair_run FROM astra_ingestion_v1.backfill_runs_v2 WHERE status='ACTIVE' ORDER BY created_at,id LIMIT 1;
  IF v_fair_run IS NULL THEN RETURN NULL; END IF;
  INSERT INTO astra_ingestion_v1.backfill_family_turn_v2(run_id) VALUES(v_fair_run) ON CONFLICT(run_id) DO NOTHING;
  SELECT next_family_index INTO STRICT v_fair_start FROM astra_ingestion_v1.backfill_family_turn_v2 WHERE run_id=v_fair_run FOR UPDATE;
  v_fair_selected:=false;
  FOR v_fair_pick IN
   SELECT family,ordinality::integer family_index
   FROM unnest(ARRAY['REF01','REF03','P01','P02','D01','D02','D03','D04','D05','N01','N02','N03','S01','S02','CTX02','CTX06']) WITH ORDINALITY f(family,ordinality)
   ORDER BY mod(ordinality::integer-v_fair_start+16,16)
  LOOP
  -- backfill_due_recovery_priority_v2: recovery first, then the unchanged normal candidate.
  SELECT q.* INTO t FROM astra_ingestion_v1.backfill_tasks_v2 q JOIN astra_ingestion_v1.backfill_runs_v2 rr ON rr.id=q.run_id
   WHERE q.run_id=v_fair_run AND q.family=v_fair_pick.family
    AND q.status IN ('RETRY_WAIT','RUNNING') AND rr.status='ACTIVE' AND rr.fence=q.run_fence AND q.kind = ANY(ARRAY(SELECT jsonb_array_elements_text(v_supported)))
    AND q.next_retry_at<=v_now AND q.page_attempts<8
    AND (q.status IN ('PENDING','RETRY_WAIT') OR (q.status='RUNNING' AND q.lease_until<=v_now))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=q.run_id AND d.provider=q.provider AND d.state='BLOCKED_EXTERNAL')
    AND NOT EXISTS(SELECT 1 FROM unnest(q.dependencies) dep LEFT JOIN astra_ingestion_v1.backfill_tasks_v2 d ON d.id=dep
      WHERE d.id IS NULL OR d.run_id<>q.run_id OR d.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=q.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(q.dependencies) AND gap.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND (q.kind<>'derive_breadth' OR astra_ingestion_v1.backfill_breadth_ready_v2(q.id))
    AND (SELECT count(*) FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=v_fair_run)=3000 /* backfill_claim_member_count_once_v2 */
   ORDER BY q.priority,q.next_retry_at,q.created_at,q.id LIMIT 1 FOR UPDATE OF q;
  IF NOT FOUND THEN
  SELECT q.* INTO t FROM astra_ingestion_v1.backfill_tasks_v2 q JOIN astra_ingestion_v1.backfill_runs_v2 rr ON rr.id=q.run_id
   WHERE q.run_id=v_fair_run AND q.family=v_fair_pick.family
    AND q.status IN ('PENDING','RUNNING','RETRY_WAIT') AND rr.status='ACTIVE' AND rr.fence=q.run_fence AND q.kind = ANY(ARRAY(SELECT jsonb_array_elements_text(v_supported)))
    AND q.next_retry_at<=v_now AND q.page_attempts<8
    AND (q.status IN ('PENDING','RETRY_WAIT') OR (q.status='RUNNING' AND q.lease_until<=v_now))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_provider_dependencies_v2 d WHERE d.run_id=q.run_id AND d.provider=q.provider AND d.state='BLOCKED_EXTERNAL')
    AND NOT EXISTS(SELECT 1 FROM unnest(q.dependencies) dep LEFT JOIN astra_ingestion_v1.backfill_tasks_v2 d ON d.id=dep
      WHERE d.id IS NULL OR d.run_id<>q.run_id OR d.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=q.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(q.dependencies) AND gap.status NOT IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED'))
    AND (q.kind<>'derive_breadth' OR astra_ingestion_v1.backfill_breadth_ready_v2(q.id))
    AND (SELECT count(*) FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=v_fair_run)=3000 /* backfill_claim_member_count_once_v2 */
   ORDER BY q.priority,q.next_retry_at,q.created_at,q.id LIMIT 1 FOR UPDATE OF q;
  END IF;
   IF FOUND THEN
    v_fair_selected:=true;
    UPDATE astra_ingestion_v1.backfill_family_turn_v2
     SET next_family_index=(v_fair_pick.family_index%16)+1,last_family=t.family,last_claimed_task_id=t.id,
      claim_turns=claim_turns+1,changed_at=v_now WHERE run_id=v_fair_run;
    EXIT;
   END IF;
  END LOOP;
  IF NOT v_fair_selected THEN RETURN NULL; END IF;

  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status='RUNNING',owner=v_owner,generation=generation+1,lease_until=v_now+make_interval(secs=>v_lease),attempt_deadline=v_now+interval '5 minutes',
    page_limit=COALESCE(page_limit,CASE WHEN kind='massive_news' AND (cursor IS NULL OR cursor='null'::jsonb) THEN 100 ELSE astra_ingestion_v1.backfill_page_limit_cap_v2(kind) END),attempts=attempts+1,page_attempts=page_attempts+1,reserved_generation=NULL,reserved_page_no=NULL,reserved_at=NULL,source_revision=p_payload->>'source_revision'
   WHERE id=t.id RETURNING * INTO t;
  RETURN to_jsonb(t);
 END IF;
 v_claim:=p_payload->'claim';
 -- Readback never replays a mutation or requires a live lease; exact claim/run binding still applies.
 IF p_operation='backfill_verify' THEN
  SELECT * INTO t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=v_claim->>'id' AND run_id=v_claim->>'run_id';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Replacement task not found'; END IF;
  v_page:=COALESCE((p_payload->>'page_no')::int,t.page_no-1);
  SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=t.id AND page_no=v_page;
  IF NOT FOUND THEN RETURN jsonb_build_object('state','not_committed','task_id',t.id,'page_no',v_page,'task_status',t.status,'next_page_no',t.page_no); END IF;
  RETURN jsonb_build_object('state','committed','task_id',t.id,'page_no',p.page_no,'body_sha256',p.body_sha256,
    'readback_sha256',encode(sha256(convert_to(p.raw_body,'UTF8')),'hex'),'records_sha256',p.records_sha256,'record_count',p.record_count,
    'next_cursor',p.cursor_out,'next_page_no',t.page_no,'task_status',t.status,'raw_body',p.raw_body,'request',p.request,'quality',p.quality,'adapter_version',p.adapter_version);
 END IF;
 -- A duplicate after a lost HTTP acknowledgement is an immutable matching-commit receipt, not a second write.
 IF p_operation='backfill_commit' AND v_claim->>'id' IS NOT NULL THEN
  SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=v_claim->>'id' AND page_no=(v_claim->>'page_no')::int;
  IF FOUND THEN
   IF p.run_id IS DISTINCT FROM v_claim->>'run_id' OR p.generation::text IS DISTINCT FROM v_claim->>'generation'
    OR p.run_fence::text IS DISTINCT FROM v_claim->>'run_fence' OR p.body_sha256 IS DISTINCT FROM p_payload->>'body_sha256' THEN
     RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Existing replacement receipt differs from original commit'; END IF;
   RETURN jsonb_build_object('state','already_committed','task_id',p.task_id,'page_no',p.page_no,'body_sha256',p.body_sha256,'record_count',p.record_count,'next_cursor',p.cursor_out);
  END IF;
 END IF;
 t:=astra_ingestion_v1.backfill_owned_v2(v_claim);
 IF p_operation='backfill_work' THEN RETURN to_jsonb(t);
 ELSIF p_operation='backfill_reserve' THEN
  IF t.reserved_generation=t.generation AND t.reserved_page_no=t.page_no THEN RETURN jsonb_build_object('state','already_reserved','task_id',t.id,'page_no',t.page_no); END IF;
  IF t.provider IN ('Alpaca','Massive') THEN
   v_epoch:=extract(epoch FROM v_now);
   SELECT next_request_at INTO STRICT v_not_before FROM astra_ingestion_v1.source_limits WHERE id=lower(t.provider) FOR UPDATE;
   IF v_not_before>v_epoch THEN
    UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status='RETRY_WAIT',owner=NULL,lease_until=NULL,next_retry_at=to_timestamp(v_not_before),page_attempts=GREATEST(0,page_attempts-1) WHERE id=t.id;

    -- backfill_short_pacing_fairness_v2: a refused request has not served this family.
    -- The existing worker waits two seconds after request_deferred. Retaining
    -- this turn only for <=1 second is bounded; long Retry-After waits rotate.
    IF v_not_before>v_epoch AND v_not_before<=v_epoch+1.0 THEN
     UPDATE astra_ingestion_v1.backfill_family_turn_v2 ft
      SET next_family_index=array_position(ARRAY['REF01','REF03','P01','P02','D01','D02','D03','D04','D05','N01','N02','N03','S01','S02','CTX02','CTX06'],t.family),
       changed_at=v_now
      WHERE ft.run_id=t.run_id AND ft.last_claimed_task_id=t.id AND ft.last_family=t.family
       AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_runs_v2 rr
        WHERE rr.id=t.run_id AND rr.status='ACTIVE' AND rr.fence=t.run_fence);
    END IF;
    RETURN jsonb_build_object('state','request_deferred','task_id',t.id,'page_no',t.page_no,'next_retry_at',to_timestamp(v_not_before));
   END IF;
   -- backfill_paid_provider_pacing_v2: at most one reservation per second/provider; an existing later deadline still wins.
   UPDATE astra_ingestion_v1.source_limits SET next_request_at=v_epoch+1 WHERE id=lower(t.provider);
  END IF;
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET reserved_generation=generation,reserved_page_no=page_no,reserved_at=v_now,
    requests_reserved=requests_reserved+CASE WHEN provider IN ('Alpaca','Massive') THEN 1 ELSE 0 END WHERE id=t.id;
  UPDATE astra_ingestion_v1.backfill_runs_v2 SET requests_reserved=requests_reserved+CASE WHEN t.provider IN ('Alpaca','Massive') THEN 1 ELSE 0 END WHERE id=t.run_id;
  RETURN jsonb_build_object('state','reserved','task_id',t.id,'page_no',t.page_no,'query_scope',t.scope,'cursor',t.cursor,'lease_until',t.lease_until);

 ELSIF p_operation='backfill_defer' THEN
  -- backfill_adaptive_page_dispatch_v2: already authenticated, locked and fenced.
  IF p_payload->>'code'='SOURCE_PAGE_TOO_LARGE' THEN
   p_payload:=astra_ingestion_v1.backfill_adapt_page_v2(t,p_payload);
   t:=astra_ingestion_v1.backfill_owned_v2(v_claim);
  END IF;
  v_retry:=COALESCE((p_payload->>'retryable')::boolean,false);
  IF length(COALESCE(p_payload->>'code','')) NOT BETWEEN 1 AND 120 OR octet_length(COALESCE(p_payload->'evidence','{}')::text)>4194304 THEN
    RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid bounded failure evidence'; END IF;
  v_delay:=GREATEST(2,COALESCE((p_payload->>'retry_after')::double precision,0),LEAST(3600,power(2,GREATEST(1,t.page_attempts))));
  IF v_delay IN ('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision) OR extract(epoch FROM v_now)+v_delay>253402300799 THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retry-After must be a finite representable interval'; END IF;
  v_state:=CASE WHEN v_retry AND t.page_attempts<8 THEN 'RETRY_WAIT'
    WHEN p_payload->>'code' IN ('BLOCKED_EXTERNAL','AUTHENTICATION_FAILED','MISSING_CREDENTIAL','MISSING_PROVIDER_CREDENTIAL','PROVIDER_FORBIDDEN') THEN 'BLOCKED_EXTERNAL' ELSE 'OPERATIONAL_ERROR' END;
  IF t.provider IN ('Alpaca','Massive') AND (p_payload#>>'{evidence,http_status}'='429' OR p_payload->>'code' IN ('SOURCE_RATE_LIMIT','PROVIDER_RATE_LIMIT')) THEN
   UPDATE astra_ingestion_v1.source_limits SET next_request_at=GREATEST(next_request_at,extract(epoch FROM v_now)+v_delay) WHERE id=lower(t.provider);
  END IF;
  v_dependency_code:=p_payload#>>'{evidence,dependency}';
  IF t.provider IN ('Alpaca','Massive') AND v_dependency_code=upper(t.provider)||'_WORKER_CREDENTIAL' THEN
   v_state:='BLOCKED_EXTERNAL';
   SELECT capability_revision INTO v_capability_revision FROM astra_ingestion_v1.backfill_workers_v2 WHERE worker_id=t.owner;
   INSERT INTO astra_ingestion_v1.backfill_provider_dependencies_v2(run_id,provider,dependency,state,code,evidence,blocked_worker,blocked_revision)
    VALUES(t.run_id,t.provider,v_dependency_code,v_state,'MISSING_PROVIDER_CREDENTIAL',COALESCE(p_payload->'evidence','{}'),t.owner,v_capability_revision)
    ON CONFLICT(run_id,provider) DO UPDATE SET state=EXCLUDED.state,code=EXCLUDED.code,evidence=EXCLUDED.evidence,blocked_worker=EXCLUDED.blocked_worker,blocked_revision=EXCLUDED.blocked_revision,observed_at=v_now,resolved_at=NULL;
  END IF;
  INSERT INTO astra_ingestion_v1.backfill_exceptions_v2(run_id,task_id,page_no,generation,state,code,message,evidence,next_retry_at)
   VALUES(t.run_id,t.id,t.page_no,t.generation,v_state,p_payload->>'code',left(COALESCE(p_payload->>'message','Operation failed'),1000),COALESCE(p_payload->'evidence','{}'),CASE WHEN v_state='RETRY_WAIT' THEN v_now+make_interval(secs=>v_delay) END);
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status=v_state,owner=NULL,lease_until=NULL,next_retry_at=v_now+make_interval(secs=>v_delay),error_code=CASE WHEN v_dependency_code=upper(t.provider)||'_WORKER_CREDENTIAL' THEN 'MISSING_PROVIDER_CREDENTIAL' ELSE p_payload->>'code' END,error_message=left(p_payload->>'message',1000) WHERE id=t.id;
  RETURN jsonb_build_object('state',v_state,'task_id',t.id,'next_retry_at',CASE WHEN v_state='RETRY_WAIT' THEN v_now+make_interval(secs=>v_delay) END,'page_attempts',t.page_attempts);
 ELSIF p_operation='backfill_material' THEN
  UPDATE astra_ingestion_v1.backfill_tasks_v2 SET lease_until=LEAST(attempt_deadline,v_now+interval '120 seconds') WHERE id=t.id;
  v_after_task:=COALESCE(p_payload#>>'{after,task_id}',''); v_after_page:=COALESCE((p_payload#>>'{after,page_no}')::int,-1); v_limit:=GREATEST(1,LEAST(COALESCE((p_payload->>'limit')::int,2),4));
  SELECT COALESCE(jsonb_agg(x ORDER BY task_id,page_no),'[]') INTO v_pages FROM (
   SELECT pg.task_id,pg.page_no,jsonb_build_object('id',d.id,'kind',d.kind,'family',d.family,'provider',d.provider,'scope',d.scope,'cursor',pg.cursor_in) AS task,
    pg.raw_body,pg.body_sha256,pg.request,pg.record_count,pg.quality,pg.adapter_version
   FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_tasks_v2 d ON d.id=pg.task_id
   WHERE (pg.task_id=ANY(t.dependencies) OR pg.task_id IN (SELECT gap.id FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=t.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(t.dependencies))) AND pg.run_id=t.run_id AND (pg.task_id,pg.page_no)>(v_after_task,v_after_page)
   ORDER BY pg.task_id,pg.page_no LIMIT v_limit
  ) x;
  IF jsonb_array_length(v_pages)>0 THEN v_last:=v_pages->(jsonb_array_length(v_pages)-1); v_after_task:=v_last->>'task_id';v_after_page:=(v_last->>'page_no')::int; END IF;
  SELECT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 pg WHERE (pg.task_id=ANY(t.dependencies) OR pg.task_id IN (SELECT gap.id FROM astra_ingestion_v1.backfill_tasks_v2 gap WHERE gap.run_id=t.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=ANY(t.dependencies))) AND pg.run_id=t.run_id AND (pg.task_id,pg.page_no)>(v_after_task,v_after_page)) INTO v_more;
  RETURN jsonb_build_object('pages',v_pages,'next_after',CASE WHEN v_more THEN jsonb_build_object('task_id',v_after_task,'page_no',v_after_page) END,'complete',NOT v_more,
    'dependency_states',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'status',status,'error_code',error_code)),'[]') FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=ANY(t.dependencies)));
 ELSIF p_operation<>'backfill_commit' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unsupported replacement operation';
 END IF;
 IF t.provider IN ('Alpaca','Massive') AND (t.reserved_generation IS DISTINCT FROM t.generation OR t.reserved_page_no IS DISTINCT FROM t.page_no) THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Page request must be durably reserved before dispatch'; END IF;
 v_raw:=p_payload->>'raw_body'; v_hash:=encode(sha256(convert_to(v_raw,'UTF8')),'hex');
 IF v_raw IS NULL OR octet_length(v_raw)>4194304 OR v_hash IS DISTINCT FROM p_payload->>'body_sha256'
  OR jsonb_typeof(p_payload->'records') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'records')>100000
  OR (p_payload->>'http_status')::int<>200 OR NOT astra_ingestion_v1.backfill_request_valid_v2(t,p_payload->'request')
  OR length(COALESCE(p_payload->>'adapter_version','')) NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Replacement source digest, request scope or page shape is invalid'; END IF;
 PERFORM astra_ingestion_v1.rpc_json_unique(v_raw::json);
 v_parsed:=v_raw::jsonb;
 IF t.kind IN ('alpaca_stock_bars','alpaca_option_bars') THEN
   SELECT COALESCE(jsonb_agg(b.value ORDER BY b.value::text),'[]') INTO v_source_rows
     FROM jsonb_each(COALESCE(NULLIF(v_parsed->'bars','null'::jsonb),'{}')) s CROSS JOIN LATERAL jsonb_array_elements(s.value) b;
 ELSIF t.kind='alpaca_reference' THEN v_source_rows:=jsonb_build_array(v_parsed);
 ELSIF t.kind='alpaca_option_contracts' THEN
   SELECT COALESCE(jsonb_agg(value ORDER BY value::text),'[]') INTO v_source_rows FROM jsonb_array_elements(COALESCE(NULLIF(v_parsed->'option_contracts','null'::jsonb),'[]'));
 ELSIF t.kind='alpaca_news' THEN
   SELECT COALESCE(jsonb_agg(value ORDER BY value::text),'[]') INTO v_source_rows FROM jsonb_array_elements(COALESCE(NULLIF(v_parsed->'news','null'::jsonb),'[]'));
 ELSIF t.kind='alpaca_actions' THEN
   SELECT COALESCE(jsonb_agg(b.value ORDER BY b.value::text),'[]') INTO v_source_rows
     FROM jsonb_each(COALESCE(NULLIF(v_parsed->'corporate_actions','null'::jsonb),'{}')) s CROSS JOIN LATERAL jsonb_array_elements(s.value) b;
 ELSIF t.provider='Massive' THEN
   SELECT COALESCE(jsonb_agg(value ORDER BY value::text),'[]') INTO v_source_rows FROM jsonb_array_elements(
      CASE WHEN jsonb_typeof(v_parsed->'results')='object' THEN jsonb_build_array(v_parsed->'results') ELSE COALESCE(NULLIF(v_parsed->'results','null'::jsonb),'[]') END);
 ELSE
   v_source_rows:=COALESCE(v_parsed->'rows',v_parsed->'records');
 END IF;
 IF t.provider IN ('Alpaca','Massive') THEN
   SELECT COALESCE(jsonb_agg(value->'source' ORDER BY (value->'source')::text),'[]') INTO v_submitted_rows FROM jsonb_array_elements(p_payload->'records');
 ELSE v_submitted_rows:=p_payload->'records'; END IF;
 IF v_source_rows IS DISTINCT FROM v_submitted_rows THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Normalized source rows do not match the original retained page'; END IF;
 v_count:=jsonb_array_length(p_payload->'records'); v_cursor:=NULLIF(p_payload->'next_cursor','null'::jsonb);
 IF t.provider='Alpaca' AND t.kind<>'alpaca_reference' THEN
  IF NOT (v_parsed ? 'next_page_token') THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Original source pagination field is missing'; END IF;
  IF NULLIF(v_parsed->'next_page_token','null'::jsonb) IS DISTINCT FROM v_cursor THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained source continuation differs from the proposed checkpoint'; END IF;
 ELSIF t.provider='Massive' THEN
  v_source_url:=v_parsed->>'next_url';v_source_cursor:=NULL;
  IF v_source_url IS NOT NULL THEN
   IF strpos(v_source_url,'https://api.massive.com'||(p_payload#>>'{request,path}')||'?')<>1
    AND strpos(v_source_url,'https://api.polygon.io'||(p_payload#>>'{request,path}')||'?')<>1 THEN
     RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Untrusted provider pagination origin or path'; END IF;
   SELECT astra_ingestion_v1.backfill_uri_component_v2(substr(kv,strpos(kv,'=')+1)) INTO v_source_cursor
    FROM unnest(string_to_array(split_part(v_source_url,'?',2),'&')) kv WHERE split_part(kv,'=',1)='cursor';
   IF v_source_cursor IS NULL THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Source continuation cursor missing'; END IF;
  END IF;
  IF v_source_cursor IS DISTINCT FROM v_cursor#>>'{}' THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained source continuation differs from the proposed checkpoint'; END IF;
 END IF;
 IF v_cursor IS NOT NULL AND (jsonb_typeof(v_cursor)<>'string' OR length(v_cursor#>>'{}') NOT BETWEEN 1 AND 8192 OR v_cursor IS NOT DISTINCT FROM t.cursor
  OR EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=t.id AND cursor_in=v_cursor)) THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Replacement source pagination token is invalid or repeated'; END IF;
 v_state:=CASE WHEN v_cursor IS NOT NULL THEN 'PENDING' WHEN t.records_committed+v_count=0 THEN 'NO_DATA_RETURNED' ELSE 'INGESTED' END;
 IF v_cursor IS NULL AND p_payload->>'terminal_state' IN ('IDENTITY_OR_QUALITY_UNRESOLVED','NOT_APPLICABLE','PROVIDER_LIMITATION') THEN
   IF COALESCE(jsonb_array_length(p_payload->'quality'),0)=0 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='A terminal limitation requires retained evidence'; END IF;
   v_state:=p_payload->>'terminal_state';
 END IF;
 IF v_cursor IS NULL AND jsonb_array_length(COALESCE(p_payload->'quality','[]'))>0 AND v_state='INGESTED' THEN v_state:='IDENTITY_OR_QUALITY_UNRESOLVED'; END IF;
 INSERT INTO astra_ingestion_v1.backfill_pages_v2(task_id,page_no,run_id,generation,run_fence,provider,cursor_in,cursor_out,request,http_status,request_id,fetched_at,raw_body,body_sha256,records_sha256,record_count,source_bytes,quality,headers,adapter_version)
 VALUES(t.id,t.page_no,t.run_id,t.generation,t.run_fence,t.provider,t.cursor,v_cursor,p_payload->'request',200,left(p_payload->>'request_id',256),(p_payload->>'fetched_at')::timestamptz,v_raw,v_hash,
  encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(p_payload->'records'),'UTF8')),'hex'),v_count,octet_length(v_raw),COALESCE(p_payload->'quality','[]'),COALESCE(p_payload->'headers','{}'),p_payload->>'adapter_version');
 -- Durable contract enumeration admission is independently verified and reconciled by the same controller.
 IF t.kind='alpaca_option_contracts' THEN PERFORM astra_ingestion_v1.backfill_contract_enqueue_v2(t.id,t.page_no);END IF;
 PERFORM astra_ingestion_v1.backfill_owned_v2(v_claim);
 UPDATE astra_ingestion_v1.backfill_tasks_v2 SET status=v_state,cursor=v_cursor,page_no=page_no+1,records_committed=records_committed+v_count,
  owner=NULL,lease_until=NULL,page_attempts=0,last_progress_at=v_now,next_retry_at=v_now,error_code=NULL,error_message=NULL WHERE id=t.id;
 UPDATE astra_ingestion_v1.backfill_runs_v2 SET pages_committed=pages_committed+1,records_committed=records_committed+v_count,source_bytes=source_bytes+octet_length(v_raw),last_progress_at=v_now WHERE id=t.run_id;
 IF v_state IN ('IDENTITY_OR_QUALITY_UNRESOLVED','NOT_APPLICABLE','PROVIDER_LIMITATION') THEN
  INSERT INTO astra_ingestion_v1.backfill_exceptions_v2(run_id,task_id,page_no,generation,state,code,message,evidence)
   VALUES(t.run_id,t.id,t.page_no,t.generation,v_state,v_state,'Retained source page has documented per-unit limitations',COALESCE(p_payload->'quality','[]'));
 END IF;
 RETURN jsonb_build_object('state','page_committed','task_id',t.id,'page_no',t.page_no,'task_status',v_state,'record_count',v_count,'body_sha256',v_hash,'next_cursor',v_cursor);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_feature_reuse_summary_v2(p_task_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
AS $function$
DECLARE
 t astra_ingestion_v1.backfill_tasks_v2;
 r astra_ingestion_v1.backfill_runs_v2;
 m astra_ingestion_v1.backfill_members_v2;
 s astra_ingestion_v1.backfill_tasks_v2;
 p astra_ingestion_v1.backfill_pages_v2;
 i reference.alpaca_fixed_window_instruments_v1;
 c astra_shared_equity_features_20260928_v1.feature_session_cache_remediated_v1;
 v_day date; v_calendar jsonb; v_open timestamptz; v_close timestamptz;
 v_sources text[]; v_identity bytea; v_identity_anchor text; v_result jsonb;
 v_raw_count int; v_profile_count int; v_usable_count int; v_aligned_count int;
 v_source_hash bytea; v_profile_hash text; v_minutes smallint[]; v_jobs jsonb;
 v_output_hash bytea; v_builder_hash text; v_grid_hash text; v_hash_function_hash text;
 v_miss jsonb:=jsonb_build_object('state','CACHE_NOT_REUSABLE','new_market_rows_written',0);
BEGIN
 SELECT * INTO t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF NOT FOUND OR t.kind<>'derive_intraday' OR t.family<>'D01' OR lower(t.provider)<>'derived' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='D01 cache requires an immutable intraday derivation'; END IF;
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=t.run_id;
 IF r.cohort_sha256<>'2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec'
 OR r.target_start<>'2025-09-01'::date OR r.target_end<>'2026-07-31'::date
 OR jsonb_typeof(t.scope->'member_ids') IS DISTINCT FROM 'array'
 OR jsonb_array_length(t.scope->'member_ids')<>1 THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='D01 cache frozen scope differs'; END IF;
 IF t.scope->>'target_start' IS NULL OR t.scope->>'target_end' IS DISTINCT FROM t.scope->>'target_start' THEN
  RETURN v_miss||jsonb_build_object('reason','ONE_TARGET_SESSION_REQUIRED'); END IF;
 v_day:=(t.scope->>'target_start')::date;
 IF v_day<r.target_start OR v_day>r.target_end THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='D01 cache date is outside the frozen target'; END IF;
 SELECT * INTO STRICT m FROM astra_ingestion_v1.backfill_members_v2
  WHERE run_id=t.run_id AND member_id=t.scope#>>'{member_ids,0}';
 SELECT e INTO v_calendar FROM jsonb_array_elements(COALESCE(t.scope->'calendar','[]')) e WHERE e->>'date'=v_day::text;
 IF v_calendar IS NULL OR v_calendar->>'open' IS NULL OR v_calendar->>'close' IS NULL THEN
  RETURN v_miss||jsonb_build_object('reason','ACTUAL_SESSION_CALENDAR_REQUIRED'); END IF;
 v_open:=(v_day+(v_calendar->>'open')::time) AT TIME ZONE 'America/New_York';
 v_close:=(v_day+(v_calendar->>'close')::time) AT TIME ZONE 'America/New_York';
 IF v_close<=v_open OR v_close-v_open>interval '8 hours' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid D01 exchange session'; END IF;
 SELECT array_agg(z.id ORDER BY z.id) INTO v_sources FROM (
  SELECT q.id FROM astra_ingestion_v1.backfill_tasks_v2 q
  WHERE q.id=ANY(t.dependencies) AND q.run_id=t.run_id AND q.kind='retained_reuse'
   AND lower(q.provider)='reuse' AND q.status IN ('INGESTED','IDENTITY_OR_QUALITY_UNRESOLVED')
   AND q.scope->'member_ids'=t.scope->'member_ids'
   AND (q.scope->>'start')::timestamptz<=v_open AND (q.scope->>'end_exclusive')::timestamptz>=v_close
  LIMIT 2) z;
 IF COALESCE(cardinality(v_sources),0)<>1 THEN
  RETURN v_miss||jsonb_build_object('reason','ONE_COMMITTED_RETAINED_DEPENDENCY_REQUIRED'); END IF;
 SELECT * INTO STRICT s FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=v_sources[1];
 -- Any repair query supersedes this old session, even a genuine empty response.
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 gap
   WHERE gap.run_id=t.run_id AND gap.scope ? 'reuse_parent' AND gap.scope->>'reuse_parent'=s.id
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(gap.scope->'calendar','[]')) e WHERE e->>'date'=v_day::text)) THEN
  RETURN v_miss||jsonb_build_object('reason','SESSION_HAS_PROVIDER_REPAIR_CHILD'); END IF;
 SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=s.id AND page_no=0;
 IF NOT FOUND OR p.record_count<>1 OR p.raw_body::jsonb#>>'{rows,0,record_type}' IS DISTINCT FROM 'RETAINED_SOURCE_POINTER'
 OR p.body_sha256 IS DISTINCT FROM encode(sha256(convert_to(p.raw_body,'UTF8')),'hex') THEN
  RETURN v_miss||jsonb_build_object('reason','COMMITTED_SOURCE_POINTER_REQUIRED'); END IF;
 SELECT * INTO i FROM reference.alpaca_fixed_window_instruments_v1 WHERE instrument_key=(s.scope->>'instrument_key')::int;
 IF NOT FOUND OR i.alpaca_asset_id::text IS DISTINCT FROM s.scope->>'alpaca_asset_id'
 OR i.symbol IS DISTINCT FROM s.scope->>'symbol' OR i.symbol IS DISTINCT FROM m.anchor_ticker
 OR NOT COALESCE(t.scope->'symbols' @> jsonb_build_array(i.symbol),false) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='D01 cache provider security and frozen member differ'; END IF;
 SELECT * INTO c FROM astra_shared_equity_features_20260928_v1.feature_session_cache_remediated_v1
  WHERE instrument_key=i.instrument_key AND session_date=v_day;
 IF NOT FOUND THEN RETURN v_miss||jsonb_build_object('reason','CACHE_ROW_ABSENT'); END IF;
 SELECT h.identity_contract_sha256,h.identity_anchor INTO v_identity,v_identity_anchor
 FROM astra_shared_equity_features_20260928_v1.shared_identity_contract_remediated_v1 h
 WHERE h.instrument_key=i.instrument_key AND h.session_date=v_day;
 IF v_identity IS NULL OR v_identity IS DISTINCT FROM c.identity_contract_sha256 THEN
  RETURN v_miss||jsonb_build_object('reason','IDENTITY_CONTRACT_HASH_MISMATCH'); END IF;
 IF c.regular_open IS DISTINCT FROM v_open OR c.regular_close IS DISTINCT FROM v_close
 OR c.expected_grid_rows IS DISTINCT FROM (extract(epoch FROM v_close-v_open)/60)::integer
 OR COALESCE(c.aligned_source_rows,0)<1 OR cardinality(c.minute_indices) IS DISTINCT FROM c.aligned_source_rows
 OR cardinality(c.validity_codes) IS DISTINCT FROM c.aligned_source_rows
 OR cardinality(c.dependency_source_observed_at) IS DISTINCT FROM c.aligned_source_rows
 OR array_ndims(c.coefficient_values) IS DISTINCT FROM 2 OR array_length(c.coefficient_values,1) IS DISTINCT FROM c.aligned_source_rows
 OR array_length(c.coefficient_values,2) IS DISTINCT FROM 17 THEN
  RETURN v_miss||jsonb_build_object('reason','CACHE_ARRAY_OR_SESSION_SHAPE_MISMATCH'); END IF;
 SELECT encode(sha256(convert_to(pg_get_functiondef('astra_shared_equity_features_20260928_v1.compute_feature_sessions_remediated_v1(integer,integer,date,date,boolean)'::regprocedure),'UTF8')),'hex'),
  encode(sha256(convert_to(pg_get_functiondef('astra_shared_equity_features_20260928_v1.feature_grid_remediated_v1(integer,date,timestamptz,boolean)'::regprocedure),'UTF8')),'hex'),
  encode(sha256(convert_to(pg_get_functiondef('astra_shared_equity_features_20260928_v1.compact_output_hash_remediated_v1(bytea,bytea,smallint[],smallint[],timestamptz[],double precision[],integer,integer,integer,integer)'::regprocedure),'UTF8')),'hex')
 INTO v_builder_hash,v_grid_hash,v_hash_function_hash;
 IF v_builder_hash<>'019b86197174c682febb88a546a0ff956c058347e99b6dc0dbdd430e090fb552'
 OR v_grid_hash<>'5f45e08dce40aa5cc138fa9b5819b25d049bacea574d50ceb2f943d8ff02b251'
 OR v_hash_function_hash<>'3d2af9589f2171964f77ecb2a5739e7417d12775833c0b3c884a61438689dae5' THEN
  RETURN v_miss||jsonb_build_object('reason','RECOVERED_FORMULA_SOURCE_VERSION_CHANGED'); END IF;
 WITH bounded AS MATERIALIZED(
  SELECT b.* FROM market_fixed_20250901_20260831.alpaca_sip_bars_1m b
  WHERE b.instrument_key=i.instrument_key AND b.bar_ts>=v_open AND b.bar_ts<v_close ORDER BY b.bar_ts LIMIT 1001
 ), measured AS MATERIALIZED(
  SELECT b.*,j.config,j.status,
   COALESCE(j.config->>'feed'='sip' AND j.config->>'adjustment'='raw' AND j.config->'timeframes' @> '["1Min"]'::jsonb
    AND (j.config->>'start_date')::date<=v_day AND (j.config->>'end_date')::date>=v_day,false) profile_ok,
   sha256(convert_to(jsonb_build_array(b.instrument_key,b.bar_ts,b.open,b.high,b.low,b.close,b.volume,b.trade_count,b.vwap,b.source_loaded_at,b.loaded_by_job_id)::text,'UTF8')) row_sha256
  FROM bounded b LEFT JOIN market_provenance.alpaca_populator_jobs_v1 j ON j.id=b.loaded_by_job_id
 )
 SELECT count(*),count(*) FILTER(WHERE profile_ok),
  count(*) FILTER(WHERE bar_ts=date_trunc('minute',bar_ts)),
  sha256(COALESCE(string_agg(row_sha256,''::bytea ORDER BY bar_ts),''::bytea)),
  array_agg((extract(epoch FROM bar_ts-v_open)/60)::smallint ORDER BY bar_ts) FILTER(WHERE bar_ts=date_trunc('minute',bar_ts)),
  COALESCE(jsonb_agg(DISTINCT loaded_by_job_id ORDER BY loaded_by_job_id),'[]'),
  encode(sha256(convert_to(COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id',loaded_by_job_id,'config',config,'status',status)
   ORDER BY jsonb_build_object('id',loaded_by_job_id,'config',config,'status',status)),'[]')::text,'UTF8')),'hex')
 INTO v_raw_count,v_profile_count,v_aligned_count,v_source_hash,v_minutes,v_jobs,v_profile_hash FROM measured;
 IF v_raw_count>1000 OR v_raw_count=0 OR v_profile_count<>v_raw_count THEN
  RETURN v_miss||jsonb_build_object('reason','RETAINED_SOURCE_PROFILE_NOT_FULLY_QUALIFIED'); END IF;
 IF v_source_hash IS DISTINCT FROM c.source_rows_sha256 OR v_raw_count<>c.retained_source_rows
 OR v_aligned_count<>c.aligned_source_rows OR v_minutes IS DISTINCT FROM c.minute_indices THEN
  RETURN v_miss||jsonb_build_object('reason','RAW_SOURCE_HASH_OR_GRID_MISMATCH'); END IF;
 v_output_hash:=astra_shared_equity_features_20260928_v1.compact_output_hash_remediated_v1(
  c.source_rows_sha256,c.identity_contract_sha256,c.minute_indices,c.validity_codes,c.dependency_source_observed_at,
  c.coefficient_values,c.retained_source_rows,c.unaligned_source_rows,c.invalid_ohlc_rows,c.invalid_volume_rows);
 IF v_output_hash IS DISTINCT FROM c.output_sha256 THEN
  RETURN v_miss||jsonb_build_object('reason','CACHE_OUTPUT_HASH_MISMATCH'); END IF;
 SELECT count(*) FILTER(WHERE (flags&1)=1 AND (flags&2)=2) INTO v_usable_count FROM unnest(c.validity_codes) flags;
 RETURN jsonb_build_object('state','CACHE_REUSABLE','family','D01','task_id',t.id,'run_id',t.run_id,
  'member_id',m.member_id,'symbol',i.symbol,'instrument_key',i.instrument_key,'alpaca_asset_id',i.alpaca_asset_id,
  'market_date',v_day,'regular_open',v_open,'regular_close',v_close,
  'source_relation','market_fixed_20250901_20260831.alpaca_sip_bars_1m',
  'cache_relation','astra_shared_equity_features_20260928_v1.feature_session_cache_remediated_v1',
  'formula_version','compact_intraday_float64_v1','formula_builder_sha256',v_builder_hash,
  'formula_grid_sha256',v_grid_hash,'formula_hash_function_sha256',v_hash_function_hash,
  'source_digest',encode(v_source_hash,'hex'),'source_digest_algorithm','sha256-ordered-binary-sha256-jsonb-array-source-rows-v1',
  'identity_contract_sha256',encode(v_identity,'hex'),'output_sha256',encode(v_output_hash,'hex'),
  'source_profile_sha256',v_profile_hash,'source_job_ids',v_jobs,'cache_built_at',c.built_at,
  'source_task_id',s.id,'source_page_no',p.page_no,'source_pointer_sha256',p.body_sha256,
  'source_rows',v_raw_count,'reused_feature_rows',c.expected_grid_rows,'qualifying_feature_rows',v_aligned_count,
  'usable_feature_rows',v_usable_count,'missing_scheduled_rows',c.expected_grid_rows-v_aligned_count,
  'unaligned_source_rows',c.unaligned_source_rows,'invalid_ohlc_rows',c.invalid_ohlc_rows,'invalid_volume_rows',c.invalid_volume_rows,
  'coefficient_count',17,'coefficient_order',jsonb_build_array('return_1m','return_5m','return_10m','return_20m','return_60m','return_120m',
   'realized_vol_5m','realized_vol_20m','realized_vol_60m','range_20m_pct','volume_mean_20m','volume_sd_20m',
   'dollar_volume_mean_20m','sma_close_5m','sma_close_20m','sma_close_60m','session_vwap_proxy'),
  'covered_feature_categories',jsonb_build_array('provider_interval','availability_assumed_ts','ohlcv','dollar_volume','rolling_returns',
   'realized_volatility','candle_geometry','rolling_range_20m','volume_relative_20m','dollar_volume_mean_20m','sma_close',
   'session_vwap_proxy','trend_primitives','session_position','liquidity_quality','quality_flags'),
  'unavailable_feature_categories',jsonb_build_array('microstructure_primitives','scenario10_frozen_factor_inputs'),
  'mapping_state','IDENTITY_OR_QUALITY_UNRESOLVED','mapping_reason','POST_WINDOW_ANCHOR_SYMBOL_MATCH_IS_NOT_HISTORICAL_IDENTITY_PROOF',
  'retained_identity_anchor',v_identity_anchor,'original_historical_receipt_recovered',false,
  'expected_bar_slots_are_not_a_trade_denominator',true,'new_market_rows_written',0);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_feature_reuse_verify_v2(p_task_id text, p_page_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
AS $function$
DECLARE p astra_ingestion_v1.backfill_pages_v2; t astra_ingestion_v1.backfill_tasks_v2;
 pointer jsonb; actual jsonb; mismatches jsonb:='[]'; k text;
BEGIN
 SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=p_task_id AND page_no=p_page_no;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Committed feature pointer absent'; END IF;
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p.task_id;
 IF t.run_id<>p.run_id OR t.status NOT IN ('INGESTED','IDENTITY_OR_QUALITY_UNRESOLVED') OR t.page_no<=p.page_no
 OR t.kind<>'derive_intraday' OR t.family<>'D01' OR lower(t.provider)<>'derived'
 OR p.record_count<>1 OR p.cursor_out IS NOT NULL OR p.body_sha256 IS DISTINCT FROM encode(sha256(convert_to(p.raw_body,'UTF8')),'hex') THEN
  RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Committed feature pointer envelope differs'; END IF;
 PERFORM astra_ingestion_v1.rpc_json_unique(p.raw_body::json);
 IF jsonb_typeof(p.raw_body::jsonb->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p.raw_body::jsonb->'rows')<>1
 OR p.records_sha256 IS DISTINCT FROM encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(p.raw_body::jsonb->'rows'),'UTF8')),'hex') THEN
  RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Committed feature pointer record digest differs'; END IF;
 pointer:=p.raw_body::jsonb#>'{rows,0}';
 IF pointer->>'record_type' IS DISTINCT FROM 'DERIVED_RETAINED_SOURCE_POINTER'
 OR pointer->'reused_feature_rows' IS DISTINCT FROM p.raw_body::jsonb->'reused_feature_rows'
 OR pointer->'formula_version' IS DISTINCT FROM p.raw_body::jsonb->'formula_version' THEN
  RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Committed feature pointer identity differs'; END IF;
 actual:=astra_ingestion_v1.backfill_feature_reuse_summary_v2(t.id);
 IF actual->>'state' IS DISTINCT FROM 'CACHE_REUSABLE' THEN
  RETURN actual||jsonb_build_object('passed',false,'state','FEATURE_REUSE_SOURCE_MISMATCH','receipt_record_count',1,
   'reused_feature_rows',0,'qualifying_feature_rows',0,'usable_feature_rows',0,
   'mismatched_fields',jsonb_build_array(actual->>'reason'),'pointer_body_sha256',p.body_sha256); END IF;
 FOR k IN SELECT jsonb_object_keys(actual-'state') LOOP
  IF actual->k IS DISTINCT FROM pointer->k THEN mismatches:=mismatches||jsonb_build_array(k); END IF;
 END LOOP;
 RETURN (actual-'state')||jsonb_build_object('passed',jsonb_array_length(mismatches)=0,
  'state',CASE WHEN jsonb_array_length(mismatches)=0 THEN 'FEATURE_REUSE_SOURCE_VERIFIED' ELSE 'FEATURE_REUSE_SOURCE_MISMATCH' END,
  'receipt_record_count',1,'mismatched_fields',mismatches,'pointer_body_sha256',p.body_sha256,
  'verification_kind','COMMITTED_COMPACT_FEATURE_SOURCE_READBACK_V1');
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_discover_member_v2(p_run text, p_member text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE m astra_ingestion_v1.backfill_members_v2;r astra_ingestion_v1.backfill_runs_v2;x record;meta jsonb;v_id text;n integer:=0;
 state astra_ingestion_v1.backfill_identity_discovered_members_v2;seen integer:=0;last_day date;last_source text;more boolean;
BEGIN
 SELECT * INTO STRICT m FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=p_run AND member_id=p_member;
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=p_run FOR UPDATE;
 IF r.status<>'ACTIVE' THEN RETURN 0; END IF;
 INSERT INTO astra_ingestion_v1.backfill_identity_discovered_members_v2(run_id,member_id,discovered_sources) VALUES(p_run,p_member,0) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT state FROM astra_ingestion_v1.backfill_identity_discovered_members_v2 WHERE run_id=p_run AND member_id=p_member FOR UPDATE;
 IF state.complete THEN RETURN 0; END IF;
 last_day:=state.after_day;last_source:=state.after_source_id;
 FOR x IN SELECT DISTINCT o.requested_as_of,lower(o.raw_payload#>>'{_remediation_acquisition,source_id}') source_id
  FROM reference.massive_security_master_observation_v1 o
  WHERE o.requested_as_of BETWEEN '2025-06-05'::date AND '2026-07-31'::date
   AND o.source_route='market_data_remediation_20261008_v1.massive_native_listing_pages_v1'
   AND (o.ticker=m.anchor_ticker OR (o.composite_figi=m.anchor->>'anchor_composite_figi' AND o.share_class_figi=m.anchor->>'anchor_share_class_figi'))
   AND o.raw_payload#>>'{_remediation_acquisition,source_id}' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   AND (o.requested_as_of,lower(o.raw_payload#>>'{_remediation_acquisition,source_id}'))>(state.after_day,state.after_source_id)
  ORDER BY o.requested_as_of,source_id LIMIT 128
 LOOP
  seen:=seen+1;last_day:=x.requested_as_of;last_source:=x.source_id;
  meta:=astra_ingestion_v1.backfill_identity_source_meta_v2(x.source_id::uuid,x.requested_as_of,false);
  IF meta->>'state'<>'RETAINED_SOURCE_READY' THEN
   INSERT INTO astra_ingestion_v1.backfill_identity_discovery_gaps_v2(run_id,member_id,market_date,source_id,reason,evidence)
   VALUES(p_run,p_member,x.requested_as_of,x.source_id::uuid,COALESCE(meta->>'reason','RETAINED_SOURCE_UNVERIFIABLE'),meta) ON CONFLICT DO NOTHING;
   CONTINUE; END IF;
  v_id:='backfill-identity-source-'||encode(sha256(convert_to(p_run||':'||x.source_id,'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
  VALUES(v_id,p_run,'REF01','REUSE','retained_identity',jsonb_build_object('identity_source_id',x.source_id,
   'expected_source_sha256',meta->>'source_sha256','reference_date',x.requested_as_of,'cohort_sha256',r.cohort_sha256,
   'shared_cohort_reference',true,'member_ids','[]'::jsonb,'plan_static',false,'governing_date','REFERENCE_AS_OF'),15,r.fence)
  ON CONFLICT(id) DO NOTHING;
  INSERT INTO astra_ingestion_v1.backfill_identity_source_members_v2 VALUES(p_run,p_member,v_id) ON CONFLICT DO NOTHING;
  n:=n+1;
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM reference.massive_security_master_observation_v1 o
  WHERE o.requested_as_of BETWEEN '2025-06-05'::date AND '2026-07-31'::date
   AND o.source_route='market_data_remediation_20261008_v1.massive_native_listing_pages_v1'
   AND (o.ticker=m.anchor_ticker OR (o.composite_figi=m.anchor->>'anchor_composite_figi' AND o.share_class_figi=m.anchor->>'anchor_share_class_figi'))
   AND o.raw_payload#>>'{_remediation_acquisition,source_id}' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   AND (o.requested_as_of,lower(o.raw_payload#>>'{_remediation_acquisition,source_id}'))>(last_day,last_source)) INTO more;
 UPDATE astra_ingestion_v1.backfill_identity_discovered_members_v2 SET discovered_sources=discovered_sources+n,observed_at=clock_timestamp(),
  complete=NOT more,after_day=last_day,after_source_id=last_source WHERE run_id=p_run AND member_id=p_member;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_discover_pending_v2()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x record;
BEGIN
 SELECT d.run_id,d.member_id INTO x FROM astra_ingestion_v1.backfill_identity_discovered_members_v2 d
 JOIN astra_ingestion_v1.backfill_runs_v2 r ON r.id=d.run_id WHERE NOT d.complete AND r.status='ACTIVE'
 ORDER BY d.observed_at,d.run_id,d.member_id LIMIT 1;
 IF NOT FOUND THEN RETURN 0; END IF;
 RETURN astra_ingestion_v1.backfill_identity_discover_member_v2(x.run_id,x.member_id);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_project_v2(p_run text, p_day date, p_ref text, p_sha text, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x record;v_cik text;v_state text;v_reason text;v_anchor text;n integer:=0;added integer;
BEGIN
 IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows)>1000 THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Bounded native reference rows required'; END IF;
 FOR x IN SELECT m.member_id,m.anchor_ticker,m.anchor,n.row,n.ordinality::integer ord
  FROM jsonb_array_elements(p_rows) WITH ORDINALITY n(row,ordinality)
  JOIN astra_ingestion_v1.backfill_members_v2 m ON m.run_id=p_run AND
   (n.row->>'ticker'=m.anchor_ticker OR n.row->>'composite_figi'=m.anchor->>'anchor_composite_figi'
     OR n.row->>'share_class_figi'=m.anchor->>'anchor_share_class_figi')
 LOOP
  v_cik:=CASE WHEN x.row->>'cik' ~ '^\d{1,10}$' THEN lpad(x.row->>'cik',10,'0') END;
  v_state:='IDENTITY_OR_QUALITY_UNRESOLVED';v_reason:='STABLE_COHORT_IDENTIFIERS_DIFFER';v_anchor:=NULL;
  IF v_cik IS NOT NULL AND x.member_id='CIK:'||v_cik
   AND x.row->>'composite_figi' ~ '^[A-Z0-9]{12}$' AND x.row->>'share_class_figi' ~ '^[A-Z0-9]{12}$'
   AND x.row->>'composite_figi'=x.anchor->>'anchor_composite_figi'
   AND x.row->>'share_class_figi'=x.anchor->>'anchor_share_class_figi'
   AND x.row->>'type'=x.anchor->>'anchor_security_type'
   AND length(COALESCE(x.row->>'primary_exchange',''))>0
   AND x.row->>'market'='stocks' AND x.row->>'locale'='us'
  THEN v_state:='RETROSPECTIVE_DATED_IDENTIFIERS_MATCHED';v_reason:=NULL;
   v_anchor:='CIK:'||v_cik||'|FIGI:'||(x.row->>'composite_figi')||'|CLASS:'||(x.row->>'share_class_figi');
  ELSIF v_cik IS NULL OR x.row->>'composite_figi' IS NULL OR x.row->>'share_class_figi' IS NULL THEN v_reason:='STABLE_PROVIDER_IDENTIFIERS_MISSING'; END IF;
  INSERT INTO astra_ingestion_v1.backfill_identity_evidence_v2(run_id,member_id,market_date,source_ref,native_ordinal,symbol,historical_symbol,
   cik,composite_figi,share_class_figi,security_type,primary_exchange,identity_anchor,state,reason,eligible,native_row_sha256,source_sha256)
  VALUES(p_run,x.member_id,p_day,p_ref,x.ord,x.anchor_ticker,x.row->>'ticker',v_cik,x.row->>'composite_figi',x.row->>'share_class_figi',
   x.row->>'type',x.row->>'primary_exchange',v_anchor,v_state,v_reason,
   CASE WHEN v_state='RETROSPECTIVE_DATED_IDENTIFIERS_MATCHED' AND x.row->'active'='true'::jsonb THEN true END,
   encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(x.row),'UTF8')),'hex'),p_sha) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS added=ROW_COUNT;n:=n+added;
  IF added>0 THEN PERFORM astra_ingestion_v1.backfill_identity_mark_changed_v2(p_run,x.member_id,p_day); END IF;
 END LOOP;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_readback_trigger_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;p astra_ingestion_v1.backfill_pages_v2;ref text;b jsonb;day date;x record;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=NEW.task_id;
 SELECT * INTO STRICT p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=NEW.task_id AND page_no=NEW.page_no;
 IF t.kind='massive_reference' THEN
  b:=p.raw_body::jsonb;day:=(t.scope->>'asof')::date;ref:='page:'||t.id||':'||p.page_no;
  INSERT INTO astra_ingestion_v1.backfill_identity_sources_v2(run_id,source_ref,source_kind,task_id,page_no,market_date,source_sha256,native_records,verified,verified_at)
  VALUES(t.run_id,ref,'CURRENT_PAGE',t.id,p.page_no,day,p.body_sha256,p.record_count,true,clock_timestamp()) ON CONFLICT DO NOTHING;
  PERFORM astra_ingestion_v1.backfill_identity_project_v2(t.run_id,day,ref,p.body_sha256,
   CASE WHEN jsonb_typeof(b->'results')='object' THEN jsonb_build_array(b->'results') ELSE COALESCE(b->'results','[]') END);
 ELSIF t.kind IN('derive_daily','derive_intraday','derive_breadth') THEN
  INSERT INTO astra_ingestion_v1.backfill_identity_calculation_receipts_v2(task_id,root_task_id,identity_material_sha256,body_sha256,page_no)
  VALUES(t.id,COALESCE(t.scope->>'identity_refresh_of',t.id),p.raw_body::jsonb->>'identity_material_sha256',p.body_sha256,p.page_no) ON CONFLICT DO NOTHING;
  IF t.family='D03' THEN
   FOR x IN SELECT DISTINCT (value->>'market_date')::date AS session_date FROM jsonb_array_elements(COALESCE(p.raw_body::jsonb->'rows','[]')) LOOP
    IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_roots_v2 ir WHERE ir.run_id=t.run_id AND ir.member_id IS NULL
      AND x.session_date BETWEEN ir.input_start AND ir.target_end) THEN
     PERFORM astra_ingestion_v1.backfill_identity_mark_changed_v2(t.run_id,'__COHORT__',x.session_date); END IF;
   END LOOP;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_refresh_pending_v2(p_limit integer DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE q astra_ingestion_v1.backfill_identity_refresh_v2;t astra_ingestion_v1.backfill_tasks_v2;v jsonb;v_id text;n integer:=0;seen integer:=0;last_id text;
BEGIN
 SELECT x.* INTO q FROM astra_ingestion_v1.backfill_identity_refresh_v2 x JOIN astra_ingestion_v1.backfill_runs_v2 r ON r.id=x.run_id
  WHERE r.status='ACTIVE' AND x.ready_after<=clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_source_members_v2 sm JOIN astra_ingestion_v1.backfill_tasks_v2 st ON st.id=sm.task_id
    WHERE sm.run_id=x.run_id AND sm.member_id=x.member_id AND st.status IN('PENDING','RUNNING','RETRY_WAIT'))
  ORDER BY x.ready_after,x.run_id,x.member_id LIMIT 1 FOR UPDATE OF x;
 IF NOT FOUND THEN RETURN 0; END IF;
 PERFORM 1 FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=q.run_id AND status='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RETURN 0; END IF;
 last_id:=q.after_task_id;
 FOR t IN SELECT * FROM astra_ingestion_v1.backfill_tasks_v2 z WHERE z.run_id=q.run_id AND z.id>q.after_task_id AND NOT(z.scope ? 'identity_refresh_of')
  AND ((q.member_id='__COHORT__' AND z.kind='derive_breadth') OR (z.kind='derive_daily' AND z.scope#>>'{member_ids,0}'=q.member_id))
  AND z.status IN('INGESTED','NO_DATA_RETURNED','IDENTITY_OR_QUALITY_UNRESOLVED')
  AND COALESCE((z.scope->>'input_start')::date,(z.scope->>'target_start')::date)<=q.latest_date
  AND (z.scope->>'target_end')::date>=q.earliest_date ORDER BY z.id LIMIT GREATEST(1,LEAST(p_limit,8))
 LOOP
  seen:=seen+1;last_id:=t.id;v:=astra_ingestion_v1.backfill_identity_build_material_v2(t);
  INSERT INTO astra_ingestion_v1.backfill_identity_roots_v2(root_task_id,run_id,member_id,input_start,target_end,identity_material_sha256)
  VALUES(t.id,t.run_id,CASE WHEN t.kind<>'derive_breadth' THEN q.member_id END,COALESCE((t.scope->>'input_start')::date,(t.scope->>'target_start')::date),(t.scope->>'target_end')::date,v->>'identity_material_sha256')
  ON CONFLICT(root_task_id) DO UPDATE SET identity_material_sha256=EXCLUDED.identity_material_sha256,invalidated=false,checked_at=clock_timestamp();
  IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_calculation_receipts_v2 c
    WHERE c.root_task_id=t.id AND c.identity_material_sha256=v->>'identity_material_sha256') THEN CONTINUE; END IF;
  v_id:='backfill-identity-refresh-'||encode(sha256(convert_to(t.id||':'||(v->>'identity_material_sha256'),'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,dependencies,priority,run_fence)
  VALUES(v_id,t.run_id,t.family,t.provider,t.kind,t.scope||jsonb_build_object('identity_refresh_of',t.id,
    'identity_material_sha256',v->>'identity_material_sha256','plan_static',false,'prefer_retained_formula_cache',false),t.dependencies,GREATEST(t.priority,150),t.run_fence)
  ON CONFLICT(id) DO NOTHING;
  n:=n+1;
 END LOOP;
 IF seen<GREATEST(1,LEAST(p_limit,8)) THEN DELETE FROM astra_ingestion_v1.backfill_identity_refresh_v2 WHERE run_id=q.run_id AND member_id=q.member_id;
 ELSE UPDATE astra_ingestion_v1.backfill_identity_refresh_v2 SET after_task_id=last_id WHERE run_id=q.run_id AND member_id=q.member_id; END IF;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_source_verify_v2(p_task text, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s astra_ingestion_v1.backfill_identity_sources_v2;v jsonb;ok boolean;x record;
BEGIN
 SELECT * INTO s FROM astra_ingestion_v1.backfill_identity_sources_v2 WHERE task_id=p_task AND page_no=p_page AND source_kind='RETAINED';
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Retained identity proof does not exist'; END IF;
 v:=astra_ingestion_v1.backfill_identity_source_meta_v2(s.source_id,s.market_date,false);
 ok:=v->>'state'='RETAINED_SOURCE_READY' AND v->>'source_sha256'=s.source_sha256 AND v->>'compressed_sha256'=s.compressed_sha256;
 UPDATE astra_ingestion_v1.backfill_identity_sources_v2 SET verified=COALESCE(ok,false),invalidated=NOT COALESCE(ok,false),
  invalidation_reason=CASE WHEN NOT COALESCE(ok,false) THEN 'ORIGINAL_REFERENCE_SOURCE_CHANGED' END,verified_at=clock_timestamp()
  WHERE run_id=s.run_id AND source_ref=s.source_ref;
 RETURN jsonb_build_object('passed',COALESCE(ok,false),'state',CASE WHEN ok THEN 'RETAINED_IDENTITY_SOURCE_VERIFIED' ELSE 'RETAINED_IDENTITY_SOURCE_CHANGED' END,
  'source_id',s.source_id,'source_sha256',s.source_sha256,'native_records',s.native_records,'market_date',s.market_date);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_massive_archive_verify_v2(p_task text, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE p astra_ingestion_v1.backfill_pages_v2;proof jsonb;
BEGIN
 SELECT * INTO STRICT p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=p_task AND page_no=p_page;
 IF p_page<>0 OR p.record_count<>1 OR p.cursor_out IS NOT NULL OR lower(p.provider)<>'reuse'
  OR p.committed_at>=transaction_timestamp() OR encode(sha256(convert_to(p.raw_body,'UTF8')),'hex')<>p.body_sha256
  OR p.raw_body::jsonb#>>'{rows,0,record_type}' IS DISTINCT FROM 'RETAINED_MASSIVE_SOURCE_POINTER'
  OR encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(p.raw_body::jsonb->'rows'),'UTF8')),'hex')<>p.records_sha256 THEN
  RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained S02 pointer envelope or independent-readback boundary differs'; END IF;
 proof:=astra_ingestion_v1.backfill_s02_source_check_v2(p_task);
 IF proof IS DISTINCT FROM p.raw_body::jsonb#>'{rows,0,proof}' THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained S02 source proof changed after commit'; END IF;
 RETURN proof;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_minute_account_v2(p_task_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; parent astra_ingestion_v1.backfill_tasks_v2;
 v astra_ingestion_v1.backfill_readbacks_v2; v_asset text; v_member text; v_symbol text;
 v_complete boolean; v_max integer; v_added integer;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF t.family NOT IN('P01','P02') OR t.kind NOT IN('retained_reuse','alpaca_stock_bars')
 OR COALESCE(t.scope->>'timeframe','1Min')<>'1Min' THEN RETURN jsonb_build_object('state','NOT_MINUTE_SOURCE'); END IF;
 IF jsonb_array_length(COALESCE(t.scope->'member_ids','[]'))<>1 THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Minute accounting requires an explicit single fixed member'; END IF;
 v_member:=t.scope#>>'{member_ids,0}';v_symbol:=COALESCE(t.scope->>'symbol',t.scope#>>'{symbols,0}');
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_members_v2 m WHERE m.run_id=t.run_id AND m.member_id=v_member AND m.anchor_ticker=v_symbol) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Minute source differs from its frozen provider anchor'; END IF;
 IF t.scope ? 'reuse_parent' THEN SELECT * INTO STRICT parent FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=t.scope->>'reuse_parent'; END IF;
 v_asset:=COALESCE(t.scope->>'alpaca_asset_id',parent.scope->>'alpaca_asset_id',
  (SELECT CASE WHEN count(*)=1 THEN min(i.alpaca_asset_id::text) END FROM reference.alpaca_fixed_window_instruments_v1 i WHERE i.symbol=v_symbol),'ANCHOR_SYMBOL:'||v_symbol);
 SELECT max(page_no) INTO v_max FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=t.id;
 IF v_max IS NULL THEN RETURN jsonb_build_object('state','READBACK_REQUIRED'); END IF;
 IF t.kind='retained_reuse' THEN
  SELECT * INTO STRICT v FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=t.id AND page_no=0;
  IF v.retained_source_verification->'passed' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained session counts require successful source verification'; END IF;
  INSERT INTO astra_ingestion_v1.backfill_minute_sessions_v2
   (run_id,task_id,member_id,symbol,asset_key,market_date,source_type,query_complete,
    raw_rth,raw_pre,raw_post,qualified_rth,qualified_pre,qualified_post,usable_rth,usable_pre,usable_post,last_verified_page,source_verified_at)
  SELECT t.run_id,t.id,v_member,v_symbol,v_asset,(e->>'market_date')::date,'RETAINED',false,
   (e->>'rth_count')::bigint,(e->>'pre_count')::bigint,(e->>'post_count')::bigint,
   (e->>'qualified_rth_count')::bigint,(e->>'qualified_pre_count')::bigint,(e->>'qualified_post_count')::bigint,
   (e->>'usable_rth_count')::bigint,(e->>'usable_pre_count')::bigint,(e->>'usable_post_count')::bigint,v_max,v.verified_at
  FROM jsonb_array_elements(v.retained_source_verification->'session_coverage') e
  ON CONFLICT(task_id,market_date) DO NOTHING;
 ELSE
  IF (t.scope->>'end')::timestamptz-(t.scope->>'start')::timestamptz>interval '32 days' THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Minute accounting unit must fit32 days'; END IF;
  SELECT t.status IN('INGESTED','NO_DATA_RETURNED','IDENTITY_OR_QUALITY_UNRESOLVED')
   AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 p WHERE p.task_id=t.id AND p.cursor_out IS NULL
     AND p.raw_body::jsonb ? 'next_page_token' AND p.raw_body::jsonb->'next_page_token'='null'::jsonb)
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 p WHERE p.task_id=t.id
     AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 b WHERE b.task_id=p.task_id AND b.page_no=p.page_no)) INTO v_complete;
  WITH bars AS MATERIALIZED (
   SELECT x.symbol,x.market_date,x.session,astra_ingestion_v1.backfill_stamp_v2(x.source_row->>'t') stamp,
    count(DISTINCT x.source_row)=1 AND bool_and(astra_ingestion_v1.backfill_bar_usable_v2(x.source_row)) usable
   FROM astra_ingestion_v1.backfill_pages_v2 p JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
   CROSS JOIN LATERAL astra_ingestion_v1.backfill_page_rows_v2(p.task_id,p.page_no) x
   WHERE p.task_id=t.id AND x.symbol=v_symbol AND x.session IN('RTH','PRE','POST')
   GROUP BY x.symbol,x.market_date,x.session,astra_ingestion_v1.backfill_stamp_v2(x.source_row->>'t')
  ), days AS (
   SELECT DISTINCT (e->>'date')::date market_date FROM jsonb_array_elements(COALESCE(t.scope->'calendar','[]')) e
   WHERE (e->>'date')::date BETWEEN ((t.scope->>'start')::timestamptz AT TIME ZONE 'America/New_York')::date
    AND ((t.scope->>'end')::timestamptz AT TIME ZONE 'America/New_York')::date
  )
  INSERT INTO astra_ingestion_v1.backfill_minute_sessions_v2
   (run_id,task_id,member_id,symbol,asset_key,market_date,source_type,query_complete,
    raw_rth,raw_pre,raw_post,qualified_rth,qualified_pre,qualified_post,usable_rth,usable_pre,usable_post,last_verified_page,source_verified_at)
  SELECT t.run_id,t.id,v_member,v_symbol,v_asset,d.market_date,'ACQUIRED',v_complete
   AND (t.scope->>'start')::timestamptz<=((d.market_date+time '04:00') AT TIME ZONE 'America/New_York')
   AND (t.scope->>'end')::timestamptz>=((d.market_date+time '19:59') AT TIME ZONE 'America/New_York'),
   count(*) FILTER(WHERE b.session='RTH'),count(*) FILTER(WHERE b.session='PRE'),count(*) FILTER(WHERE b.session='POST'),
   count(*) FILTER(WHERE b.session='RTH'),count(*) FILTER(WHERE b.session='PRE'),count(*) FILTER(WHERE b.session='POST'),
   count(*) FILTER(WHERE b.session='RTH' AND b.usable),count(*) FILTER(WHERE b.session='PRE' AND b.usable),count(*) FILTER(WHERE b.session='POST' AND b.usable),
   v_max,clock_timestamp() FROM days d LEFT JOIN bars b ON b.market_date=d.market_date GROUP BY d.market_date
  ON CONFLICT(task_id,market_date) DO UPDATE SET query_complete=EXCLUDED.query_complete,
   raw_rth=EXCLUDED.raw_rth,raw_pre=EXCLUDED.raw_pre,raw_post=EXCLUDED.raw_post,
   qualified_rth=EXCLUDED.qualified_rth,qualified_pre=EXCLUDED.qualified_pre,qualified_post=EXCLUDED.qualified_post,
   usable_rth=EXCLUDED.usable_rth,usable_pre=EXCLUDED.usable_pre,usable_post=EXCLUDED.usable_post,
   last_verified_page=EXCLUDED.last_verified_page,source_verified_at=EXCLUDED.source_verified_at;
 END IF;
 GET DIAGNOSTICS v_added=ROW_COUNT;
 INSERT INTO astra_ingestion_v1.backfill_minute_projection_v2(task_id,last_verified_page) VALUES(t.id,v_max)
 ON CONFLICT(task_id) DO UPDATE SET last_verified_page=EXCLUDED.last_verified_page,projected_at=clock_timestamp();
 RETURN jsonb_build_object('state','MINUTE_SESSIONS_PROJECTED','task_id',t.id,'sessions',v_added,'last_verified_page',v_max);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_nonminute_field_reason_v2(v jsonb, p_type text, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE n double precision; typ text:=replace(p_type,'meta_',''); s text:=v#>>'{}';
BEGIN
 IF NULLIF(p_reason,'') IS NOT NULL THEN RETURN p_reason; END IF;
 IF v IS NULL THEN RETURN 'FIELD_NOT_RETURNED'; END IF;
 IF v='null'::jsonb THEN RETURN 'NULL_WITHOUT_RECORDED_REASON'; END IF;
 IF typ IN('number','positive','nonnegative') THEN
  IF jsonb_typeof(v) NOT IN('number','string') OR length(s)>100 OR s !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$' THEN RETURN 'INVALID_NUMERIC_VALUE'; END IF;
  n:=s::double precision;
  IF n IN('Infinity'::double precision,'-Infinity'::double precision,'NaN'::double precision) OR (typ='positive' AND n<=0) OR (typ='nonnegative' AND n<0) THEN RETURN 'INVALID_NUMERIC_VALUE'; END IF;
 ELSIF typ='timestamp' THEN IF astra_ingestion_v1.backfill_stamp_v2(s) IS NULL THEN RETURN 'INVALID_OR_UNQUALIFIED_TIMESTAMP'; END IF;
 ELSIF typ='date' THEN IF astra_ingestion_v1.backfill_date_v2(s) IS NULL THEN RETURN 'INVALID_DATE'; END IF;
 ELSIF typ='text' THEN IF jsonb_typeof(v)<>'string' OR btrim(s)='' THEN RETURN 'EMPTY_OR_INVALID_TEXT'; END IF;
 ELSIF typ='identifier' THEN IF jsonb_typeof(v) NOT IN('number','string') OR btrim(s)='' THEN RETURN 'EMPTY_OR_INVALID_IDENTIFIER'; END IF;
 ELSIF typ IN('object','array') THEN IF jsonb_typeof(v)<>typ THEN RETURN 'INVALID_STRUCTURE'; END IF;
 ELSE RETURN 'UNDECLARED_FIELD_VALIDATION'; END IF;
 RETURN NULL;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN 'INVALID_NUMERIC_VALUE';
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_nonminute_project_page_v2(p_task_id text, p_page_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;p astra_ingestion_v1.backfill_pages_v2;
 role text;variant text;spec jsonb; v_inserted integer;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF t.family IN('P01','P02','D01','REF03') THEN RETURN jsonb_build_object('state','SEPARATE_MINUTE_OR_AUDIT_ACCOUNTING'); END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_nonminute_pages_v2 WHERE task_id=t.id AND page_no=p_page_no) THEN RETURN jsonb_build_object('state','ALREADY_PROJECTED'); END IF;
 SELECT pg.* INTO p FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
  WHERE pg.task_id=t.id AND pg.page_no=p_page_no AND pg.body_sha256=b.body_sha256 AND b.body_sha256=b.readback_sha256 AND pg.record_count=b.actual_records;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Non-minute projection requires independently verified immutable page evidence'; END IF;
 role:=CASE WHEN lower(t.provider)='reuse' OR p.raw_body::jsonb#>>'{rows,0,record_type}' IN('RETAINED_REFERENCE_SOURCE_POINTER','DERIVED_RETAINED_SOURCE_POINTER','RETAINED_SOURCE_POINTER') THEN 'POINTER'
  WHEN lower(t.provider)='derived' THEN 'DERIVED' ELSE 'SOURCE' END;
 variant:=CASE WHEN t.kind='alpaca_stock_bars' AND t.scope->>'timeframe'='1Day' THEN 'ALPACA_1DAY_'||upper(COALESCE(t.scope->>'adjustment','raw'))
  WHEN role='DERIVED' THEN t.family||'_DERIVED_OUTPUT' ELSE t.kind END;
 spec:=CASE WHEN role='POINTER' THEN '{}'::jsonb ELSE astra_ingestion_v1.backfill_nonminute_field_spec_v2(t.family,t.kind) END;
 WITH rows AS MATERIALIZED(
  SELECT x.source_row,COALESCE(x.market_date,CASE WHEN t.kind='massive_reference' THEN astra_ingestion_v1.backfill_date_v2(t.scope->>'asof') END) d
  FROM astra_ingestion_v1.backfill_page_rows_v2(t.id,p_page_no) x
 ), dated AS MATERIALIZED(
  SELECT *,CASE WHEN d BETWEEN '2025-09-01'::date AND '2026-07-31'::date THEN 'TARGET'
   WHEN d<'2025-09-01'::date THEN 'SUPPORT' WHEN d>'2026-07-31'::date THEN 'AFTER_TARGET' ELSE 'UNKNOWN_DATE' END period FROM rows
 ), fields AS MATERIALIZED(
  SELECT d.period,f.key field,f.value datatype,v.value,
   astra_ingestion_v1.backfill_nonminute_field_reason_v2(v.value,f.value,
    COALESCE(d.source_row#>>ARRAY['null_reasons',f.key],
     CASE WHEN f.key='publication_time' AND (v.value IS NULL OR v.value='null'::jsonb) THEN 'PUBLICATION_TIMESTAMP_NOT_SUPPLIED'
      WHEN f.key='eligible_company_count' AND (v.value IS NULL OR v.value='null'::jsonb) THEN 'ELIGIBLE_COMPANY_DENOMINATOR_UNKNOWN' END)) reason
  FROM dated d CROSS JOIN jsonb_each_text(spec) f
  CROSS JOIN LATERAL(SELECT astra_ingestion_v1.backfill_nonminute_field_value_v2(d.source_row,role,f.key) value) v
 ), counts AS(
  SELECT period,field,datatype,(value IS NOT NULL AND value<>'null'::jsonb) nonnull,reason,count(*) n
  FROM fields GROUP BY period,field,datatype,(value IS NOT NULL AND value<>'null'::jsonb),reason
 )
 INSERT INTO astra_ingestion_v1.backfill_nonminute_pages_v2(task_id,page_no,run_id,family,kind,provider,observation_role,source_variant,body_sha256,physical_records,
  target_records,support_records,after_target_records,unknown_date_records,target_first_date,target_last_date,support_first_date,support_last_date,after_target_first_date,after_target_last_date,
  page_has_quality_findings,field_counts)
 SELECT t.id,p_page_no,t.run_id,t.family,t.kind,t.provider,role,variant,p.body_sha256,count(*),
  count(*) FILTER(WHERE period='TARGET'),count(*) FILTER(WHERE period='SUPPORT'),count(*) FILTER(WHERE period='AFTER_TARGET'),count(*) FILTER(WHERE period='UNKNOWN_DATE'),
  min(d) FILTER(WHERE period='TARGET'),max(d) FILTER(WHERE period='TARGET'),min(d) FILTER(WHERE period='SUPPORT'),max(d) FILTER(WHERE period='SUPPORT'),min(d) FILTER(WHERE period='AFTER_TARGET'),max(d) FILTER(WHERE period='AFTER_TARGET'),
  jsonb_array_length(p.quality)>0,
  (SELECT COALESCE(jsonb_agg(jsonb_build_object('period',period,'field',field,'datatype',datatype,'nonnull',nonnull,'reason',reason,'records',n) ORDER BY period,field,reason),'[]') FROM counts)
 FROM dated ON CONFLICT(task_id,page_no) DO NOTHING;
 GET DIAGNOSTICS v_inserted=ROW_COUNT;
 RETURN jsonb_build_object('state','NONMINUTE_PAGE_PROJECTED','task_id',t.id,'page_no',p_page_no,'inserted',v_inserted);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_owned_v2(p_claim jsonb)
 RETURNS astra_ingestion_v1.backfill_tasks_v2
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;
BEGIN
 IF jsonb_typeof(p_claim) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Invalid replacement claim'; END IF;
 SELECT * INTO t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_claim->>'id' FOR UPDATE;
 IF NOT FOUND OR t.status<>'RUNNING' OR t.run_id IS DISTINCT FROM p_claim->>'run_id'
 OR t.owner IS DISTINCT FROM p_claim->>'owner' OR t.generation::text IS DISTINCT FROM p_claim->>'generation'
 OR t.run_fence::text IS DISTINCT FROM p_claim->>'run_fence' OR t.lease_until<=clock_timestamp()
 OR NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_runs_v2 r WHERE r.id=t.run_id AND r.fence=t.run_fence AND r.status='ACTIVE')
 THEN RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Replacement lease, run fence or stop changed'; END IF;
 RETURN t;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_page_rows_v2(p_task_id text, p_page_no integer)
 RETURNS TABLE(record_ordinal bigint, symbol text, market_date date, session text, target_window boolean, record_group text, source_row jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; p astra_ingestion_v1.backfill_pages_v2;
 b jsonb; v_row jsonb; v_rows jsonb; v_array jsonb; v_symbol text; v_group text;
 v_stamp timestamptz; v_local timestamp; v_calendar jsonb; v_day jsonb; v_ordinal bigint:=0;
BEGIN
 SELECT * INTO t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=p_task_id AND page_no=p_page_no;
 IF NOT FOUND THEN RETURN; END IF;
 b:=p.raw_body::jsonb;
 IF t.kind IN ('alpaca_stock_bars','alpaca_option_bars') THEN
  SELECT COALESCE(jsonb_object_agg(e->>'date',e),'{}') INTO v_calendar FROM jsonb_array_elements(COALESCE(t.scope->'calendar','[]')) e;
  FOR v_symbol,v_array IN SELECT key,value FROM jsonb_each(COALESCE(NULLIF(b->'bars','null'::jsonb),'{}')) ORDER BY key LOOP
   FOR v_row IN SELECT value FROM jsonb_array_elements(v_array) LOOP
    v_ordinal:=v_ordinal+1;record_ordinal:=v_ordinal;symbol:=v_symbol;source_row:=v_row;record_group:='bars';
    v_stamp:=astra_ingestion_v1.backfill_stamp_v2(v_row->>'t');v_local:=v_stamp AT TIME ZONE 'America/New_York';market_date:=v_local::date;
    target_window:=market_date BETWEEN '2025-09-01'::date AND '2026-07-31'::date;
    IF t.kind='alpaca_option_bars' OR t.scope->>'timeframe'='1Day' THEN session:='DAILY';
    ELSE
     v_day:=v_calendar->market_date::text;
     session:=CASE WHEN v_stamp IS NULL THEN 'INVALID_TIMESTAMP'
      WHEN v_day IS NULL THEN 'CALENDAR_UNRESOLVED'
      WHEN v_local::time>='04:00'::time AND v_local::time<(v_day->>'open')::time THEN 'PRE'
      WHEN v_local::time>=(v_day->>'open')::time AND v_local::time<(v_day->>'close')::time THEN 'RTH'
      WHEN v_local::time>=(v_day->>'close')::time AND v_local::time<'20:00'::time THEN 'POST'
      ELSE 'OUTSIDE_SUPPORTED_SESSION' END;
    END IF;
    RETURN NEXT;
   END LOOP;
  END LOOP;
  RETURN;
 ELSIF t.kind='alpaca_actions' THEN
  FOR v_group,v_array IN SELECT key,value FROM jsonb_each(COALESCE(NULLIF(b->'corporate_actions','null'::jsonb),'{}')) ORDER BY key LOOP
   FOR v_row IN SELECT value FROM jsonb_array_elements(v_array) LOOP
    v_ordinal:=v_ordinal+1;record_ordinal:=v_ordinal;symbol:=COALESCE(v_row->>'symbol',v_row->>'initiating_symbol');record_group:=v_group;source_row:=v_row;
    market_date:=astra_ingestion_v1.backfill_date_v2(v_row->>'process_date');session:=NULL;target_window:=market_date BETWEEN '2025-09-01'::date AND '2026-07-31'::date;
    RETURN NEXT;
   END LOOP;
  END LOOP;
  RETURN;
 ELSIF t.kind='alpaca_reference' THEN v_rows:=jsonb_build_array(b);
 ELSIF t.kind='alpaca_news' THEN v_rows:=COALESCE(NULLIF(b->'news','null'::jsonb),'[]');
 ELSIF t.kind='alpaca_option_contracts' THEN v_rows:=COALESCE(NULLIF(b->'option_contracts','null'::jsonb),'[]');
 ELSIF t.provider='Massive' THEN v_rows:=CASE WHEN jsonb_typeof(b->'results')='object' THEN jsonb_build_array(b->'results') ELSE COALESCE(NULLIF(b->'results','null'::jsonb),'[]') END;
 ELSE v_rows:=COALESCE(b->'rows',b->'records','[]'); END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(v_rows) LOOP
  v_ordinal:=v_ordinal+1;record_ordinal:=v_ordinal;symbol:=COALESCE(v_row->>'symbol',v_row->>'ticker',CASE WHEN jsonb_array_length(COALESCE(t.scope->'symbols','[]'))=1 THEN t.scope#>>'{symbols,0}' END);
  source_row:=v_row;record_group:=t.kind;session:=NULL;
  market_date:=astra_ingestion_v1.backfill_date_v2(COALESCE(v_row->>'market_date',v_row->>'date',v_row->>'settlement_date',v_row->>'ex_dividend_date',v_row->>'execution_date',v_row->>'created_at',v_row->>'published_utc'));
  target_window:=market_date BETWEEN '2025-09-01'::date AND '2026-07-31'::date;
  RETURN NEXT;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_plan_insert_v2(p_run text, p_fence bigint, p_key text, p_family text, p_provider text, p_kind text, p_scope jsonb, p_dependencies text[] DEFAULT '{}'::text[], p_priority integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_id text:=astra_ingestion_v1.backfill_plan_task_id_v2(p_run,p_key); v_added integer;
 v_scope jsonb:=p_scope||jsonb_build_object('plan_static',true,'planner_version','fixed3000-plan-v2.1');
BEGIN
 INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,dependencies,priority,run_fence)
 VALUES(v_id,p_run,p_family,p_provider,p_kind,v_scope,p_dependencies,p_priority,p_fence)
 ON CONFLICT(id) DO NOTHING;
 GET DIAGNOSTICS v_added=ROW_COUNT;
 IF v_added=0 AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 t
  WHERE t.id=v_id AND t.run_id=p_run AND t.family=p_family AND t.provider=p_provider
  AND t.kind=p_kind AND t.scope=v_scope AND t.dependencies=p_dependencies) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Deterministic plan task differs from its retained definition';
 END IF;
 RETURN v_added;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_plan_next_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
 SET lock_timeout TO '1s'
AS $function$
DECLARE
 r astra_ingestion_v1.backfill_runs_v2;
 m astra_ingestion_v1.backfill_members_v2;
 v_run text:=COALESCE(p_payload->>'run_id','fixed3000-20250901-20260731-v1-20261030');
 v_limit int:=GREATEST(1,LEAST(COALESCE((p_payload->>'member_limit')::int,1),5));
 v_next int; v_breadth int; v_phase text; v_added int:=0; v_members int:=0; v_expected bigint;
 v_calendar jsonb; v_month_calendar jsonb; v_target_dates jsonb; v_map jsonb; v_workflow jsonb; v_snapshot jsonb;
 v_scope jsonb; v_base jsonb; v_key text; v_source_id text; v_raw_id text; v_split_id text;
 v_anchor_count int; v_instrument int; v_asset text; v_month date; v_first date; v_last date;
 v_input date; v_entry jsonb; v_day date; v_family text; v_adjustment text; v_status text;
 v_count bigint; v_hash text; v_calendar_hash text; v_fallback boolean;
 v_after int; v_result jsonb; v_supported jsonb:=COALESCE(p_payload->'supported_kinds','[]'::jsonb);
BEGIN
 -- Same transaction lock as the authenticated existing RPC; no lease can be
 -- advanced by a competing planner between its insertions and checkpoint.
 PERFORM pg_advisory_xact_lock(706314020261028);
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=v_run FOR UPDATE;
 IF r.status<>'ACTIVE' THEN RETURN jsonb_build_object('state','PLANNING_PAUSED','run_id',r.id,'run_status',r.status,'plan_complete',false); END IF;
 IF r.metadata->'planning_complete'='true'::jsonb THEN
  RETURN jsonb_build_object('state','FULL_PLAN_SEALED','run_id',r.id,'plan_complete',true,
   'expected_task_count',r.metadata->'expected_static_task_count','expected_plan_sha256',r.metadata->'expected_plan_sha256');
 END IF;
 IF r.cohort_sha256<>'2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec'
 OR r.cohort_manifest_sha256<>'4134b415e2c26fcde9fced749c0d54ef51376e23f0d2f8c6ce9ef562f9fab99f'
 OR r.target_start<>'2025-09-01'::date OR r.target_end<>'2026-07-31'::date THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Planner accepts only the frozen replacement cohort and dates';
 END IF;
 SELECT count(*),encode(sha256(convert_to(string_agg(member_id,E'\n' ORDER BY selection_order,member_id),'UTF8')),'hex')
 INTO v_count,v_hash FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id;
 IF v_count<>3000 OR v_hash<>'a83310df6a6465ce8d37ffd5352095f6e38d91a3204afd8807fff39092cfd85e' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Frozen actual 3000-member list differs; selection cannot be reopened';
 END IF;
 SELECT jsonb_agg(jsonb_build_object('date',e->>'date','open',e->>'open','close',e->>'close') ORDER BY e->>'date')
 INTO v_calendar FROM jsonb_array_elements(r.scope#>'{calendar,sessions}') e;
 v_calendar_hash:=encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(v_calendar),'UTF8')),'hex');
 IF v_calendar IS NULL OR jsonb_array_length(v_calendar)<>290 OR v_calendar_hash<>'8483822a5553f0d270d87d1ff69c9a30d512d9ea8f660036664aebbf70053d49'
 OR r.scope->>'daily_support_start' IS DISTINCT FROM '2025-06-05'
 OR r.scope->>'intraday_support_start' IS DISTINCT FROM '2025-08-04' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Exact retained 290-session calendar and support history required';
 END IF;
 SELECT jsonb_agg(e->>'date' ORDER BY e->>'date') INTO v_target_dates FROM jsonb_array_elements(v_calendar) e
 WHERE e->>'date' BETWEEN '2025-09-01' AND '2026-07-31';
 v_workflow:=jsonb_build_object('version','fixed3000-plan-v2.1','target_start','2025-09-01','target_end','2026-07-31',
  'market_timezone','America/New_York','session_dates',v_target_dates,'cohort_classification','RETROSPECTIVE_FIXED_COHORT',
  'representative_policy','ONE_FROZEN_COMPANY_ONE_EXPLICIT_ANCHOR_SECURITY; ELIGIBILITY_UNKNOWN_UNTIL_EVIDENCED',
  'daily_support_start','2025-06-05','intraday_support_start','2025-08-04','calendar_sha256',v_calendar_hash,
  'formula_manifest_sha256','e0b0835ad53ef7b71d072184bbb1576b3cd8f514c523361fa31865f71a0c8a65',
  'families',jsonb_build_array('REF01','REF03','P01','P02','D01','D02','D03','D04','D05','N01','N02','N03','S01','S02','CTX02','CTX06'),
  'REF03',jsonb_build_object('mode','CONTINUOUS_AUDIT','scope','All replacement tasks/pages/exceptions/readbacks/recovery',
   'destination','astra_ingestion_v1.backfill_family_ref03_v2'),
  'P02',jsonb_build_object('mode','SHARED_P01_SOURCE_RETRIEVAL','sessions',jsonb_build_array('PRE','POST')),
  'event_policy','Retain all supplied action dates and boundary events; no ex-date-only archive restriction',
  'news_policy','All calendar dates, prefer Massive; separately retained Alpaca alternative if Massive worker configuration unavailable',
  'short_interest_policy','Settlement-date selection; actual publication/retrieval availability retained separately',
  'options_policy','Active and inactive underlying contracts; expiry Sep2025 through2099; dynamic individual-contract daily pages',
  'programme_expires_at',NULL);
 IF r.metadata->>'planner_version' IS NULL THEN
  v_snapshot:=astra_ingestion_v1.backfill_plan_snapshot_v2(r.id,500);
  IF v_snapshot->'more'='true'::jsonb THEN
   RETURN jsonb_build_object('state','SNAPSHOTTING_EXISTING_TASKS','plan_complete',false,'snapshot',v_snapshot);
  END IF;
  SELECT count(*) INTO v_expected FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id;
  r.metadata:=r.metadata||jsonb_build_object('planner_version','fixed3000-plan-v2.1','planner_phase','MEMBERS',
   'planner_next_selection_order',1,'planner_next_breadth_index',0,'planner_expected_static_count',v_expected,
   'planner_preexisting_static_count',v_expected,'workflow_plan',v_workflow);
 ELSIF r.metadata->>'planner_version'<>'fixed3000-plan-v2.1' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Existing planner version differs; retain and explicitly reconcile its checkpoint';
 END IF;
 v_next:=(r.metadata->>'planner_next_selection_order')::int;
 v_breadth:=(r.metadata->>'planner_next_breadth_index')::int;
 v_phase:=r.metadata->>'planner_phase';
 v_expected:=(r.metadata->>'planner_expected_static_count')::bigint;
 IF jsonb_typeof(v_supported)<>'array' THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Worker supported kinds must be an explicit array'; END IF;
 v_fallback:=v_supported ? 'alpaca_news' AND NOT (v_supported ? 'massive_news');

 IF v_phase='MEMBERS' THEN
  -- backfill_planner_one_member_v2: commit one complete member before the next existing worker call.
  FOR m IN SELECT * FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id AND selection_order>=v_next
   ORDER BY selection_order LIMIT LEAST(v_limit,1)
  LOOP
   v_base:=jsonb_build_object('member_ids',jsonb_build_array(m.member_id),'symbols',jsonb_build_array(m.anchor_ticker),
    'symbol',m.anchor_ticker,'market_timezone','America/New_York','target_start','2025-09-01','target_end','2026-07-31',
    'identity_status','UNRESOLVED_PROVIDER_ANCHOR','asof','2026-08-03','cohort_classification','RETROSPECTIVE_FIXED_COHORT');
   v_key:=m.member_id||':';
   -- Daily raw/split series are fetched once per member for all required support.
   FOREACH v_adjustment IN ARRAY ARRAY['raw','split'] LOOP
    v_scope:=v_base||jsonb_build_object('timeframe','1Day','feed','sip','adjustment',v_adjustment,
     'start','2025-06-05T04:00:00Z','end','2026-08-01T03:59:59.999999Z','input_start','2025-06-05',
     'calendar',v_calendar,'daily_basis','ALPACA_PROVIDER_DAILY_NOT_ASSERTED_RTH','governing_date','MARKET_DATE',
     'support_history_policy','Observations before2025-09-01 retained as support history');
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'daily-source:'||v_adjustment,'D02','Alpaca','alpaca_stock_bars',v_scope,'{}',20);
   END LOOP;
   v_raw_id:=astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'daily-source:raw');
   v_split_id:=astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'daily-source:split');
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'reference:alpaca','REF01','Alpaca','alpaca_reference',
    v_base||jsonb_build_object('reference_policy','CURRENT_PROVIDER_IDENTIFIERS_NOT_HISTORICAL_PROOF'),'{}',10);
   SELECT count(*),min(instrument_key),min(alpaca_asset_id::text) INTO v_anchor_count,v_instrument,v_asset
    FROM reference.alpaca_fixed_window_instruments_v1 WHERE symbol=m.anchor_ticker AND alpaca_asset_id IS NOT NULL;
   -- Twelve monthly minute-source units cover Aug support plus all11 targetmonths.
   FOR v_month IN SELECT d::date FROM generate_series('2025-08-01'::date,'2026-07-01'::date,interval '1 month') d LOOP
    v_first:=GREATEST(v_month,'2025-08-04'::date);v_last:=(v_month+interval '1 month')::date-1;
    SELECT jsonb_agg(e ORDER BY e->>'date') INTO v_month_calendar FROM jsonb_array_elements(v_calendar) e
     WHERE (e->>'date')::date BETWEEN v_first AND v_last;
    v_scope:=v_base||jsonb_build_object('source_month',v_month::text,'target_start',v_first::text,'target_end',v_last::text,
     'input_start',v_first::text,'calendar',COALESCE(v_month_calendar,'[]'::jsonb),'feed','sip','timeframe','1Min','adjustment','raw',
     'start',to_char(v_first::timestamp AT TIME ZONE 'America/New_York' AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
     'end_exclusive',to_char((v_last+1)::timestamp AT TIME ZONE 'America/New_York' AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
     'support_history',v_last<'2025-09-01'::date,'governing_date','MARKET_SESSION',
     'shared_families',jsonb_build_array('P01','P02'),'identity_mapping_basis','POST_WINDOW_PROVIDER_ANCHOR_ONLY');
    IF v_anchor_count=1 THEN
     v_scope:=v_scope||jsonb_build_object('instrument_key',v_instrument,'alpaca_asset_id',v_asset,
      'reuse_policy','VERIFY_RETAINED_SOURCE_AND_ADMIT_ONLY_MISSING_OR_UNQUALIFIED_RANGES');
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'minutes:'||v_month::text,'P01','REUSE','retained_reuse',v_scope,'{}',30);
    ELSE
     v_scope:=v_scope||jsonb_build_object('end',to_char(((v_last+1)::timestamp AT TIME ZONE 'America/New_York')-interval '1 microsecond','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'retained_reference_state',CASE WHEN v_anchor_count=0 THEN 'NO_MATCHING_RETAINED_PROVIDER_ANCHOR' ELSE 'AMBIGUOUS_RETAINED_PROVIDER_ANCHOR' END);
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'minutes:'||v_month::text,'P01','Alpaca','alpaca_stock_bars',v_scope,'{}',30);
    END IF;
    IF v_month<'2025-09-01'::date THEN CONTINUE; END IF;
    v_source_id:=astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'minutes:'||v_month::text);
    FOR v_entry IN SELECT e FROM jsonb_array_elements(v_month_calendar) e LOOP
     v_day:=(v_entry->>'date')::date;
     v_scope:=v_base||jsonb_build_object('target_start',v_day::text,'target_end',v_day::text,'input_start',v_day::text,
      'source_month',v_month::text,'calendar',jsonb_build_array(v_entry),'governing_date','MARKET_SESSION',
      'formula_version','fixed3000-derived-v2.1','prefer_retained_formula_cache',true,
      'retained_formula_policy','Preserve original qualifying formula version and lineage when equivalent cache is available');
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'D01:'||v_day::text,'D01','DERIVED','derive_intraday',v_scope,ARRAY[v_source_id],160);
    END LOOP;
    -- The last60 actual preceding sessions, plus current month, are sufficient
    -- for all recovered daily horizons. Missing observations are never filled.
    SELECT min((x.e->>'date')::date) INTO v_input FROM (SELECT e FROM jsonb_array_elements(v_calendar) e
     WHERE (e->>'date')::date<v_month ORDER BY e->>'date' DESC LIMIT 60) x;
    SELECT jsonb_agg(e ORDER BY e->>'date') INTO v_month_calendar FROM jsonb_array_elements(v_calendar) e
     WHERE (e->>'date')::date BETWEEN v_input AND v_last;
    FOREACH v_family IN ARRAY ARRAY['D02','D03','D04','D05'] LOOP
     v_scope:=v_base||jsonb_build_object('target_start',v_month::text,'target_end',v_last::text,'input_start',v_input::text,
      'source_month',v_month::text,'calendar',v_month_calendar,'governing_date','MARKET_SESSION',
      'formula_version','fixed3000-derived-v2.1','prefer_retained_formula_cache',true);
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||v_family||':'||v_month::text,v_family,'DERIVED','derive_daily',v_scope,ARRAY[v_raw_id,v_split_id],100);
    END LOOP;
    v_scope:=v_base||jsonb_build_object('target_start',v_month::text,'target_end',v_last::text,'asof',v_month::text,
     'governing_date','REFERENCE_AS_OF','reference_policy','DATED_PROVIDER_SNAPSHOT_ATTRIBUTION_REMAINS_EXPLICIT');
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'reference:massive:'||v_month::text,'REF01','Massive','massive_reference',v_scope,'{}',40);
    v_scope:=v_base||jsonb_build_object('target_start',v_month::text,'target_end',v_last::text,
     'start',to_char(v_month::timestamp AT TIME ZONE 'America/New_York' AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
     'end',to_char(((v_last+1)::timestamp AT TIME ZONE 'America/New_York')-interval '1 microsecond','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
     'governing_date','PUBLICATION_TIMESTAMP','include_weekends_holidays',true,'archive_scope','MASSIVE_ENTITLED_ARCHIVE',
     'permitted_alternative','alpaca_news');
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'news:massive:'||v_month::text,'N01','Massive','massive_news',v_scope,'{}',50);
    IF v_fallback THEN
     v_scope:=v_scope||jsonb_build_object('archive_scope','ALPACA_ENTITLED_ARCHIVE',
      'alternative_reason','MASSIVE_WORKER_CONFIGURATION_UNAVAILABLE','does_not_complete_primary_archive',true,
      'primary_task_id',astra_ingestion_v1.backfill_plan_task_id_v2(r.id,v_key||'news:massive:'||v_month::text));
     v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'news:alpaca:'||v_month::text,'N01','Alpaca','alpaca_news',v_scope,'{}',51);
    END IF;
   END LOOP;
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'reference:massive:2026-07-31','REF01','Massive','massive_reference',
    v_base||jsonb_build_object('asof','2026-07-31','governing_date','REFERENCE_AS_OF'),'{}',40);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'dividends:massive','N02','Massive','massive_dividends',
    v_base||jsonb_build_object('governing_date','DECLARATION_EX_RECORD_PAYMENT_EFFECTIVE_SEPARATE','archive_date_filter','UNBOUNDED_PROVIDER_EVENT_HISTORY','retain_boundary_crossing_events',true),'{}',45);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'splits:massive','N03','Massive','massive_splits',
    v_base||jsonb_build_object('governing_date','EXECUTION_EFFECTIVE_DATE','archive_date_filter','UNBOUNDED_PROVIDER_EVENT_HISTORY','retain_boundary_crossing_events',true),'{}',45);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'actions:alpaca','N02','Alpaca','alpaca_actions',
    v_base||jsonb_build_object('start','2025-06-05','end',(r.created_at AT TIME ZONE 'America/New_York')::date::text,
     'governing_date','PROVIDER_PROCESS_DATE_WITH_SUPPLIED_ACTION_DATES_RETAINED','retain_boundary_crossing_events',true,
     'shared_families',jsonb_build_array('N02','N03')),'{}',45);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'short-volume','S01','Massive','massive_short_volume',
    v_base||jsonb_build_object('start','2025-09-01','end','2026-07-31','governing_date','REPORTING_DATE',
     'reporting_scope','PROVIDER_FINRA_OFF_EXCHANGE_NOT_TOTAL_MARKET'),'{}',60);
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'short-interest','S02','Massive','massive_short_interest',
    v_base||jsonb_build_object('start','2025-09-01','end','2026-07-31','governing_date','SETTLEMENT_DATE',
     'publication_date_filter','NONE','retain_later_publications',true,'availability_policy','ACTUAL_PUBLICATION_WHEN_SUPPLIED_ELSE_RETRIEVAL_UPPER_BOUND'),'{}',60);
   FOREACH v_status IN ARRAY ARRAY['active','inactive'] LOOP
    v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,v_key||'options:'||v_status,'CTX02','Alpaca','alpaca_option_contracts',
     v_base||jsonb_build_object('status',v_status,'expiration_start','2025-09-01','expiration_end','2099-12-31',
      'governing_date','CONTRACT_EXPIRY_REFERENCE_AND_DAILY_MARKET_DATE','include_adjusted_contracts',true,
      'historical_enumeration_completeness','UNKNOWN_UNTIL_PROVIDER_REFERENCE_EXHAUSTED'),'{}',70);
   END LOOP;
   v_next:=m.selection_order+1;v_members:=v_members+1;
  END LOOP;
  IF v_next>3000 THEN v_phase:='BREADTH'; END IF;
 ELSIF v_phase='BREADTH' THEN
  SELECT jsonb_object_agg(member_id,jsonb_build_object('symbol',anchor_ticker,'eligible',NULL) ORDER BY selection_order)
   INTO v_map FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=r.id;
  v_after:=v_breadth;
  FOR v_entry IN SELECT e FROM jsonb_array_elements(v_calendar) e WHERE e->>'date' BETWEEN '2025-09-01' AND '2026-07-31'
   ORDER BY e->>'date' OFFSET v_after LIMIT v_limit
  LOOP
   v_day:=(v_entry->>'date')::date;
   v_scope:=jsonb_build_object('target_start',v_day::text,'target_end',v_day::text,'input_start',v_day::text,
    'market_timezone','America/New_York','calendar',jsonb_build_array(v_entry),'source_family','D03',
    'source_month',date_trunc('month',v_day)::date::text,'representative_security',v_map,
    'representative_policy',v_workflow->'representative_policy','governing_date','MARKET_SESSION',
    'formula_version','fixed3000-derived-v2.1','cohort_classification','RETROSPECTIVE_FIXED_COHORT');
   v_added:=v_added+astra_ingestion_v1.backfill_plan_insert_v2(r.id,r.fence,'CTX06:'||v_day::text,'CTX06','DERIVED','derive_breadth',v_scope,'{}',250);
   v_breadth:=v_breadth+1;
  END LOOP;
  IF v_breadth=230 THEN v_phase:='SEAL'; END IF;
 ELSIF v_phase='SEAL' THEN
  v_snapshot:=astra_ingestion_v1.backfill_plan_snapshot_v2(r.id,500);
  IF v_snapshot->'more'='true'::jsonb THEN RETURN jsonb_build_object('state','SNAPSHOTTING_EXISTING_TASKS','plan_complete',false,'snapshot',v_snapshot); END IF;
  SELECT count(*),encode(sha256(convert_to(COALESCE(string_agg(task_id||':'||definition_sha256,E'\n' ORDER BY task_id COLLATE "C"),''),'UTF8')),'hex')
   INTO v_count,v_hash FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id;
  IF v_count<>v_expected THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Actual static plan count differs from transactionally admitted expected count'; END IF;
  v_result:=astra_ingestion_v1.backfill_seal_plan_v2(r.id,v_expected,v_hash,v_workflow);
  RETURN v_result||jsonb_build_object('run_id',r.id,'plan_complete',v_result->>'state'='FULL_PLAN_SEALED',
   'planned_members',3000,'next_selection_order',3001,'breadth_sessions',230);
 ELSE
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unknown persisted planner phase';
 END IF;
 v_expected:=v_expected+v_added;
 UPDATE astra_ingestion_v1.backfill_runs_v2 SET metadata=r.metadata||jsonb_build_object(
  'planner_phase',v_phase,'planner_next_selection_order',v_next,'planner_next_breadth_index',v_breadth,
  'planner_expected_static_count',v_expected,'workflow_plan',v_workflow,'planner_last_progress_at',clock_timestamp()),
  last_progress_at=CASE WHEN v_added>0 THEN clock_timestamp() ELSE last_progress_at END WHERE id=r.id;
 RETURN jsonb_build_object('state','PLAN_ADVANCED','run_id',r.id,'phase',v_phase,'plan_complete',false,
  'members_admitted_this_call',v_members,'planned_members',v_next-1,'next_selection_order',v_next,
  'breadth_sessions',v_breadth,'inserted_tasks',v_added,'expected_static_task_count',v_expected);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_recheck_page_v2(p_task_id text, p_page_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE p astra_ingestion_v1.backfill_pages_v2; v_hash text; v_counts record; v_saved astra_ingestion_v1.backfill_readbacks_v2; v_reuse jsonb; v_sessions record; v_feature jsonb; v_identity jsonb;v_s02 jsonb;
BEGIN
 SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=p_task_id AND page_no=p_page_no;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Readback page does not exist'; END IF;
 IF p.committed_at>=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Independent readback requires a subsequent transaction'; END IF;
 v_hash:=encode(sha256(convert_to(p.raw_body,'UTF8')),'hex');
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 st WHERE st.id=p.task_id AND st.kind='retained_massive_archive') THEN v_s02:=astra_ingestion_v1.backfill_massive_archive_verify_v2(p.task_id,p.page_no);END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 it WHERE it.id=p.task_id AND it.kind='retained_identity') THEN
  v_identity:=astra_ingestion_v1.backfill_identity_source_verify_v2(p.task_id,p.page_no);
  IF v_identity->'passed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained identity source readback differs'; END IF;
 END IF;
 SELECT count(*)::int total,count(*) FILTER(WHERE target_window)::int target,
  count(*) FILTER(WHERE market_date<'2025-09-01'::date)::int support,
  count(*) FILTER(WHERE market_date IS NULL)::int unknown_date,
  count(*) FILTER(WHERE target_window AND session='RTH')::int rth,
  count(*) FILTER(WHERE target_window AND session='PRE')::int pre,
  count(*) FILTER(WHERE target_window AND session='POST')::int post,
  count(*) FILTER(WHERE target_window AND session='RTH' AND astra_ingestion_v1.backfill_bar_usable_v2(source_row))::int urth,
  count(*) FILTER(WHERE target_window AND session='PRE' AND astra_ingestion_v1.backfill_bar_usable_v2(source_row))::int upre,
  count(*) FILTER(WHERE target_window AND session='POST' AND astra_ingestion_v1.backfill_bar_usable_v2(source_row))::int upost,
  count(*) FILTER(WHERE session IN ('INVALID_TIMESTAMP','CALENDAR_UNRESOLVED','OUTSIDE_SUPPORTED_SESSION'))::int unclassified
 INTO v_counts FROM astra_ingestion_v1.backfill_page_rows_v2(p.task_id,p.page_no);
 IF v_hash<>p.body_sha256 OR v_counts.total<>p.record_count THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Independent stored-source hash or count mismatch'; END IF;

 IF p.raw_body::jsonb#>>'{rows,0,record_type}'='DERIVED_RETAINED_SOURCE_POINTER' THEN
  v_feature:=astra_ingestion_v1.backfill_feature_reuse_verify_v2(p.task_id,p.page_no);
  IF v_feature->'passed' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained feature source readback differs'; END IF;
  v_counts.target:=(v_feature->>'reused_feature_rows')::int;
  v_counts.support:=0;v_counts.unknown_date:=0;
 END IF;
 IF lower(p.provider)='reuse' AND EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 it WHERE it.id=p.task_id AND it.kind='retained_reuse') THEN
  IF to_regprocedure('astra_ingestion_v1.backfill_reuse_verify_v2(text,integer)') IS NULL THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Fixed retained-source verifier is required before pointer readback'; END IF;
  v_reuse:=astra_ingestion_v1.backfill_reuse_verify_v2(p.task_id,p.page_no);
  IF v_reuse->'passed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Retained pointer source digest or aggregate readback differs'; END IF;
  SELECT COALESCE(sum((e->>'record_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int target,
   COALESCE(sum((e->>'record_count')::int) FILTER(WHERE (e->>'market_date')::date<'2025-09-01'::date),0)::int support,
   COALESCE(sum((e->>'qualified_rth_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int rth,
   COALESCE(sum((e->>'qualified_pre_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int pre,
   COALESCE(sum((e->>'qualified_post_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int post,
   COALESCE(sum((e->>'usable_rth_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int urth,
   COALESCE(sum((e->>'usable_pre_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int upre,
   COALESCE(sum((e->>'usable_post_count')::int) FILTER(WHERE (e->>'market_date')::date BETWEEN '2025-09-01'::date AND '2026-07-31'::date),0)::int upost
   INTO v_sessions FROM jsonb_array_elements(v_reuse->'session_coverage') e;
  v_counts.target:=v_sessions.target;v_counts.support:=v_sessions.support;v_counts.unknown_date:=0;
  v_counts.rth:=v_sessions.rth;v_counts.pre:=v_sessions.pre;v_counts.post:=v_sessions.post;
  v_counts.urth:=v_sessions.urth;v_counts.upre:=v_sessions.upre;v_counts.upost:=v_sessions.upost;
  v_counts.unclassified:=COALESCE((v_reuse->>'unknown_session_count')::int,0);
 END IF;
 INSERT INTO astra_ingestion_v1.backfill_readbacks_v2(task_id,page_no,run_id,body_sha256,readback_sha256,expected_records,actual_records,target_records,support_records,unknown_date_records,rth_records,pre_records,post_records,unclassified_session_records,
  usable_rth_records,usable_pre_records,usable_post_records,reused_records,reused_qualified_records,reused_usable_records,retained_source_verification,reused_feature_records,qualified_feature_records,usable_feature_records,retained_feature_verification,retained_identity_verification,retained_s02_verification)
 VALUES(p.task_id,p.page_no,p.run_id,p.body_sha256,v_hash,p.record_count,v_counts.total,v_counts.target,v_counts.support,v_counts.unknown_date,v_counts.rth,v_counts.pre,v_counts.post,v_counts.unclassified,
  v_counts.urth,v_counts.upre,v_counts.upost,COALESCE((v_reuse->>'reused_records')::bigint,0),COALESCE((v_reuse->>'qualifying_profile_count')::bigint,0),COALESCE((v_reuse->>'usable_source_count')::bigint,0),v_reuse,COALESCE((v_feature->>'reused_feature_rows')::int,0),COALESCE((v_feature->>'qualifying_feature_rows')::int,0),COALESCE((v_feature->>'usable_feature_rows')::int,0),v_feature,v_identity,v_s02)
 ON CONFLICT(task_id,page_no) DO NOTHING;
 SELECT * INTO v_saved FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE task_id=p.task_id AND page_no=p.page_no;
 RETURN to_jsonb(v_saved)||jsonb_build_object('state','VERIFIED');
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_request_valid_v2(t astra_ingestion_v1.backfill_tasks_v2, q jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE p text; syms text; h text; token_key text;
BEGIN
 IF lower(t.provider) IN ('derived','reuse') THEN RETURN jsonb_typeof(q)='object'; END IF;
 IF q->>'method' IS DISTINCT FROM 'GET' OR q->>'provider' IS DISTINCT FROM t.provider OR jsonb_typeof(q->'params') IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 SELECT string_agg(s,',' ORDER BY ord) INTO syms FROM jsonb_array_elements_text(t.scope->'symbols') WITH ORDINALITY AS a(s,ord);
 IF syms IS NULL THEN syms:=t.scope->>'symbol'; END IF;
 h:=q->>'host'; p:=q->>'path';
 IF t.provider='Alpaca' THEN
  IF h NOT IN ('data.alpaca.markets','paper-api.alpaca.markets','api.alpaca.markets') THEN RETURN false; END IF;
  token_key:='page_token';
  IF t.kind='alpaca_reference' THEN
   IF h NOT IN ('paper-api.alpaca.markets','api.alpaca.markets') OR p<>('/v2/assets/'||replace(split_part(syms,',',1),'/','%2F')) THEN RETURN false; END IF;
  ELSIF t.kind='alpaca_option_contracts' THEN
   IF h NOT IN ('paper-api.alpaca.markets','api.alpaca.markets') OR p<>'/v2/options/contracts' OR q#>>'{params,underlying_symbols}' IS DISTINCT FROM syms OR q#>>'{params,status}' IS DISTINCT FROM t.scope->>'status' THEN RETURN false; END IF;
  ELSE
   IF h<>'data.alpaca.markets' OR q#>>'{params,symbols}' IS DISTINCT FROM syms
    OR q#>>'{params,start}' IS DISTINCT FROM t.scope->>'start' OR q#>>'{params,end}' IS DISTINCT FROM t.scope->>'end' THEN RETURN false; END IF;
   IF t.kind='alpaca_stock_bars' AND (p<>'/v2/stocks/bars' OR q#>>'{params,feed}'<>'sip' OR q#>>'{params,timeframe}' IS DISTINCT FROM COALESCE(t.scope->>'timeframe','1Min') OR q#>>'{params,adjustment}' IS DISTINCT FROM COALESCE(t.scope->>'adjustment','raw')) THEN RETURN false; END IF;
   IF t.kind='alpaca_option_bars' AND (p<>'/v1beta1/options/bars' OR q#>>'{params,timeframe}'<>'1Day') THEN RETURN false; END IF;
   IF t.kind='alpaca_news' AND p<>'/v1beta1/news' THEN RETURN false; END IF;
   IF t.kind='alpaca_actions' AND p<>'/v1/corporate-actions' THEN RETURN false; END IF;
  END IF;
 ELSE
  IF h<>'api.massive.com' THEN RETURN false; END IF;
  token_key:='cursor';
  IF t.kind='massive_reference' THEN
   IF p<>('/v3/reference/tickers/'||replace(split_part(syms,',',1),'/','%2F')) OR q#>>'{params,date}' IS DISTINCT FROM t.scope->>'asof' THEN RETURN false; END IF;
  ELSIF t.kind='massive_news' THEN
   IF p<>'/v2/reference/news' OR q#>>'{params,ticker}' IS DISTINCT FROM syms OR q#>>'{params,published_utc.gte}' IS DISTINCT FROM t.scope->>'start' OR q#>>'{params,published_utc.lte}' IS DISTINCT FROM t.scope->>'end' THEN RETURN false; END IF;
  ELSE
   IF q#>>'{params,ticker.any_of}' IS DISTINCT FROM syms THEN RETURN false; END IF;
   IF t.kind='massive_dividends' AND p<>'/stocks/v1/dividends' THEN RETURN false; END IF;
   IF t.kind='massive_splits' AND p<>'/stocks/v1/splits' THEN RETURN false; END IF;
   IF t.kind='massive_short_volume' AND (p<>'/stocks/v1/short-volume' OR q#>>'{params,date.gte}' IS DISTINCT FROM t.scope->>'start' OR q#>>'{params,date.lte}' IS DISTINCT FROM t.scope->>'end') THEN RETURN false; END IF;
   IF t.kind='massive_short_interest' AND (p<>'/stocks/v1/short-interest' OR q#>>'{params,settlement_date.gte}' IS DISTINCT FROM t.scope->>'start' OR q#>>'{params,settlement_date.lte}' IS DISTINCT FROM t.scope->>'end') THEN RETURN false; END IF;
  END IF;
 END IF;

 -- backfill_adaptive_page_request_v2: a caller cannot enlarge or omit its claimed limit.
 IF astra_ingestion_v1.backfill_page_limit_cap_v2(t.kind)>1 AND (
  jsonb_typeof(q#>'{params,limit}') IS DISTINCT FROM 'number'
  OR COALESCE(q#>>'{params,limit}','') !~ '^[0-9]{1,5}$'
  OR q#>>'{params,limit}' IS DISTINCT FROM COALESCE(t.page_limit,astra_ingestion_v1.backfill_page_limit_cap_v2(t.kind))::text) THEN RETURN false;END IF;
 IF q->'params'->>token_key IS DISTINCT FROM t.cursor#>>'{}' THEN RETURN false; END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_reuse_commit_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; existing astra_ingestion_v1.backfill_pages_v2;
 s jsonb; pointer jsonb; quality jsonb; raw text; committed jsonb;
 child_scope jsonb; child_id text; children jsonb:='[]'; day text;
 query_start timestamptz; query_end timestamptz; gaps jsonb; parent_calendar jsonb;
BEGIN
 -- A lost acknowledgement is reconciled by reading the immutable receipt.
 SELECT * INTO existing FROM astra_ingestion_v1.backfill_pages_v2
  WHERE task_id=p_payload#>>'{claim,id}' AND page_no=(p_payload#>>'{claim,page_no}')::int;
 IF FOUND THEN
  IF existing.run_id IS DISTINCT FROM p_payload#>>'{claim,run_id}'
   OR existing.generation::text IS DISTINCT FROM p_payload#>>'{claim,generation}'
   OR existing.run_fence::text IS DISTINCT FROM p_payload#>>'{claim,run_fence}' THEN
    RAISE EXCEPTION USING ERRCODE='AI001',MESSAGE='Reuse acknowledgement belongs to another claim'; END IF;
  RETURN jsonb_build_object('state','already_committed','task_id',existing.task_id,'page_no',existing.page_no,
   'body_sha256',existing.body_sha256,'record_count',existing.record_count,
   'reused_records',existing.raw_body::jsonb->'reused_records');
 END IF;
 t:=astra_ingestion_v1.backfill_owned_v2(p_payload->'claim');
 IF t.kind<>'retained_reuse' OR lower(t.provider)<>'reuse' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='A retained-source task is required'; END IF;
 s:=astra_ingestion_v1.backfill_reuse_read_v2(jsonb_build_object('claim',p_payload->'claim','mode','summary'));
 IF s->>'calendar_available' IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Actual exchange calendar is required before planning retained-source gaps'; END IF;
 pointer:=(s-'rows'-'mode'-'state'-'next_after'-'has_more')||jsonb_build_object(
  'record_type','RETAINED_SOURCE_POINTER','reused_records',(s->>'record_count')::int,
  'source_original_unchanged',true,'new_market_rows_written',0);
 quality:=jsonb_build_array(jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED',
  'reason',s->>'mapping_reason','scope','company_attribution','source_preserved',true),
  jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED','reason','UNKNOWN_PROVIDER_OBSERVATION_DENOMINATOR',
  'scope','observation_coverage','expected_bar_slots_are_not_a_trade_denominator',true));
 IF (s->>'record_count')::int<>(s->>'qualifying_profile_count')::int THEN
  quality:=quality||jsonb_build_array(jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED',
    'reason','RETAINED_ROWS_WITH_UNQUALIFIED_PROVIDER_PROFILE','affected_records',
     (s->>'record_count')::int-(s->>'qualifying_profile_count')::int));
 END IF;
 IF (s->>'record_count')::int<>(s->>'valid_ohlcv_count')::int THEN
  quality:=quality||jsonb_build_array(jsonb_build_object('state','IDENTITY_OR_QUALITY_UNRESOLVED',
    'reason','RETAINED_INVALID_OHLCV_REQUIRES_PROVIDER_REPAIR','affected_records',
     (s->>'record_count')::int-(s->>'valid_ohlcv_count')::int));
 END IF;
 raw:=astra_ingestion_v1.rpc_canonical(jsonb_build_object('rows',jsonb_build_array(pointer),
  'reused_records',(s->>'record_count')::int,'receipt_kind','RETAINED_SOURCE_POINTER'));
 committed:=astra_ingestion_v1.backfill_dispatch_v2('backfill_commit',jsonb_build_object(
  'claim',p_payload->'claim','raw_body',raw,'body_sha256',encode(sha256(convert_to(raw,'UTF8')),'hex'),
  'http_status',200,'request_id',NULL,'fetched_at',s->'observed_at',
  'request',jsonb_build_object('provider','REUSE','method','FIXED_RETAINED_READ',
    'source_relation',s->'source_relation','instrument_key',s->'instrument_key',
    'start',s->'start','end_exclusive',s->'end_exclusive'),
  'records',jsonb_build_array(pointer),'next_cursor',NULL,
  'terminal_state','IDENTITY_OR_QUALITY_UNRESOLVED','quality',quality,'headers','{}'::jsonb,
  'adapter_version','fixed3000-retained-pointer-v2.1'));

 -- Existing observations are never relabelled provider-empty. Missing retained
 -- ranges become real Alpaca work in the same transaction as the pointer.
 IF (s->>'record_count')::int=0 THEN gaps:='["WHOLE_SCOPE"]'::jsonb;
 ELSE
  SELECT COALESCE(jsonb_agg(d ORDER BY d),'[]') INTO gaps FROM (
   SELECT DISTINCT value d FROM jsonb_array_elements_text(
    COALESCE(s->'days_without_retained_rows','[]')||COALESCE(s->'days_with_unqualified_profile','[]')||
    COALESCE(s->'days_with_invalid_ohlcv','[]')) a(value)
  ) z;
 END IF;
 FOR day IN SELECT jsonb_array_elements_text(gaps) LOOP
  IF day='WHOLE_SCOPE' THEN
   query_start:=(t.scope->>'start')::timestamptz;
   query_end:=(t.scope->>'end_exclusive')::timestamptz-interval '1 microsecond';
   parent_calendar:=t.scope->'calendar';
  ELSE
   query_start:=(day::date+time '04:00') AT TIME ZONE 'America/New_York';
   query_end:=((day::date+time '20:00') AT TIME ZONE 'America/New_York')-interval '1 microsecond';
   SELECT COALESCE(jsonb_agg(x),'[]') INTO parent_calendar FROM jsonb_array_elements(t.scope->'calendar') x WHERE x->>'date'=day;
  END IF;
  child_scope:=jsonb_build_object('symbols',jsonb_build_array(t.scope->>'symbol'),
    'member_ids',t.scope->'member_ids','start',to_char(query_start AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'end',to_char(query_end AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'timeframe','1Min','feed','sip','adjustment','raw',
    'asof',COALESCE(t.scope->>'asof','2026-08-03'),'calendar',parent_calendar,
    'target_start',t.scope->'target_start','target_end',t.scope->'target_end',
    'market_timezone','America/New_York','identity_status','UNRESOLVED_PROVIDER_ANCHOR',
    'reuse_parent',t.id,'gap_reason',CASE WHEN day='WHOLE_SCOPE' THEN 'NO_RETAINED_ROWS' ELSE 'RETAINED_SESSION_MISSING_OR_UNQUALIFIED' END);
  child_id:='backfill-gap-'||encode(sha256(convert_to(t.run_id||':'||astra_ingestion_v1.rpc_canonical(child_scope),'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,priority,run_fence)
   VALUES(child_id,t.run_id,'P01','Alpaca','alpaca_stock_bars',child_scope,t.priority+1,t.run_fence)
   ON CONFLICT(id) DO NOTHING;
  children:=children||jsonb_build_array(child_id);
 END LOOP;
 RETURN committed||jsonb_build_object('reused_records',(s->>'record_count')::int,
  'qualifying_reused_records',(s->>'qualifying_profile_count')::int,'provider_children',children,
  'new_market_rows_written',0);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_reuse_verify_v2(p_task_id text, p_page_no integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
 SET lock_timeout TO '1s'
AS $function$
DECLARE
 p_payload jsonb:=jsonb_build_object('mode','summary');
 p astra_ingestion_v1.backfill_pages_v2%ROWTYPE;
 v_pointer jsonb;
 v_actual jsonb;
 v_key text;
 v_mismatches jsonb:='[]'::jsonb;
 t astra_ingestion_v1.backfill_tasks_v2%ROWTYPE;
 active_task astra_ingestion_v1.backfill_tasks_v2%ROWTYPE;
 source_task astra_ingestion_v1.backfill_tasks_v2%ROWTYPE;
 r astra_ingestion_v1.backfill_runs_v2%ROWTYPE;
 m astra_ingestion_v1.backfill_members_v2%ROWTYPE;
 i reference.alpaca_fixed_window_instruments_v1%ROWTYPE;
 c jsonb:=p_payload->'claim';
 v_start timestamptz;
 v_end timestamptz;
 v_after timestamptz;
 v_mode text:=COALESCE(p_payload->>'mode','summary');
 v_limit int:=GREATEST(1,LEAST(COALESCE((p_payload->>'limit')::int,2000),2000));
 v_result jsonb;
 v_count int;
BEGIN
 -- Post-commit readback requires no fabricated lease, reopening, provider call or write.
 IF p_task_id IS NULL OR length(p_task_id) NOT BETWEEN 8 AND 200 OR p_page_no IS NULL OR p_page_no<0 THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Invalid committed retained-pointer reference'; END IF;
 SELECT * INTO p FROM astra_ingestion_v1.backfill_pages_v2 WHERE task_id=p_task_id AND page_no=p_page_no;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Committed retained pointer was not found'; END IF;
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p.task_id;
 IF t.run_id IS DISTINCT FROM p.run_id OR t.kind<>'retained_reuse' OR lower(t.provider)<>'reuse'
 OR t.status NOT IN ('INGESTED','IDENTITY_OR_QUALITY_UNRESOLVED') OR t.page_no<=p_page_no
 OR p.record_count<>1 OR p.cursor_out IS NOT NULL
 OR encode(sha256(convert_to(p.raw_body,'UTF8')),'hex') IS DISTINCT FROM p.body_sha256 THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Committed retained-pointer envelope is inconsistent'; END IF;
 PERFORM astra_ingestion_v1.rpc_json_unique(p.raw_body::json);
 IF jsonb_typeof(p.raw_body::jsonb->'rows') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p.raw_body::jsonb->'rows')<>1
 OR encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(p.raw_body::jsonb->'rows'),'UTF8')),'hex') IS DISTINCT FROM p.records_sha256 THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Committed retained-pointer records digest differs'; END IF;
 v_pointer:=p.raw_body::jsonb#>'{rows,0}';
 IF v_pointer->>'record_type' IS DISTINCT FROM 'RETAINED_SOURCE_POINTER'
 OR v_pointer->'reused_records' IS DISTINCT FROM p.raw_body::jsonb->'reused_records' THEN
   RAISE EXCEPTION USING ERRCODE='AI002',MESSAGE='Committed retained-pointer identity or count envelope differs'; END IF;
 active_task:=t;
 IF t.kind IN ('derive_daily','derive_intraday') AND lower(t.provider)='derived'
 AND t.family IN ('D01','D02','D03','D04','D05') AND v_mode='material' THEN
   IF p_payload->>'source_task_id' IS NULL OR NOT (p_payload->>'source_task_id'=ANY(t.dependencies)) THEN
     RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained material must be a direct immutable dependency'; END IF;
   SELECT * INTO source_task FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_payload->>'source_task_id';
   IF NOT FOUND OR source_task.run_id<>t.run_id OR source_task.kind<>'retained_reuse'
   OR lower(source_task.provider)<>'reuse'
   OR source_task.status NOT IN ('INGESTED','IDENTITY_OR_QUALITY_UNRESOLVED')
   OR source_task.scope->'member_ids' IS DISTINCT FROM t.scope->'member_ids' THEN
     RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained dependency is not committed for the same frozen member'; END IF;
   t:=source_task;
 ELSIF t.kind<>'retained_reuse' OR lower(t.provider)<>'reuse'
 OR t.family NOT IN ('P01','P02','D01','D02') THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Task kind cannot access retained source material';
 END IF;
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=t.run_id;
 IF r.id IS DISTINCT FROM p.run_id
 OR r.cohort_sha256<>'2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec'
 OR r.target_start<>'2025-09-01'::date OR r.target_end<>'2026-07-31'::date
 OR jsonb_typeof(t.scope->'member_ids') IS DISTINCT FROM 'array'
 OR jsonb_array_length(t.scope->'member_ids')<>1 THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained-read frozen replacement scope differs';
 END IF;
 SELECT * INTO STRICT m FROM astra_ingestion_v1.backfill_members_v2
  WHERE run_id=t.run_id AND member_id=t.scope#>>'{member_ids,0}';
 SELECT * INTO STRICT i FROM reference.alpaca_fixed_window_instruments_v1
  WHERE instrument_key=(t.scope->>'instrument_key')::int;
 IF i.alpaca_asset_id::text IS DISTINCT FROM t.scope->>'alpaca_asset_id'
 OR i.symbol IS DISTINCT FROM t.scope->>'symbol' OR i.symbol IS DISTINCT FROM m.anchor_ticker THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained provider security and frozen anchor differ';
 END IF;
 -- Anchor equality permits raw-source reuse only. It does not prove a dated
 -- historical company/security mapping; this limitation is always returned.
 v_start:=(t.scope->>'start')::timestamptz;
 v_end:=(t.scope->>'end_exclusive')::timestamptz;
 IF v_start IS NULL OR v_end IS NULL OR NOT pg_catalog.isfinite(v_start) OR NOT pg_catalog.isfinite(v_end)
 OR v_start>=v_end OR v_end-v_start>interval '32 days'
 OR v_start<('2025-08-04 00:00:00'::timestamp AT TIME ZONE 'America/New_York')
 OR v_end>('2026-08-01 00:00:00'::timestamp AT TIME ZONE 'America/New_York')
 OR date_trunc('month',v_start AT TIME ZONE 'America/New_York')<>
    date_trunc('month',(v_end-interval '1 microsecond') AT TIME ZONE 'America/New_York') THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained-read range must fit one admitted calendar month';
 END IF;
 IF p_payload->>'after' IS NOT NULL THEN
   v_after:=(p_payload->>'after')::timestamptz;
   IF NOT pg_catalog.isfinite(v_after) OR v_after<v_start OR v_after>=v_end THEN
    RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained-read cursor is outside the immutable range'; END IF;
 END IF;
 -- A derivation can read only the intersection of its own input window and
 -- its committed retained dependency. The caller cannot widen either scope.
 IF active_task.kind IN ('derive_daily','derive_intraday') THEN
   IF active_task.scope->>'input_start' IS NOT NULL THEN
     v_start:=GREATEST(v_start,(active_task.scope->>'input_start')::date::timestamp AT TIME ZONE 'America/New_York');
   END IF;
   IF active_task.scope->>'target_end' IS NOT NULL THEN
     v_end:=LEAST(v_end,((active_task.scope->>'target_end')::date+1)::timestamp AT TIME ZONE 'America/New_York');
   END IF;
   IF v_after IS NOT NULL AND (v_after<v_start OR v_after>=v_end) THEN
     RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained material cursor is outside derived input scope'; END IF;
 END IF;
 IF v_mode='summary' AND v_after IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='A retained summary must cover its whole immutable range';
 END IF;

 WITH bounded AS MATERIALIZED (
  SELECT b.instrument_key,b.bar_ts,b.session_label::text AS session_label,
    b.open,b.high,b.low,b.close,b.volume,b.trade_count,b.vwap,b.loaded_by_job_id,b.source_loaded_at
  FROM market_fixed_20250901_20260831.alpaca_sip_bars_1m b
  WHERE b.instrument_key=i.instrument_key AND b.bar_ts>=v_start AND b.bar_ts<v_end
    AND (v_after IS NULL OR b.bar_ts>v_after)
  ORDER BY b.bar_ts LIMIT CASE WHEN v_mode='summary' THEN 40001 ELSE v_limit+1 END
 ), measured AS MATERIALIZED (
  SELECT b.*,j.id AS provenance_job_id,
   COALESCE(j.config->>'feed'='sip' AND j.config->>'adjustment'='raw'
    AND j.config->'timeframes' @> '["1Min"]'::jsonb
    AND (j.config->>'start_date')::date<=(b.bar_ts AT TIME ZONE 'America/New_York')::date
    AND (j.config->>'end_date')::date>=(b.bar_ts AT TIME ZONE 'America/New_York')::date,false) AS qualifying_profile,
   COALESCE(b.open>0 AND b.high>0 AND b.low>0 AND b.close>0 AND b.volume>=0
    AND b.high>=GREATEST(b.open,b.close,b.low) AND b.low<=LEAST(b.open,b.close,b.high)
    AND b.open NOT IN ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8)
    AND b.high NOT IN ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8)
    AND b.low NOT IN ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8)
    AND b.close NOT IN ('Infinity'::float8,'-Infinity'::float8,'NaN'::float8),false) AS valid_ohlcv,
   encode(sha256(convert_to(to_jsonb(b)::text,'UTF8')),'hex') AS row_sha256
  FROM bounded b LEFT JOIN market_provenance.alpaca_populator_jobs_v1 j ON j.id=b.loaded_by_job_id
 ), selected AS MATERIALIZED (
  SELECT * FROM measured ORDER BY bar_ts LIMIT CASE WHEN v_mode='summary' THEN 40001 ELSE v_limit END
 )
 SELECT jsonb_build_object(
   'record_count',count(*),'qualifying_profile_count',count(*) FILTER(WHERE qualifying_profile),
   'valid_ohlcv_count',count(*) FILTER(WHERE valid_ohlcv),
   'usable_source_count',count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv),
   'first_bar',min(bar_ts),'last_bar',max(bar_ts),
   'source_digest',encode(sha256(convert_to(COALESCE(string_agg(row_sha256,'' ORDER BY bar_ts),''),'UTF8')),'hex'),
   'digest_algorithm','sha256-concatenated-ordered-postgres-jsonb-row-sha256-v1',
   'rth_count',count(*) FILTER(WHERE session_label='regular'),
   'pre_count',count(*) FILTER(WHERE session_label='premarket'),
   'post_count',count(*) FILTER(WHERE session_label='postmarket'),
   'qualified_rth_count',count(*) FILTER(WHERE qualifying_profile AND session_label='regular'),
   'qualified_pre_count',count(*) FILTER(WHERE qualifying_profile AND session_label='premarket'),
   'qualified_post_count',count(*) FILTER(WHERE qualifying_profile AND session_label='postmarket'),
   'usable_rth_count',count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv AND session_label='regular'),
   'usable_pre_count',count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv AND session_label='premarket'),
   'usable_post_count',count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv AND session_label='postmarket'),
   'overnight_count',count(*) FILTER(WHERE session_label='overnight'),
   'unknown_session_count',count(*) FILTER(WHERE session_label NOT IN ('regular','premarket','postmarket','overnight') OR session_label IS NULL),
   'source_job_ids',COALESCE(jsonb_agg(DISTINCT loaded_by_job_id) FILTER(WHERE loaded_by_job_id IS NOT NULL),'[]'),
   'source_loaded_at_min',min(source_loaded_at),'source_loaded_at_max',max(source_loaded_at),
   'session_coverage',CASE WHEN v_mode='summary' THEN (
     SELECT COALESCE(jsonb_agg(z ORDER BY z.market_date),'[]') FROM (
       SELECT (bar_ts AT TIME ZONE 'America/New_York')::date AS market_date,
        count(*) AS record_count,count(*) FILTER(WHERE qualifying_profile) AS qualifying_profile_count,
        count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv) AS usable_source_count,
        count(*) FILTER(WHERE session_label='regular') AS rth_count,
        count(*) FILTER(WHERE session_label='premarket') AS pre_count,
        count(*) FILTER(WHERE session_label='postmarket') AS post_count,
        count(*) FILTER(WHERE qualifying_profile AND session_label='regular') AS qualified_rth_count,
        count(*) FILTER(WHERE qualifying_profile AND session_label='premarket') AS qualified_pre_count,
        count(*) FILTER(WHERE qualifying_profile AND session_label='postmarket') AS qualified_post_count,
        count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv AND session_label='regular') AS usable_rth_count,
        count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv AND session_label='premarket') AS usable_pre_count,
        count(*) FILTER(WHERE qualifying_profile AND valid_ohlcv AND session_label='postmarket') AS usable_post_count,
        min(bar_ts) AS first_bar,max(bar_ts) AS last_bar
       FROM selected GROUP BY 1) z) ELSE '[]'::jsonb END,
   'days_without_retained_rows',CASE WHEN v_mode='summary' THEN (
     SELECT COALESCE(jsonb_agg(e->>'date' ORDER BY e->>'date'),'[]')
     FROM jsonb_array_elements(COALESCE(t.scope->'calendar','[]'::jsonb)) e
     WHERE (e->>'date')::date>=(v_start AT TIME ZONE 'America/New_York')::date
       AND (e->>'date')::date<=((v_end-interval '1 microsecond') AT TIME ZONE 'America/New_York')::date
       AND NOT EXISTS(SELECT 1 FROM selected s WHERE (s.bar_ts AT TIME ZONE 'America/New_York')::date=(e->>'date')::date)
   ) ELSE '[]'::jsonb END,
   'days_with_unqualified_profile',CASE WHEN v_mode='summary' THEN (
     SELECT COALESCE(jsonb_agg(z.market_date ORDER BY z.market_date),'[]') FROM (
       SELECT DISTINCT (bar_ts AT TIME ZONE 'America/New_York')::date AS market_date FROM selected WHERE NOT qualifying_profile) z
   ) ELSE '[]'::jsonb END,
   'days_with_invalid_ohlcv',CASE WHEN v_mode='summary' THEN (
     SELECT COALESCE(jsonb_agg(z.market_date ORDER BY z.market_date),'[]') FROM (
       SELECT DISTINCT (bar_ts AT TIME ZONE 'America/New_York')::date AS market_date FROM selected WHERE NOT valid_ohlcv) z
   ) ELSE '[]'::jsonb END,
   'has_more',CASE WHEN v_mode='material' THEN (SELECT count(*) FROM bounded)>v_limit ELSE false END,
   'next_after',CASE WHEN v_mode='material' AND (SELECT count(*) FROM bounded)>v_limit THEN max(bar_ts) END,
   'rows',CASE WHEN v_mode='material' THEN COALESCE(jsonb_agg(jsonb_build_object(
     'symbol',i.symbol,'timestamp',bar_ts,'market_date',(bar_ts AT TIME ZONE 'America/New_York')::date,
     'session',CASE session_label WHEN 'regular' THEN 'RTH' WHEN 'premarket' THEN 'PRE' WHEN 'postmarket' THEN 'POST' ELSE 'OUTSIDE_SUPPORTED_SESSION' END,
     'timeframe','1Min','feed','sip','adjustment','raw','saved_session_label',session_label,
     'source',jsonb_build_object('t',bar_ts,'o',open,'h',high,'l',low,'c',close,'v',volume,'n',trade_count,'vw',vwap),
     'instrument_key',instrument_key,'alpaca_asset_id',i.alpaca_asset_id,'loaded_by_job_id',loaded_by_job_id,
     'source_loaded_at',source_loaded_at,'source_row_sha256',row_sha256,
     'provenance_qualified',qualifying_profile,'valid_ohlcv',valid_ohlcv,
     'support_history',(bar_ts AT TIME ZONE 'America/New_York')::date<'2025-09-01'::date,
     'mapping_state','IDENTITY_OR_QUALITY_UNRESOLVED') ORDER BY bar_ts),'[]') ELSE '[]'::jsonb END
 ) INTO v_result FROM selected;
 v_count:=(v_result->>'record_count')::int;
 IF v_mode='summary' AND v_count>40000 THEN
   RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Retained summary exceeded40000 rows; split its date unit';
 END IF;
 v_actual:=v_result||jsonb_build_object(
   'state',CASE WHEN v_count=0 THEN 'NO_RETAINED_ROWS' ELSE 'RETAINED_SOURCE_READ' END,
   'mode',v_mode,'task_id',active_task.id,'source_task_id',t.id,'run_id',t.run_id,'member_id',m.member_id,
   'source_relation','market_fixed_20250901_20260831.alpaca_sip_bars_1m',
   'source_project','oxzabweahkoimtevbbny','original_source_project','mnmkxjirpwbptdnvjmpw',
   'instrument_key',i.instrument_key,'alpaca_asset_id',i.alpaca_asset_id,'symbol',i.symbol,
   'start',v_start,'end_exclusive',v_end,'observed_at',clock_timestamp(),
   'provider','Alpaca','feed','sip','adjustment','raw','timeframe','1Min',
   'mapping_state','IDENTITY_OR_QUALITY_UNRESOLVED',
   'mapping_reason','POST_WINDOW_ANCHOR_SYMBOL_MATCH_IS_NOT_HISTORICAL_IDENTITY_PROOF',
   'calendar_available',COALESCE(jsonb_typeof(t.scope->'calendar')='array',false),
   'coverage_state','UNKNOWN_PROVIDER_OBSERVATION_DENOMINATOR',
   'source_reference_provenance',i.provenance);
 FOR v_key IN SELECT jsonb_object_keys(v_actual) LOOP
   IF v_key IN ('observed_at','state','mode','rows','next_after','has_more') THEN CONTINUE; END IF;
   IF v_key='source_job_ids' THEN
     IF jsonb_typeof(v_pointer->v_key) IS DISTINCT FROM 'array'
       OR NOT ((v_pointer->v_key) @> (v_actual->v_key) AND (v_actual->v_key) @> (v_pointer->v_key))
       OR jsonb_array_length(v_pointer->v_key)<>jsonb_array_length(v_actual->v_key) THEN
       v_mismatches:=v_mismatches||jsonb_build_array(v_key); END IF;
   ELSIF v_pointer->v_key IS DISTINCT FROM v_actual->v_key THEN
     v_mismatches:=v_mismatches||jsonb_build_array(v_key);
   END IF;
 END LOOP;
 IF v_pointer->'reused_records' IS DISTINCT FROM v_actual->'record_count' THEN
   v_mismatches:=v_mismatches||jsonb_build_array('reused_records'); END IF;
 RETURN v_actual||jsonb_build_object(
   'state',CASE WHEN jsonb_array_length(v_mismatches)=0 THEN 'REUSE_SOURCE_VERIFIED' ELSE 'REUSE_SOURCE_MISMATCH' END,
   'passed',jsonb_array_length(v_mismatches)=0,'page_no',p.page_no,
   'receipt_record_count',p.record_count,'reused_records',v_actual->'record_count',
   'expected_reused_records',v_pointer->'reused_records',
   'expected_source_digest',v_pointer->'source_digest',
   'pointer_body_sha256',p.body_sha256,'mismatched_fields',v_mismatches,
   'verification_kind','COMMITTED_RETAINED_POINTER_SOURCE_READBACK_V1');
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_seal_plan_v2(p_run_id text, p_expected_count bigint, p_expected_sha256 text, p_workflow_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE r astra_ingestion_v1.backfill_runs_v2; v_count bigint; v_hash text; v_trading datemultirange; v_calendar datemultirange; v_missing jsonb;
BEGIN
 SELECT * INTO STRICT r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=p_run_id FOR UPDATE;
 IF r.status<>'ACTIVE' OR EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_plan_manifests_v2 WHERE run_id=r.id) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Only an active unsealed replacement plan may be sealed'; END IF;
 IF jsonb_typeof(p_workflow_plan) IS DISTINCT FROM 'object' OR length(COALESCE(p_workflow_plan->>'version',''))=0
  OR p_workflow_plan->>'target_start' IS DISTINCT FROM '2025-09-01' OR p_workflow_plan->>'target_end' IS DISTINCT FROM '2026-07-31'
  OR p_workflow_plan->>'market_timezone' IS DISTINCT FROM 'America/New_York' OR length(COALESCE(p_workflow_plan->>'representative_policy',''))=0
  OR jsonb_typeof(p_workflow_plan->'session_dates') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Plan sealing requires explicit fixed-window, calendar and representative policy evidence'; END IF;
 SELECT range_agg(daterange(d,d+1,'[)')) INTO v_trading FROM (SELECT DISTINCT value::date d FROM jsonb_array_elements_text(p_workflow_plan->'session_dates')) x;
 IF (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_workflow_plan->'session_dates'))<>230
  OR (SELECT encode(sha256(convert_to(string_agg(value,E'\n' ORDER BY value),'UTF8')),'hex') FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(p_workflow_plan->'session_dates')) s)
     <>'acb2972a35b3458a6a41dfeaca34abea14cd0c228183b9dca602cb59deb0d9d6'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_workflow_plan->'session_dates') d WHERE d::date<r.target_start OR d::date>r.target_end) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Frozen target exchange calendar must contain the retained 230 sessions'; END IF;
 v_calendar:=datemultirange(daterange(r.target_start,r.target_end+1,'[)'));
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 q WHERE q.run_id=r.id
  AND NOT ((q.kind='alpaca_option_bars' AND q.scope ? 'enumeration_parent') OR q.scope ? 'reuse_parent')
  AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_plan_units_v2 p WHERE p.task_id=q.id)) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Static task snapshots are incomplete; continue bounded backfill_plan_snapshot'; END IF;
 SELECT count(*),encode(sha256(convert_to(COALESCE(string_agg(task_id||':'||definition_sha256,E'\n' ORDER BY task_id COLLATE "C"),''),'UTF8')),'hex')
 INTO v_count,v_hash FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id;
 IF v_count IS DISTINCT FROM p_expected_count OR v_hash IS DISTINCT FROM p_expected_sha256 THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Stored task count/hash differs from the expected complete workflow manifest'; END IF;
 v_missing:=astra_ingestion_v1.backfill_plan_coverage_check_v2(r.id,v_trading,v_calendar);
 IF jsonb_array_length(v_missing->'missing_member_date_workflows')>0 THEN
  RETURN jsonb_build_object('state','INCOMPLETE_MEMBER_DATE_WORKFLOWS','evidence',v_missing); END IF;
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id AND family='CTX06')
  OR EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id AND family='CTX06' AND representative_map_valid IS DISTINCT FROM true) THEN
  RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Every breadth unit needs an explicit representative map for the exact 3000 frozen companies'; END IF;
 INSERT INTO astra_ingestion_v1.backfill_plan_manifests_v2(run_id,expected_task_count,expected_plan_sha256,workflow_plan,required_trading_dates,required_calendar_dates)
 VALUES(r.id,v_count,v_hash,p_workflow_plan,v_trading,v_calendar);
 UPDATE astra_ingestion_v1.backfill_runs_v2 SET metadata=metadata||jsonb_build_object('planning_complete',true,'expected_static_task_count',v_count,'expected_plan_sha256',v_hash,'workflow_plan',p_workflow_plan) WHERE id=r.id;
 INSERT INTO astra_ingestion_v1.backfill_audit_v2(run_id,action,evidence) VALUES(r.id,'FULL_PLAN_SEALED',jsonb_build_object('expected_task_count',v_count,'expected_plan_sha256',v_hash,'cohort_sha256',r.cohort_sha256));
 RETURN jsonb_build_object('state','FULL_PLAN_SEALED','expected_task_count',v_count,'expected_plan_sha256',v_hash);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_shared_meta_v2(p_provider text, p_kind text, p_group text, p_symbol text, p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE typ text;grp text;pid text;basis text;key_value jsonb;row_hash text;d date;stamp timestamptz;axes jsonb;spec jsonb;fields jsonb;
 links jsonb:='[]';families text[];item jsonb;token text;role text;v jsonb;dt text;primary_date_field text;
BEGIN
 typ:=CASE WHEN p_kind IN('massive_news','alpaca_news') THEN 'ARTICLE' WHEN p_kind='alpaca_option_contracts' THEN 'CONTRACT_REFERENCE'
  WHEN p_kind='alpaca_option_bars' THEN 'OPTION_DAILY_BAR' ELSE 'ACTION' END;
 grp:=CASE WHEN p_kind='massive_dividends' THEN 'DIVIDEND' WHEN p_kind='massive_splits' THEN 'SPLIT' ELSE p_group END;
 families:=CASE WHEN typ='ARTICLE' THEN ARRAY['N01'] WHEN typ IN('CONTRACT_REFERENCE','OPTION_DAILY_BAR') THEN ARRAY['CTX02']
  WHEN p_kind='massive_splits' THEN ARRAY['N03'] WHEN p_kind='alpaca_actions' AND p_group IN('forward_splits','reverse_splits','unit_splits') THEN ARRAY['N02','N03'] ELSE ARRAY['N02'] END;
 row_hash:=encode(sha256(convert_to(p_row::text,'UTF8')),'hex');
 pid:=CASE WHEN jsonb_typeof(p_row->'id') IN('string','number') AND length(p_row->>'id') BETWEEN 1 AND 512 THEN p_row->>'id' END;
 basis:='PROVIDER_RECORD_ID';key_value:=jsonb_build_array(typ,CASE WHEN typ='ACTION' THEN grp ELSE '' END,pid);
 IF typ='OPTION_DAILY_BAR' THEN
  stamp:=astra_ingestion_v1.backfill_stamp_v2(p_row->>'t');d:=(stamp AT TIME ZONE 'America/New_York')::date;
  IF p_symbol ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' AND d IS NOT NULL THEN basis:='PROVIDER_CONTRACT_SYMBOL_SESSION_OPRA';key_value:=jsonb_build_array(typ,p_symbol,d,'opra','1Day');
  ELSE basis:='EXACT_CONTENT_FALLBACK_SEMANTIC_IDENTITY_UNKNOWN';key_value:=jsonb_build_array(typ,p_symbol,'opra','1Day',row_hash);END IF;
 ELSIF typ='CONTRACT_REFERENCE' AND p_row->>'symbol' ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' THEN
  basis:='PROVIDER_CONTRACT_SYMBOL';key_value:=jsonb_build_array(typ,p_row->>'symbol');
 ELSIF pid IS NULL THEN
  basis:='EXACT_CONTENT_FALLBACK_SEMANTIC_IDENTITY_UNKNOWN';key_value:=jsonb_build_array(typ,grp,row_hash);
 END IF;
 axes:='{}';
 IF typ='ARTICLE' THEN
  primary_date_field:=CASE WHEN p_kind='massive_news' THEN 'published_utc' ELSE 'created_at' END;
  stamp:=astra_ingestion_v1.backfill_stamp_v2(p_row->>primary_date_field);d:=(stamp AT TIME ZONE 'America/New_York')::date;
  axes:=jsonb_build_object('publication_date_new_york',d);
  v:=CASE WHEN p_kind='massive_news' THEN p_row->'tickers' ELSE p_row->'symbols' END;
  FOR item IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v)='array' THEN v ELSE '[]' END) LOOP
   token:=item#>>'{}';IF jsonb_typeof(item)='string' AND token ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' THEN links:=links||jsonb_build_array(jsonb_build_object('symbol',upper(token),'role','ARTICLE_SECURITY'));END IF;
  END LOOP;
 ELSIF typ='ACTION' THEN
  SELECT COALESCE(jsonb_object_agg(key,astra_ingestion_v1.backfill_date_v2(value#>>'{}')),'{}') INTO axes FROM jsonb_each(p_row)
   WHERE key IN('announcement_date','declaration_date','ex_date','ex_dividend_date','record_date','pay_date','payable_date','payment_date','execution_date','effective_date','process_date');
  primary_date_field:=CASE WHEN p_kind='massive_dividends' THEN 'ex_dividend_date' WHEN p_kind='massive_splits' THEN 'execution_date'
   WHEN p_row ? 'effective_date' THEN 'effective_date' WHEN p_row ? 'ex_date' THEN 'ex_date' ELSE 'process_date' END;
  d:=astra_ingestion_v1.backfill_date_v2(p_row->>primary_date_field);
  FOR token,role IN SELECT p_row->>'ticker','SECURITY' UNION ALL SELECT p_row->>'symbol','SECURITY'
   UNION ALL SELECT p_row->>'initiating_symbol','INITIATING_SECURITY' UNION ALL SELECT p_row->>'target_symbol','TARGET_SECURITY' LOOP
   IF token ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' THEN links:=links||jsonb_build_array(jsonb_build_object('symbol',upper(token),'role',role));END IF;
  END LOOP;
 ELSIF typ='CONTRACT_REFERENCE' THEN
  primary_date_field:='expiration_date';d:=astra_ingestion_v1.backfill_date_v2(p_row->>'expiration_date');axes:=jsonb_build_object('expiration_date',d);
  token:=p_row->>'underlying_symbol';IF token ~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' THEN links:=jsonb_build_array(jsonb_build_object('symbol',upper(token),'role','CONTRACT_UNDERLYING'));END IF;
 ELSE primary_date_field:='t';axes:=jsonb_build_object('market_session_new_york',d);END IF;
 spec:=astra_ingestion_v1.backfill_nonminute_field_spec_v2(families[1],p_kind);
 IF p_kind='massive_news' THEN spec:=spec||'{"updated_utc":"timestamp"}'::jsonb;END IF;
 IF p_kind='alpaca_actions' AND families @> ARRAY['N03'] THEN spec:=spec||'{"ex_date":"date","old_rate":"positive","new_rate":"positive"}'::jsonb;END IF;
 -- Preserve hashes for every supplied field so unmodelled conflicts are not
 -- silently selected. Unknown field semantics are not called usable.
 SELECT COALESCE(jsonb_object_agg(f.key,jsonb_build_object('datatype',COALESCE(spec->>f.key,'undeclared'),
  'nonnull',p_row->f.key IS NOT NULL AND p_row->f.key<>'null'::jsonb,
  'value_sha256',CASE WHEN p_row ? f.key THEN encode(sha256(convert_to((p_row->f.key)::text,'UTF8')),'hex') ELSE 'ABSENT' END,
  'reason',astra_ingestion_v1.backfill_nonminute_field_reason_v2(p_row->f.key,COALESCE(spec->>f.key,'undeclared'),NULL))),'{}') INTO fields
 FROM(SELECT jsonb_object_keys(spec||p_row) key) f;
 RETURN jsonb_build_object('record_key',p_provider||':'||typ||':'||encode(sha256(convert_to(key_value::text,'UTF8')),'hex'),'row_sha256',row_hash,
  'provider',p_provider,'record_type',typ,'kind',p_kind,'record_group',grp,'provider_record_id',pid,'identity_basis',basis,
  'symbol',CASE WHEN typ='ARTICLE' THEN NULL WHEN typ='OPTION_DAILY_BAR' THEN p_symbol ELSE COALESCE(p_row->>'ticker',p_row->>'symbol',p_row->>'initiating_symbol') END,
  'market_date',d,'date_axes',axes,'primary_date_field',primary_date_field,
  'version_timestamp',astra_ingestion_v1.backfill_stamp_v2(COALESCE(p_row->>'updated_utc',p_row->>'updated_at')),
  'field_states',fields,'delivery_families',to_jsonb(families),'links',links);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_shared_project_v2(p_task text, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '12s'
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2;p astra_ingestion_v1.backfill_pages_v2;keys jsonb;old_summary jsonb;families text[];
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task;
 IF t.kind NOT IN('alpaca_news','massive_news','alpaca_actions','massive_dividends','massive_splits','alpaca_option_contracts','alpaca_option_bars') THEN RETURN jsonb_build_object('state','SEPARATE_FAMILY');END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(t.run_id,706314020261099));
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_shared_pages_v2 WHERE task_id=p_task AND page_no=p_page) THEN RETURN jsonb_build_object('state','ALREADY_PROJECTED');END IF;
 SELECT pg.* INTO STRICT p FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
  WHERE pg.task_id=p_task AND pg.page_no=p_page AND pg.body_sha256=b.body_sha256 AND b.body_sha256=b.readback_sha256 AND pg.record_count=b.actual_records;
 WITH rows AS MATERIALIZED(SELECT x.record_ordinal,astra_ingestion_v1.backfill_shared_meta_v2(t.provider,t.kind,x.record_group,x.symbol,x.source_row) m
  FROM astra_ingestion_v1.backfill_page_rows_v2(p_task,p_page) x),
 versions AS(INSERT INTO astra_ingestion_v1.backfill_shared_versions_v2
  SELECT DISTINCT ON(m->>'record_key',m->>'row_sha256') t.run_id,m->>'record_key',m->>'row_sha256',m->>'provider',m->>'record_type',m->>'kind',m->>'record_group',
   m->>'provider_record_id',m->>'identity_basis',m->>'symbol',(m->>'market_date')::date,m->'date_axes',m->>'primary_date_field',
   (m->>'version_timestamp')::timestamptz,m->'field_states',ARRAY(SELECT jsonb_array_elements_text(m->'delivery_families')),t.id,p_page,record_ordinal
  FROM rows ORDER BY m->>'record_key',m->>'row_sha256',record_ordinal ON CONFLICT DO NOTHING RETURNING record_key),
 occurrences AS(INSERT INTO astra_ingestion_v1.backfill_shared_occurrences_v2
  SELECT t.run_id,m->>'record_key',m->>'row_sha256',t.id,p_page,record_ordinal FROM rows ON CONFLICT DO NOTHING RETURNING record_key),
 links AS(INSERT INTO astra_ingestion_v1.backfill_shared_version_links_v2
  SELECT DISTINCT t.run_id,m->>'record_key',m->>'row_sha256',l->>'symbol',l->>'role' FROM rows CROSS JOIN LATERAL jsonb_array_elements(m->'links') l
  ON CONFLICT DO NOTHING RETURNING record_key)
 SELECT COALESCE(jsonb_agg(DISTINCT m->>'record_key'),'[]') INTO keys FROM rows;
 old_summary:=astra_ingestion_v1.backfill_shared_summary_v2(t.run_id,keys);
 PERFORM astra_ingestion_v1.backfill_shared_refresh_v2(t.run_id,keys);
 PERFORM astra_ingestion_v1.backfill_shared_apply_delta_v2(t.run_id,old_summary,astra_ingestion_v1.backfill_shared_summary_v2(t.run_id,keys));
 families:=CASE WHEN t.kind='alpaca_actions' THEN ARRAY['N02','N03'] ELSE ARRAY[t.family] END;
 INSERT INTO astra_ingestion_v1.backfill_shared_pages_v2(task_id,page_no,run_id,delivery_families,source_records) VALUES(t.id,p_page,t.run_id,families,p.record_count);
 RETURN jsonb_build_object('state','SHARED_RECORDS_PROJECTED','record_keys_touched',jsonb_array_length(keys),'source_occurrences',p.record_count);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_snapshot_task_v2(p_task_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE t astra_ingestion_v1.backfill_tasks_v2; v_start date; v_end date; v_period daterange; v_member text; v_family text;
 v_added integer; v_map jsonb; v_map_hash text; v_map_valid boolean;
BEGIN
 SELECT * INTO STRICT t FROM astra_ingestion_v1.backfill_tasks_v2 WHERE id=p_task_id;
 IF (t.kind='alpaca_option_bars' AND t.scope ? 'enumeration_parent') OR t.scope ? 'reuse_parent' OR t.scope ? 'identity_refresh_of' OR t.kind IN('retained_identity','retained_massive_archive') THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE task_id=t.id) THEN RETURN false; END IF;
 v_start:=astra_ingestion_v1.backfill_date_v2(t.scope->>'target_start');v_end:=astra_ingestion_v1.backfill_date_v2(t.scope->>'target_end');
 IF v_start IS NOT NULL AND v_end IS NOT NULL AND v_start<=v_end AND t.scope->>'market_timezone'='America/New_York'
  AND GREATEST(v_start,'2025-09-01'::date)<=LEAST(v_end,'2026-07-31'::date) THEN
  v_period:=daterange(GREATEST(v_start,'2025-09-01'::date),LEAST(v_end,'2026-07-31'::date)+1,'[)');
 END IF;
 IF t.family='CTX06' THEN
  v_map:=t.scope->'representative_security';v_map_valid:=false;
  IF jsonb_typeof(v_map)='object' THEN
   v_map_hash:=encode(sha256(convert_to(astra_ingestion_v1.rpc_canonical(v_map),'UTF8')),'hex');
   SELECT count(*)=3000 AND bool_and(m.member_id IS NOT NULL AND jsonb_typeof(x.value)='object' AND length(COALESCE(x.value->>'symbol',''))>0
    AND (NOT x.value ? 'eligible' OR jsonb_typeof(x.value->'eligible') IN ('boolean','null'))) INTO v_map_valid
    FROM jsonb_each(v_map) x LEFT JOIN astra_ingestion_v1.backfill_members_v2 m ON m.run_id=t.run_id AND m.member_id=x.key;
  END IF;
 END IF;
 INSERT INTO astra_ingestion_v1.backfill_plan_units_v2(run_id,task_id,family,definition_sha256,target_period,representative_map_sha256,representative_map_valid)
 VALUES(t.run_id,t.id,t.family,astra_ingestion_v1.backfill_task_definition_sha256_v2(t),v_period,v_map_hash,v_map_valid) ON CONFLICT(task_id) DO NOTHING;
 GET DIAGNOSTICS v_added=ROW_COUNT;
 IF v_added=0 THEN RETURN false; END IF;
 FOR v_family IN SELECT t.family UNION ALL SELECT 'P02' WHERE t.family='P01' AND t.kind IN ('alpaca_stock_bars','retained_reuse') LOOP
  FOR v_member IN SELECT jsonb_array_elements_text(COALESCE(t.scope->'member_ids','[]')) WHERE t.family NOT IN ('REF03','CTX06')
   UNION ALL SELECT '__COHORT__' WHERE t.family='CTX06'
  LOOP
   INSERT INTO astra_ingestion_v1.backfill_plan_coverage_v2(run_id,family,member_id,covered_dates,task_count)
   VALUES(t.run_id,v_family,v_member,CASE WHEN v_period IS NULL THEN '{}'::datemultirange ELSE datemultirange(v_period) END,1)
   ON CONFLICT(run_id,family,member_id) DO UPDATE SET covered_dates=astra_ingestion_v1.backfill_plan_coverage_v2.covered_dates+EXCLUDED.covered_dates,task_count=astra_ingestion_v1.backfill_plan_coverage_v2.task_count+1;
  END LOOP;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_task_guard_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_kind text; v_members jsonb; v_member text;
BEGIN
 IF TG_OP='UPDATE' THEN
   IF NEW.id IS DISTINCT FROM OLD.id OR NEW.run_id IS DISTINCT FROM OLD.run_id OR NEW.family IS DISTINCT FROM OLD.family
    OR NEW.provider IS DISTINCT FROM OLD.provider OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.scope IS DISTINCT FROM OLD.scope
    OR NEW.dependencies IS DISTINCT FROM OLD.dependencies OR NEW.generation<OLD.generation
    OR NEW.requests_reserved<OLD.requests_reserved OR NEW.records_committed<OLD.records_committed OR NEW.page_no<OLD.page_no
    OR NEW.attempts<OLD.attempts OR (OLD.status IN ('INGESTED','NO_DATA_RETURNED','NOT_APPLICABLE','PROVIDER_LIMITATION','IDENTITY_OR_QUALITY_UNRESOLVED','SUPERSEDED_BY_SCOPE_CHANGE') AND NEW.status IS DISTINCT FROM OLD.status)
   THEN RAISE EXCEPTION 'Task scope, cumulative accounting and terminal result are immutable'; END IF;
   RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=NEW.run_id AND status='ACTIVE' AND fence=NEW.run_fence) THEN
   RAISE EXCEPTION 'Task requires current active replacement run'; END IF;
 IF (NEW.kind LIKE 'alpaca_%' AND NEW.provider<>'Alpaca') OR (NEW.kind LIKE 'massive_%' AND NEW.provider<>'Massive')
 OR (NEW.kind LIKE 'derive_%' AND lower(NEW.provider)<>'derived') OR (NEW.kind='retained_reuse' AND lower(NEW.provider)<>'reuse') THEN
   RAISE EXCEPTION 'Task kind and permitted provider disagree'; END IF;
 IF NEW.kind='retained_identity' AND (lower(NEW.provider)<>'reuse' OR NEW.family<>'REF01' OR NEW.scope->'shared_cohort_reference' IS DISTINCT FROM 'true'::jsonb OR NEW.scope->>'cohort_sha256' IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec') THEN RAISE EXCEPTION 'Invalid shared fixed-cohort identity source'; END IF;
 IF NEW.kind='retained_massive_archive' AND (NEW.family<>'S02' OR lower(NEW.provider)<>'reuse' OR NEW.scope->'preserve_provider_acquisition' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'Invalid retained S02 overlay';END IF;
 v_members:=NEW.scope->'member_ids';
 IF NEW.family NOT IN ('CTX06','REF03') AND NEW.kind<>'retained_identity' AND (jsonb_typeof(v_members) IS DISTINCT FROM 'array' OR jsonb_array_length(v_members)=0) THEN
   RAISE EXCEPTION 'Member-scoped work requires frozen member identifiers'; END IF;
 IF v_members IS NOT NULL THEN
   IF jsonb_typeof(v_members) IS DISTINCT FROM 'array' OR jsonb_array_length(v_members)>3000 THEN RAISE EXCEPTION 'Invalid member scope'; END IF;
   FOR v_member IN SELECT jsonb_array_elements_text(v_members) LOOP
     IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_members_v2 WHERE run_id=NEW.run_id AND member_id=v_member) THEN
       RAISE EXCEPTION 'Task member is outside the frozen cohort'; END IF;
   END LOOP;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_try_finalize_v2(p_run_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE r astra_ingestion_v1.backfill_runs_v2; v_state text; v_gaps boolean; v_coverage_unknown boolean; v_plan astra_ingestion_v1.backfill_plan_manifests_v2;
BEGIN
 SELECT * INTO r FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=p_run_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='AI004',MESSAGE='Replacement run does not exist'; END IF;
 IF r.status IN ('COMPLETE','COMPLETE_WITH_DOCUMENTED_GAPS','SUPERSEDED','PAUSED') THEN RETURN jsonb_build_object('state',r.status); END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_discovered_members_v2 WHERE run_id=r.id AND NOT complete) THEN RETURN jsonb_build_object('state','IDENTITY_SOURCE_DISCOVERY_PENDING'); END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_refresh_v2 WHERE run_id=r.id) THEN RETURN jsonb_build_object('state','IDENTITY_RECOMPUTATION_PENDING'); END IF;
 IF r.metadata->'planning_complete' IS DISTINCT FROM 'true'::jsonb THEN RETURN jsonb_build_object('state','PLANNING_INCOMPLETE'); END IF;
 SELECT * INTO v_plan FROM astra_ingestion_v1.backfill_plan_manifests_v2 WHERE run_id=r.id;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','FULL_PLAN_NOT_SEALED'); END IF;

 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=r.id AND status IN ('PENDING','RUNNING','RETRY_WAIT')) THEN
  RETURN jsonb_build_object('state','WORK_REMAINS'); END IF;
 -- bounded_delivery_completion_check_v2: whole-plan count only after runnable work is exhausted.
 IF (SELECT count(*) FROM astra_ingestion_v1.backfill_plan_units_v2 WHERE run_id=r.id AND recorded_at<=v_plan.sealed_at)<>v_plan.expected_task_count THEN
  RETURN jsonb_build_object('state','EXPECTED_PLAN_UNITS_DIFFER'); END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_family_status_v2 WHERE run_id=r.id AND family<>'REF03' AND planned_units=0) THEN
  RETURN jsonb_build_object('state','REQUIRED_FAMILY_NOT_PLANNED'); END IF;
 IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=r.id AND status='OPERATIONAL_ERROR') THEN v_state:='PARTIAL_OPERATIONAL_FAILURE';
 ELSIF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=r.id AND status='BLOCKED_EXTERNAL') THEN v_state:='BLOCKED_EXTERNAL';
 ELSIF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_pages_v2 p WHERE p.run_id=r.id AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 v WHERE v.task_id=p.task_id AND v.page_no=p.page_no)) THEN
  RETURN jsonb_build_object('state','READBACK_PENDING');
 ELSE
  IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_nonminute_pages_v2 n WHERE n.run_id=r.id AND n.kind IN('alpaca_news','massive_news','alpaca_actions','massive_dividends','massive_splits','alpaca_option_contracts','alpaca_option_bars') AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_shared_pages_v2 s WHERE s.task_id=n.task_id AND s.page_no=n.page_no)) THEN RETURN jsonb_build_object('state','SHARED_RECORD_PROJECTION_PENDING');END IF;
  IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 b JOIN astra_ingestion_v1.backfill_tasks_v2 t ON t.id=b.task_id WHERE b.run_id=r.id AND t.kind='alpaca_option_contracts' AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_contract_enumeration_v2 e WHERE e.task_id=b.task_id AND e.page_no=b.page_no AND e.processed_at IS NOT NULL)) THEN RETURN jsonb_build_object('state','CONTRACT_WORK_ADMISSION_PENDING');END IF;
  v_coverage_unknown:=r.metadata->'applicable_data_coverage_established' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_typeof(r.metadata->'coverage_evidence') IS DISTINCT FROM 'object'
   OR COALESCE(r.metadata#>>'{coverage_evidence,report_sha256}','') !~ '^[0-9a-f]{64}$'
   OR length(COALESCE(r.metadata#>>'{coverage_evidence,evidence_ref}',''))<8
   OR r.metadata#>>'{coverage_evidence,cohort_sha256}' IS DISTINCT FROM r.cohort_sha256
   OR r.metadata#>>'{coverage_evidence,instruction_sha256}' IS DISTINCT FROM r.instruction_sha256
   OR astra_ingestion_v1.backfill_stamp_v2(r.metadata#>>'{coverage_evidence,verified_at}') IS NULL
   OR astra_ingestion_v1.backfill_stamp_v2(r.metadata#>>'{coverage_evidence,verified_at}')<COALESCE(r.last_progress_at,r.created_at)
   OR astra_ingestion_v1.backfill_stamp_v2(r.metadata#>>'{coverage_evidence,verified_at}')>clock_timestamp();
  SELECT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_tasks_v2 WHERE run_id=r.id AND status<>'INGESTED')
   OR EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_readbacks_v2 WHERE run_id=r.id AND unclassified_session_records>0) INTO v_gaps;
  v_gaps:=v_gaps OR EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_shared_counts_v2 WHERE run_id=r.id AND (conflicts>0 OR fallback_keys>0));
  v_state:=CASE WHEN v_gaps OR v_coverage_unknown THEN 'COMPLETE_WITH_DOCUMENTED_GAPS' ELSE 'COMPLETE' END;
 END IF;
 IF r.status<>v_state THEN
  UPDATE astra_ingestion_v1.backfill_runs_v2 SET status=v_state,metadata=metadata||jsonb_build_object('work_disposition',v_state,'work_disposition_at',clock_timestamp(),'coverage_policy','Observed source and calculation outcomes remain distinct from research coverage certification','coverage_disposition_reason',CASE WHEN v_coverage_unknown THEN 'APPLICABLE_DATA_COVERAGE_NOT_ESTABLISHED' WHEN v_gaps THEN 'DOCUMENTED_UNIT_OR_SESSION_GAPS' ELSE 'APPLICABLE_DATA_COVERAGE_EVIDENCED' END) WHERE id=r.id;
  INSERT INTO astra_ingestion_v1.backfill_audit_v2(run_id,action,evidence) VALUES(r.id,'RUN_DISPOSITION',jsonb_build_object('state',v_state,'planning_complete',true,'fixed_member_count',3000,'coverage_unknown',v_coverage_unknown,'coverage_evidence',r.metadata->'coverage_evidence'));
 END IF;
 RETURN jsonb_build_object('state',v_state);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_uri_component_v2(v text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE i integer:=1; b bytea:=''::bytea; c text;
BEGIN
 WHILE i<=length(v) LOOP
  c:=substr(v,i,1);
  IF c='%' THEN
   IF substr(v,i+1,2)!~'^[0-9A-Fa-f]{2}$' THEN RAISE EXCEPTION 'Invalid source cursor encoding'; END IF;
   b:=b||decode(substr(v,i+1,2),'hex');i:=i+3;
  ELSE b:=b||convert_to(CASE WHEN c='+' THEN ' ' ELSE c END,'UTF8');i:=i+1;
  END IF;
 END LOOP;
 RETURN convert_from(b,'UTF8');
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.rpc_canonical(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE v_result text;
BEGIN
  CASE pg_catalog.jsonb_typeof(p_value)
  WHEN 'object' THEN
    SELECT '{' || COALESCE(pg_catalog.string_agg(astra_ingestion_v1.rpc_ascii_string(k) || ':' || astra_ingestion_v1.rpc_canonical(v),',' ORDER BY k COLLATE "C"),'') || '}'
      INTO v_result FROM pg_catalog.jsonb_each(p_value) e(k,v);
  WHEN 'array' THEN
    SELECT '[' || COALESCE(pg_catalog.string_agg(astra_ingestion_v1.rpc_canonical(v),',' ORDER BY i),'') || ']'
      INTO v_result FROM pg_catalog.jsonb_array_elements(p_value) WITH ORDINALITY e(v,i);
  WHEN 'string' THEN v_result := astra_ingestion_v1.rpc_ascii_string(p_value #>> '{}');
  ELSE v_result := p_value::text;
  END CASE;
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.rpc_dispatch(p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '10s'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
 v_headers jsonb; v_claims jsonb; v_token text; v_actor text; v_credential text; v_now double precision;
 v_result jsonb; v_spec jsonb; v_hash text; v_id text; v_key text; v_action text; v_claim jsonb; v_owned jsonb;
 v_job astra_ingestion_v1.jobs%ROWTYPE; v_part astra_ingestion_v1.partitions%ROWTYPE;
 v_start timestamptz; v_end timestamptz; v_cursor timestamptz; v_until timestamptz; v_symbol text;
 v_worker text; v_lease integer; v_phase text; v_status text; v_verification text; v_next double precision;
 v_raw text; v_parsed jsonb; v_record jsonb; v_payload_text text; v_previous text; v_count integer; v_bytes integer; v_page_token text;
 v_failures integer; v_delay double precision; v_proposed double precision; v_retry boolean; v_reason text; v_errcode text; v_errmessage text;
BEGIN
  -- A machine endpoint: an anonymous gateway context is necessary, but never
  -- sufficient. Independent scoped capability authentication happens here, so
  -- calling this private function directly cannot bypass the check.
  v_headers:=NULLIF(pg_catalog.current_setting('request.headers',true),'')::jsonb;
  v_claims:=NULLIF(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb;
  v_token:=v_headers->>'x-astra-ingestion-token';
  IF pg_catalog.current_setting('role',true) IS DISTINCT FROM 'anon'
     OR v_claims->>'role' IS DISTINCT FROM 'anon'
     OR (v_claims->>'sub') IS NOT NULL
     OR NULLIF(pg_catalog.current_setting('request.jwt.claim.sub',true),'') IS NOT NULL
     OR pg_catalog.current_setting('request.method',true) IS DISTINCT FROM 'POST'
     OR pg_catalog.jsonb_typeof(v_headers->'x-astra-ingestion-token') IS DISTINCT FROM 'string'
     OR v_token !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE='PT401',MESSAGE='Ingestion capability authentication required';
  END IF;
  v_credential:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_token,'UTF8')),'hex');
  SELECT actor INTO v_actor FROM astra_ingestion_v1.runtime_credentials
    WHERE token_sha256=v_credential AND revoked_at IS NULL AND expires_at>pg_catalog.clock_timestamp();
  IF v_actor IS NULL THEN RAISE EXCEPTION USING ERRCODE='PT401',MESSAGE='Ingestion capability authentication required'; END IF;
  IF p_operation IS NULL OR NOT (p_operation='health' OR (v_actor='api' AND p_operation IN ('list_jobs','get_job','submit_job','control_job','backfill_status','backfill_delivery_status'))
     OR (v_actor='worker' AND p_operation IN ('claim_next','reserve_request','commit_page','verification_material','finish_verification','fail_claim','backfill_status','backfill_claim','backfill_reserve','backfill_commit','backfill_defer','backfill_verify','backfill_material','backfill_work','backfill_relay_probe','backfill_relay_dispatch','backfill_massive_archive_read','backfill_massive_archive_commit','backfill_massive_archive_verify','backfill_identity_material','backfill_identity_source_read','backfill_identity_source_commit','backfill_identity_refresh','backfill_breadth_material','backfill_breadth_project','backfill_delivery_status','backfill_finalize','backfill_recover','backfill_maintain','backfill_plan_snapshot','backfill_seal_plan','backfill_plan_next','backfill_reuse_read','backfill_feature_reuse_commit','backfill_feature_reuse_verify','backfill_reuse_verify','backfill_reuse_commit'))) THEN
    RAISE EXCEPTION USING ERRCODE='PT403',MESSAGE='Operation is outside this capability';
  END IF;
  IF pg_catalog.jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR pg_catalog.octet_length(p_payload::text)>8388608 THEN
    RAISE EXCEPTION USING ERRCODE='PT400',MESSAGE='A bounded operation object is required';
  END IF;
  -- Authentication precedes the global lock. Never accept SQL, identifiers,
  -- function names, destinations or schema choices from the caller.
  PERFORM pg_catalog.pg_advisory_xact_lock(706314020261028);
  IF NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.runtime_credentials WHERE token_sha256=v_credential AND actor=v_actor AND revoked_at IS NULL AND expires_at>pg_catalog.clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='PT401',MESSAGE='Ingestion capability authentication required';
  END IF;
  -- All mutating operations are in this exception subtransaction. An expected
  -- error rolls back its effects before the safe error envelope is returned.
  BEGIN
    v_now:=EXTRACT(EPOCH FROM pg_catalog.clock_timestamp());

    -- replacement_scope_admission_gate_v2: authenticated, serialized, immutable old scope.
    IF p_operation='submit_job' THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'error',pg_catalog.jsonb_build_object(
        'code','conflict','message','SUPERSEDED_BY_SCOPE_CHANGE: replacement fixed-cohort run owns new admission'));
    ELSIF p_operation='claim_next' THEN
      RETURN pg_catalog.jsonb_build_object('ok',true,'result',NULL);
    END IF;

    -- backfill_runtime_dispatch_v2: follows capability authentication and shared transaction lock.


    -- backfill_full_plan_hook_v2: bounded static admission, same authenticated worker.
    IF p_operation='backfill_plan_next' THEN
      RETURN jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_plan_next_v2(p_payload));
    END IF;
    -- backfill_delivery_dispatch_hook_v2: same capability guard and transaction lock.
    IF p_operation IN ('backfill_status','backfill_verify','backfill_delivery_status','backfill_finalize','backfill_recover','backfill_maintain','backfill_plan_snapshot','backfill_seal_plan','backfill_plan_next') THEN
      RETURN jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_delivery_dispatch_v2(p_operation,p_payload));
    END IF;

    -- backfill_managed_relay_hook_v2: after worker-only capability checks and existing global lock.
    IF p_operation IN ('backfill_relay_probe','backfill_relay_dispatch') THEN
      RETURN jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_relay_v2(p_operation,p_payload));
    END IF;
    IF p_operation LIKE 'backfill_%' THEN
      RETURN pg_catalog.jsonb_build_object('ok',true,'result',astra_ingestion_v1.backfill_dispatch_v2(p_operation,p_payload));
    END IF;
    CASE p_operation
    WHEN 'health' THEN
      IF NOT astra_ingestion_v1.rpc_keys(p_payload,ARRAY[]::text[]) THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Unexpected health parameters'; END IF;
      IF (SELECT version FROM astra_ingestion_v1.schema_info WHERE id=1) IS DISTINCT FROM 1 THEN RAISE EXCEPTION USING ERRCODE='AI005',MESSAGE='Schema migration required'; END IF;
      v_result:=pg_catalog.jsonb_build_object('ready',true,'schema_version',1,'rpc_version',1);
    WHEN 'list_jobs' THEN
